-- 0011_db_native_content.sql — PROJECT DBNATIVE, slice 1: the flagship
-- wikis' PAGE CONTENT moves into the database. Every extracted live page
-- (Taco Bell ×16 · Apple ×7) lands as section rows + ONE published
-- revision, so the reader (/read/<wiki>/<page>) serves it like any
-- originated wiki — same renderer, same canon CSS, cache-until-edited.
-- GENERATED by _builder/scripts/gen-db-native-sql.mjs from the extraction
-- output (which derives from the pages' own front matter). Idempotent, and
-- SAFE for builder work: a page that already has rows in the database is
-- left untouched — the backfill fills only pages the DB doesn't hold yet.
-- (The revision/pointer block reuses 0004's backfill pattern.)

-- ── taco-bell / taco-bell-home (2 sections) ──
insert into public.pages (wiki_id, id, slug, title, type) values
  ('taco-bell', 'taco-bell-home', 'taco-bell.html', 'Taco Bell', 'home')
on conflict (wiki_id, id) do update set slug = excluded.slug, title = excluded.title, type = excluded.type;
insert into public.sections (wiki_id, page_id, position, component, data)
select * from (values
  ('taco-bell', 'taco-bell-home', 0, 'hero', '{"eyebrow":"Visual Wiki · Vol. 1","title":"Taco Bell","subtitle":null,"subtitle_meta":null,"desc":"Every menu item, every limited-time release, every sauce-packet quote — the Live Más canon, indexed and illustrated since 1962.","stats":[{"num":"1,284","label":"entries"},{"num":"1962","label":"since"},{"num":"7,200+","label":"stores"},{"num":"31","label":"countries"}],"search":true,"search_placeholder":"Search 1,284 entries — try ''Crunchwrap'' or ''Baja Blast''…","spotlight":{"eyebrow":"★ Spotlight","title":"Cantina Chicken Menu","desc":"Five new items built around slow-roasted, marinated chicken — including the Cantina Chicken Crispy Taco and a quesadilla with avocado verde sauce.","tags":["2024","Limited","5 items"],"cta":"Open entry →"},"feature":null}'::jsonb),
  ('taco-bell', 'taco-bell-home', 1, 'overview', '{"tone":"b","heading":"An American chain that invented its own genre.","paragraphs":["<strong>Taco Bell</strong> is an American fast-food chain founded in 1962 by <strong>Glen Bell</strong> in Downey, California. Built on a single observation — that long lines at the Mexican restaurant across the street meant Americans wanted tacos faster — it became the country''s largest Mexican-inspired quick-service chain and the only one to operate at national scale.","More than a restaurant, Taco Bell functions as a cultural laboratory: a permanent menu of roughly 30 items rotated against a relentless churn of <a href=\"#\" class=\"underline decoration-[var(--neon)] underline-offset-2\">limited-time releases</a>, novelty crossovers (Doritos, Mountain Dew, Cheetos), and viral comebacks (Mexican Pizza, Volcano Menu). The chain pioneered the fourthmeal — a marketing-coined late-night occasion — and the concept of fast food as <em>fan culture</em>, complete with petitions, merch drops, and a musical.","Today the company operates over 7,200 restaurants across 31 countries under <strong>Yum! Brands</strong>, alongside KFC and Pizza Hut. Its reach extends well beyond the menu: into film cameos, sauce-packet fortune cookies, hotel residencies, a clothing line, and the only fast-food brand with a <em>nail polish collection</em>."],"infobox":{"label":null,"title":"Taco Bell Corp.","sublabel":null,"rows":[["Founder","Glen Bell"],["Founded","March 21, 1962"],["Origin","Downey, California, U.S."],["Headquarters","Irvine, California, U.S."],["Industry","Fast food restaurants"],["Cuisine","Tex-Mex / Cal-Mex"],["Locations","7,200+ (2024)"],["Areas served","Worldwide (31 countries)"],["Key people","Sean Tresvant (CEO)"],["Revenue","US$13.8B (system, 2023)"],["Parent","Yum! Brands"],["Slogan","Live Más"],["Mascot (former)","Gidget the Chihuahua"]],"badge":null}}'::jsonb)
) as v(wiki_id, page_id, position, component, data)
where not exists (select 1 from public.sections s
  where s.wiki_id = 'taco-bell' and s.page_id = 'taco-bell-home');

-- ── taco-bell / taco-bell-drinks (3 sections) ──
insert into public.pages (wiki_id, id, slug, title, type) values
  ('taco-bell', 'taco-bell-drinks', 'taco-bell-drinks.html', 'Drinks', 'standard')
on conflict (wiki_id, id) do update set slug = excluded.slug, title = excluded.title, type = excluded.type;
insert into public.sections (wiki_id, page_id, position, component, data)
select * from (values
  ('taco-bell', 'taco-bell-drinks', 0, 'hero', '{"eyebrow":"Beverage · Fountain · Freeze","title":"Drinks","subtitle":null,"subtitle_meta":null,"desc":"One Mountain Dew exclusive that became a cult, three Freeze valves, four Pepsi standards, and roughly 24 million tropical-lime cups poured each year. Indexed, charted, and pour-tested.","stats":[{"num":"~24M","label":"Baja cups / yr"},{"num":"2004","label":"Baja Blast debut"},{"num":"77 g","label":"sugar · 20oz Baja"},{"num":"1997","label":"Pepsi since"}],"search":false,"search_placeholder":null,"spotlight":null,"feature":{"bg":"linear-gradient(to bottom right,#22d3ee,#065f46)","head_left":"★ Flagship · Spotlight","head_right":"Est. 2004","title":"Baja Blast","desc":"The Mountain Dew variant engineered specifically to pair with Taco Bell food. Tropical lime, fluorescent cyan, exclusive to the chain at the fountain since launch.","chips":[{"key":"Cal","val":"290"},{"key":"Sugar","val":"77 g"},{"key":"Caffeine","val":"92 mg"}]}}'::jsonb),
  ('taco-bell', 'taco-bell-drinks', 1, 'overview', '{"tone":"a","heading":"The only fast-food chain whose drink is its own brand.","paragraphs":["<strong>Taco Bell''s beverage program</strong> is anchored by a single product nobody else can sell: <strong>Mountain Dew Baja Blast</strong>. Co-developed by PepsiCo and Taco Bell flavor R&amp;D in 2003 and launched in February 2004, it is the only Mountain Dew variant manufactured exclusively for a single restaurant chain — and it transformed Taco Bell from a Pepsi licensee into a beverage destination in its own right.","The full lineup divides into six families: the <strong>Baja</strong> products (carbonated, freeze, and the growing retail bottle line), the <strong>Freeze wall</strong> (slushed Mountain Dew variants — currently Baja, Wild Cherry, and a rotating third valve), <strong>fountain Pepsi</strong> standards, the <strong>Brisk × Taco Bell</strong> juice and tea pairings, the <strong>breakfast coffee</strong> program introduced in 2014, and a small slate of bottled cooler drinks. The fountain has been all-Pepsi since the 1997 Tricon spinoff that created what is now <em>Yum! Brands</em>.","Taken together, drinks generate roughly 18% of an average store''s revenue and a disproportionate share of its margin — Baja Blast alone has been credited with carrying entire product launches (notably the Crunchwrap and Mexican Pizza relaunches), and the freezer-aisle bottle release has become its own annual cultural event."],"infobox":{"label":null,"title":"Drinks Program","sublabel":null,"rows":[["Categories","6 families"],["Active SKUs","14 on menu"],["Hero product","Baja Blast (since 2004)"],["Pepsi exclusive","1997–present"],["Freeze supplier","Taylor Company"],["Coffee certif.","Rainforest Alliance"],["Retail bottle","Permanent (2020)"],["Annual Baja vol.","≈ 24M cups, U.S."],["Discontinued","6 known SKUs"],["See also","Mountain Dew, Yum! Brands"]],"badge":null}}'::jsonb),
  ('taco-bell', 'taco-bell-drinks', 2, 'catalog', '{"title":"Every active drink","unit":"drink","visual":"catalog","tone":"b","footnote":"Pricing reflects medium fountain sizes at standard U.S. company stores; franchise and regional pricing varies. Limited-time and dirty-soda items rotate.","categories":[{"name":"Mountain Dew","color":1,"items":[{"name":"Mountain Dew","info":"$3.19","desc":"Citrus soda. PepsiCo flagship brand."},{"name":"Mountain Dew Zero Sugar","info":"$3.19","desc":"Zero-sugar Mountain Dew."},{"name":"MTN DEW Baja Blast","info":"$3.19","desc":"Tropical lime Dew. Created as a Taco Bell exclusive in 2004. Became a permanent retail flavor in January 2024 for the 20th Bajaversary."},{"name":"Baja Blast Zero Sugar","info":"$3.19","desc":"Zero-sugar Baja Blast. Added to the Taco Bell fountain in 2019."},{"name":"MTN DEW Baja Midnight","info":"$3.19","desc":"Passionfruit and tropical lime Dew. Dark purple. Launched August 14, 2025 as a permanent Taco Bell exclusive — the first expansion of the Baja Blast lineup in 20 years."},{"name":"Baja Midnight Zero Sugar","info":"$3.19","desc":"Zero-sugar Baja Midnight. Announced at Live Más Live 2026 for release in 2026."}]},{"name":"Fountain Sodas","color":2,"items":[{"name":"Pepsi","info":"$3.19","desc":"Classic PepsiCo cola."},{"name":"Diet Pepsi","info":"$3.19","desc":"Zero-calorie Pepsi variant."},{"name":"Pepsi Zero Sugar","info":"$3.19","desc":"Zero-sugar Pepsi with bolder flavor profile."},{"name":"Cherry Pepsi","info":"$3.19","desc":"Cherry-flavored Pepsi."},{"name":"Dr Pepper","info":"$3.19","desc":"23-flavor cola."},{"name":"Starry","info":"$3.19","desc":"Lemon-lime soda. Replaced Sierra Mist in 2023."},{"name":"Mug Root Beer","info":"$3.19","desc":"PepsiCo root beer brand."}]},{"name":"Dirty Sodas","color":3,"items":[{"name":"Dirty Baja Blast","info":"$3.49","desc":"Baja Blast with vanilla sweet cream. Went viral via TikTok in Oct 2024. Made permanent March 19, 2026."},{"name":"Dirty Baja Blast Zero Sugar","info":"$3.49","desc":"Zero-sugar Baja Blast with vanilla sweet cream. Permanent since March 2026."},{"name":"Dirty Baja Midnight","info":"$3.49","desc":"Baja Midnight with vanilla sweet cream. Purple dirty soda. Launched March 19, 2026."},{"name":"Pepsi Dirty Soda","info":"$3.49","desc":"Pepsi with vanilla sweet cream. 430 cal."},{"name":"Dirty Lemonade","info":"$3.49","desc":"Tropicana lemonade with vanilla sweet cream. 170 cal."}]},{"name":"Freezes","color":4,"items":[{"name":"Pink Passionfruit Refresca Freeze","info":"$3.49","desc":"Passionfruit Refresca as a freeze. Limited time. Launched March 19, 2026."},{"name":"Mountain Dew Baja Blast Freeze","info":"$3.49","desc":"Frozen Baja Blast slush. Permanent menu item since 2012. Anchor of Freeze Slot 1."},{"name":"Blue Raspberry Freeze","info":"$3.49","desc":"Blue raspberry frozen slush. Limited time."}]},{"name":"Agua Refrescas","color":5,"items":[{"name":"Strawberry Passionfruit Refresca","info":"$3.89","desc":"Fruit-flavored agua fresca. 170 cal."},{"name":"Mango Peach Refresca","info":"$3.89","desc":"Mango and peach agua fresca. 170 cal."},{"name":"Dragonfruit Berry Refresca","info":"$3.89","desc":"Dragonfruit and berry agua fresca. New for 2026."},{"name":"Rockstar Tropical Punch Refresca","info":"$4.49","desc":"Energy refresca with 200mg caffeine. 80 cal."},{"name":"Rockstar Pineapple Lime Refresca","info":"$4.49","desc":"Energy refresca with 200mg caffeine. 50 cal."}]},{"name":"Non-Carbonated Fountain Drinks","color":6,"items":[{"name":"Brisk Mango Fiesta","info":"$3.19","desc":"Mango-flavored iced tea. On the fountain since 2013."},{"name":"Lipton Unsweetened Tea","info":"$3.19","desc":"Unsweetened black tea. 0 calories."},{"name":"Dole Lemonade","info":"$3.19","desc":"Classic lemonade."},{"name":"G2 Gatorade Fruit Punch","info":"$3.19","desc":"Low-calorie sports drink. 80 cal."}]},{"name":"Coffee","color":7,"items":[{"name":"Premium Hot Coffee","info":"$1.99","desc":"Brewed hot coffee."},{"name":"Hot Cinnabon Delights Coffee","info":"$2.29","desc":"Cinnabon-flavored hot coffee."},{"name":"Regular Iced Coffee","info":"$1.99","desc":"Iced brewed coffee."},{"name":"Iced Cinnabon Delights Coffee","info":"$2.29","desc":"Cinnabon-flavored iced coffee."}]},{"name":"Bottled Drinks","color":8,"items":[{"name":"Tropicana Orange Juice","info":"$1.99","desc":"Bottled Tropicana OJ."},{"name":"Aquafina Water","info":"$1.99","desc":"Bottled water."}]}]}'::jsonb)
) as v(wiki_id, page_id, position, component, data)
where not exists (select 1 from public.sections s
  where s.wiki_id = 'taco-bell' and s.page_id = 'taco-bell-drinks');

-- ── taco-bell / taco-bell-discontinued-drinks (3 sections) ──
insert into public.pages (wiki_id, id, slug, title, type) values
  ('taco-bell', 'taco-bell-discontinued-drinks', 'taco-bell-discontinued-drinks.html', 'Discontinued Drinks', 'standard')
on conflict (wiki_id, id) do update set slug = excluded.slug, title = excluded.title, type = excluded.type;
insert into public.sections (wiki_id, page_id, position, component, data)
select * from (values
  ('taco-bell', 'taco-bell-discontinued-drinks', 0, 'hero', '{"eyebrow":"Discontinued · Archive · From the Vault","title":"Discontinued<br>Drinks","subtitle":null,"subtitle_meta":null,"desc":"Sixty-plus drinks that didn''t survive — from pre-Pepsi Coca-Cola valves to last season''s Freeze pull. Six categories, five decades, every item charted on a shared timeline.","stats":[{"num":"60+","label":"items archived"},{"num":"6","label":"categories"},{"num":"1962","label":"earliest entry"},{"num":"2024","label":"most recent"}],"search":false,"search_placeholder":null,"spotlight":null,"feature":{"bg":"linear-gradient(to bottom right,#c24a8e,#6b1d4e)","head_left":"★ Spotlight","title":"Frutista Freeze","desc":"A premium blended beverage program with real strawberry slices and fruit purée — hand-built per order, ten flavors across nine rotating seasons. Too slow to make, too expensive to staff. Killed by the automated Taylor Freeze machine that replaced it.","chips":[{"key":"Flavors","val":"10"},{"key":"Run","val":"5 years"},{"key":"Killed by","val":"Freeze machine"}]}}'::jsonb),
  ('taco-bell', 'taco-bell-discontinued-drinks', 1, 'overview', '{"tone":"a","heading":"60+ discontinued drinks","paragraphs":["Taco Bell has discontinued more than sixty beverages since the chain first opened in 1962. Some lasted decades. Others survived a single summer. A few were killed before most customers knew they existed. This archive documents every one of them.","What makes Taco Bell''s drink history unusual isn''t the number of casualties — any fast-food chain cycles through products. It''s that nearly all of these drinks died for reasons that had nothing to do with customer demand. They died because a corporate parent changed its soda portfolio overnight. Because a machine was replaced and the old recipes didn''t fit the new hardware. Because a brand partnership expired and the valve was reassigned to the next exclusive. The drinks themselves were often popular right up until the moment they vanished.","The archive spans six categories: Mountain Dew exclusives created specifically for Taco Bell fountains, the entire Frutista Freeze program that ran from 2008 to 2013, more than two dozen Freeze machine LTOs and brand collaborations, hand-mixed Limeade Sparklers, hot beverages from the chain''s brief coffee experiments, iced teas and lemonades that quietly rotated off the menu, and a handful of defunct fountain sodas dating back to the original Coca-Cola era.","Below, you''ll find a full catalog of every item by category, a dedicated section on the Freeze machine''s brand collaborations, and then the deep-dive swim-lane charts that map each drink''s lifespan on a shared timeline. Every item is clickable — tap any pill or card for the full story."],"infobox":null}'::jsonb),
  ('taco-bell', 'taco-bell-discontinued-drinks', 2, 'catalog', '{"title":"Every discontinued drink","unit":"drink","visual":"catalog","tone":"b","categories":[{"name":"Mountain Dew Casualties","color":1,"ribbon":{"text":"Discontinued","tone":"gone"},"items":[{"name":"Sangrita Blast (fountain)","info":"December 2013 – 2017","desc":"A dark red, citrus-punch Mountain Dew created exclusively for Taco Bell fountains. PepsiCo described the flavor as cherry and pomegranate. Launched December 2013 alongside Diet Baja Blast as the first TB-exclusive Dew flavor beyond Baja Blast. Briefly released in retail cans and bottles in summer 2015. Replaced by Spiked Lemonade in 2017.","callout":{"label":"Replaced by","text":"Sweet Lightning took over the dedicated Dew valve at many locations."},"notes":"Available elsewhere? No. Never sold at retail. Existed only as a Taco Bell fountain exclusive. Never brought back despite a vocal fanbase. The closest analog was Baja Midnight, released August 2025.","cta":"/taco-bell-sangrita-blast.html"},{"name":"Diet Baja Blast","info":"December 2013 – early 2015","desc":"The zero-calorie counterpart to Baja Blast, launched December 2013 alongside Sangrita Blast. Held a TB fountain valve for roughly 15 months before Kickstart Orange Citrus replaced it in March 2015. Returned in 2019 as Baja Blast Zero Sugar, which is currently active.","callout":{"label":"Replaced by","text":"The diet valve was reallocated."},"notes":"Available elsewhere? Partially. Baja Blast Zero Sugar appears in seasonal retail cans, but the fountain version is gone. The drink survived the discontinuation — only the \"Diet Baja Blast\" brand name was retired."},{"name":"Mountain Dew AM","info":"May 2012 – ~2013","desc":"A fountain blend of Mountain Dew and orange juice, launched May 2012 as a breakfast exclusive — two years before Taco Bell’s national breakfast rollout. Physically on the fountain all day but restricted to morning hours by menu policy. Disappeared within a year without announcement.","callout":{"label":"Replaced by","text":"Discontinued with the breakfast menu overhaul. The flavor slot was eliminated."},"notes":"Available elsewhere? No. A one-year test product, never sold at retail. The \"AM-only\" restriction was a menu rule, not a hardware limitation. The syrup ran continuously."},{"name":"Kickstart Orange Citrus","info":"March 2015 – mid-2022","desc":"The longest-running Mountain Dew TB fountain exclusive after Baja Blast — seven years on the fountain. Part of the Kickstart line (5% juice, added caffeine). Replaced Diet Baja Blast in March 2015, outlasting two full exclusive flavor cycles before Brisk Dragon Paradise ended its run.","callout":{"label":"Replaced by","text":"The fountain valve was reassigned to other Dew promotional flavors."},"notes":"Available elsewhere? Yes. Kickstart is still sold in cans at gas stations and grocery stores. Seven years is remarkable for a rotating slot. Most TB exclusive Dew flavors lasted one to two."},{"name":"Mtn Dew Spiked Lemonade","info":"2017 – March 2019","desc":"Entirely non-alcoholic — \"spiked\" referred to prickly pear cactus juice. Replaced Sangrita Blast on the fountain in 2017. Also had a brief Freeze run in early 2017 before Strawberry Poppin'' Candy Freeze replaced it in September. The misleading name contributed to consumer confusion and is cited among reasons for its poor performance.","callout":{"label":"Replaced by","text":"Replaced by the next rotating Dew flavor in the dedicated valve cycle."},"notes":"Available elsewhere? No. Briefly in retail cans, now discontinued everywhere. The fountain version outlasted retail cans by over a year, finally replaced by Baja Blast Zero Sugar in March 2019.","cta":"/taco-bell-spiked-lemonade.html"}]},{"name":"Frutista Freezes","color":9,"ribbon":{"text":"Discontinued","tone":"gone"},"items":[{"name":"Strawberry Frutista Freeze","info":"Summer 2008 – late 2013","desc":"One of the two original Frutista Freeze flavors that launched the program in summer 2008. A hand-blended strawberry slush topped with real strawberry slices — the signature Frutista touch.","callout":{"label":"Replaced by","text":"The entire Frutista Freeze line was replaced by the automated Taylor Freeze machine in January 2013."},"notes":"Frutista Freezes were hand-built per order using a commercial blender — too slow and labor-intensive to scale."},{"name":"Mango Strawberry Frutista Freeze","info":"Summer 2008 – late 2013","desc":"The other original launch flavor alongside Strawberry. A tropical mango-strawberry blend that became the most-requested Frutista flavor on fan petitions after the program ended.","callout":{"label":"Replaced by","text":"Replaced by the automated Freeze program in January 2013."},"notes":"Fan nostalgia for this flavor remains strong — TikTok petitions still circulate."},{"name":"Strawberries n Creme Frutista Freeze","info":"Fall 2008","desc":"Part of the three-flavor Crème expansion in fall 2008. Strawberry base blended with a vanilla crème swirl and topped with real strawberry slices.","callout":{"label":"Replaced by","text":"Rotated out as part of the Frutista seasonal cycle."},"notes":"The Crème line was the first seasonal rotation within the Frutista program."},{"name":"Mango n Creme Frutista Freeze","info":"Fall 2008","desc":"Mango base with the same vanilla crème treatment as the Strawberries ’n Crème. Part of the fall 2008 Crème trio.","callout":{"label":"Replaced by","text":"Rotated out seasonally."}},{"name":"Triple Berries n Creme Frutista Freeze","info":"Fall 2008","desc":"A three-berry blend (strawberry, blueberry, raspberry) with vanilla crème. The most complex flavor in the original Crème lineup.","callout":{"label":"Replaced by","text":"Rotated out seasonally."}},{"name":"Pina Colada Frutista Freeze","info":"Spring 2009","desc":"Pineapple-coconut frozen blend launched in spring 2009 alongside Strawberry Colada. One of the most fondly remembered Frutista flavors — copycat recipes still circulate online.","callout":{"label":"Replaced by","text":"Rotated out seasonally. A non-Frutista Piña Colada Freeze briefly appeared in January 2013 during the transition."},"notes":"Copycat recipes remain popular on food blogs.","cta":"/taco-bell-pina-colada-frutista.html"},{"name":"Strawberry Colada Frutista Freeze","info":"Spring 2009","desc":"Strawberry meets coconut — the companion flavor to Piña Colada in the spring 2009 tropical rotation.","callout":{"label":"Replaced by","text":"Rotated out seasonally."}},{"name":"Strawberry Lemonade Frutista Freeze","info":"Fall 2009","desc":"A strawberry-lemonade blend introduced in fall 2009. Reviewed by Brand Eating in November 2009.","callout":{"label":"Replaced by","text":"Rotated out seasonally."},"notes":"Source: Brand Eating review, November 2009."},{"name":"Classic Margarita Frutista Freeze","info":"Spring 2010 · returned Spring 2011","desc":"A non-alcoholic frozen margarita introduced in spring 2010. Popular enough to return for a second spring season in 2011.","callout":{"label":"Replaced by","text":"Rotated out after 2011 season."},"notes":"One of only two Frutista flavors to get a second-season return."},{"name":"Strawberry Margarita Frutista Freeze","info":"Spring 2010","desc":"The strawberry companion to the Classic Margarita, launched alongside it in spring 2010.","callout":{"label":"Replaced by","text":"Rotated out seasonally."}},{"name":"Orange n Creme Swirl Frutista Freeze","info":"Fall 2010","desc":"An orange cream–flavored Frutista introduced in fall 2010. Reviewed by Brand Eating in October 2010.","callout":{"label":"Replaced by","text":"Rotated out seasonally."},"notes":"Source: Brand Eating review, October 2010."},{"name":"Berry Pomegranate Frutista Freeze","info":"January 2011","desc":"A berry-pomegranate blend introduced in January 2011. One of the later Frutista seasonal flavors.","callout":{"label":"Replaced by","text":"Rotated out seasonally."},"notes":"Source: Brand Eating news, January 2011."},{"name":"Cherry Creme Frutista Freeze","info":"~2011–2012","desc":"A cherry cream–flavored Frutista Freeze featured by Foodbeast. One of the final flavors in the Frutista program before the transition to automated Freezes in January 2013.","callout":{"label":"Replaced by","text":"The entire Frutista program ended in late 2012/early 2013."},"notes":"Source: Foodbeast feature."}]},{"name":"Freezes","color":10,"ribbon":{"text":"Discontinued","tone":"gone"},"items":[{"name":"Pink Lemonade","info":"January – September 2013","desc":"One of the two original launch flavors when the modern Freeze program began in January 2013. Co-ran with Piña Colada until the House of Dew expansion in September 2013 replaced both.","callout":{"label":"Replaced by","text":"Rotated out at the end of its LTO window. The Freeze machine’s third slot cycles to the next seasonal flavor."}},{"name":"Piña Colada","info":"January – September 2013","desc":"Co-launched with Pink Lemonade in January 2013. Previously appeared as a Frutista Freeze in Spring 2009. Replaced by Typhoon when the House of Dew flavors launched in September 2013.","callout":{"label":"Replaced by","text":"Rotated out as part of the Frutista seasonal cycle."},"cta":"/taco-bell-pina-colada-frutista.html"},{"name":"Watermelon","info":"2016, 2017, 2018, 2020, 2021 (seasonal)","desc":"One of the most reliably returning seasonal Freezes — appeared across at least five summers before stopping its rotation. Functioned almost like an unofficial seasonal permanent before being discontinued.","callout":{"label":"Replaced by","text":"Rotated out at the end of its LTO window. The Freeze machine’s third slot cycles to the next seasonal flavor."}},{"name":"Wild Strawberry","info":"2017 – 2023 (seasonal returns)","desc":"Taco Bell’s own house strawberry Freeze, distinct from the Starburst candy collabs. One of the most common recurring entries in the third-slot rotation, appearing across multiple years.","callout":{"label":"Replaced by","text":"Rotated out at the end of its LTO window. The Freeze machine’s third slot cycles to the next seasonal flavor."}},{"name":"Lemonade","info":"~2018","desc":"A straightforward lemonade Freeze from 2018, one of several house-flavor experiments during a period between candy and Dew collab cycles.","callout":{"label":"Replaced by","text":"Rotated out at the end of its LTO window. The Freeze machine’s third slot cycles to the next seasonal flavor."}},{"name":"Dragonfruit","info":"2022","desc":"Discontinued mid-run when the syrup supply ended, stranding customers without warning. One of the more abrupt discontinuations in the LTO calendar.","callout":{"label":"Replaced by","text":"Rotated out at the end of its LTO window. The Freeze machine’s third slot cycles to the next seasonal flavor."},"notes":"The syrup supply issue, rather than poor performance, appears to have ended this one early."},{"name":"Tropical Mango","info":"2022","desc":"A mango-forward tropical Freeze from 2022, part of a period when Taco Bell was testing fruit-forward flavors alongside the Agua Refresca line expansion.","callout":{"label":"Replaced by","text":"Rotated out at the end of its LTO window. The Freeze machine’s third slot cycles to the next seasonal flavor."}},{"name":"Blue Raspberry*","info":"2022 (LTO) → permanent","desc":"Began as a rotating LTO in 2022 before being elevated to a permanent slot. The asterisk marks its transition from the rotating third slot to a consistent fixture.","callout":{"label":"Replaced by","text":"Rotated out at the end of its LTO window. The Freeze machine’s third slot cycles to the next seasonal flavor."},"notes":"One of the rare cases of an LTO flavor graduating out of the rotating slot entirely."},{"name":"Strawberry Refresca","info":"2023","desc":"A Freeze tied to Taco Bell’s 2023 Agua Refresca launch — part of the chain''s push toward fruit-infused, lower-carbonation drink options.","callout":{"label":"Replaced by","text":"Rotated out at the end of its LTO window. The Freeze machine’s third slot cycles to the next seasonal flavor."}},{"name":"Vanilla Cream Soda","info":"2023 – 2024","desc":"One of Taco Bell’s most widely discussed drink launches of 2023. Opened a cream soda flavor direction for the LTO slot that spawned multiple variants across 2023 and 2024.","callout":{"label":"Replaced by","text":"Rotated out at the end of its LTO window. The Freeze machine’s third slot cycles to the next seasonal flavor."}},{"name":"Orange Vanilla Cream Soda","info":"2023 – 2024","desc":"The citrus companion to the Vanilla Cream Soda Freeze — an orange-vanilla hybrid that ran alongside the plain vanilla version across 2023 and 2024.","callout":{"label":"Replaced by","text":"Rotated out at the end of its LTO window. The Freeze machine’s third slot cycles to the next seasonal flavor."}},{"name":"Strawberry Vanilla Cream Soda","info":"2024","desc":"Extension of the cream soda Freeze direction into strawberry flavor, part of the 2024 rotation continuing the vanilla cream soda line introduced in 2023.","callout":{"label":"Replaced by","text":"Rotated out at the end of its LTO window. The Freeze machine’s third slot cycles to the next seasonal flavor."}},{"name":"Confetti Cookie","info":"2024","desc":"A dessert-inspired Freeze with funfetti and cookie flavoring. Available partly as an app rewards exclusive — part of Taco Bell’s growing strategy of soft-launching new Freeze flavors through the loyalty program.","callout":{"label":"Replaced by","text":"Rotated out at the end of its LTO window. The Freeze machine’s third slot cycles to the next seasonal flavor."},"notes":"Represents the app-first rollout strategy where select new items reach rewards members before general availability."},{"name":"Wild Cherry†","info":"~2013 – 2024/2025 (phasing out)","desc":"The long-running second-slot Freeze fixture for nearly a decade, running quietly alongside Baja Blast before Blue Raspberry took over the permanent second slot.","callout":{"label":"Replaced by","text":"Rotated out at the end of its LTO window. The Freeze machine’s third slot cycles to the next seasonal flavor."},"notes":"The dagger symbol marks its transition from semi-permanent to actively phasing out. May still be available at some locations."},{"name":"Starburst Strawberry Freeze","info":"October 2014 · returned 2016, 2019","desc":"A Starburst-branded strawberry Freeze introduced in 2014 as one of the early candy collaborations on the Taylor Freeze machine. Returned for limited runs in 2016 and 2019.","callout":{"label":"Replaced by","text":"Rotated out after each LTO window."},"notes":"One of the first candy brand collabs on the Freeze machine."},{"name":"Starburst Cherry Freeze","info":"September 2015","desc":"A cherry-flavored Starburst Freeze LTO in fall 2015.","callout":{"label":"Replaced by","text":"Rotated out seasonally."}},{"name":"Airheads White Mystery Freeze","info":"September 2016","desc":"The mystery-flavor Airheads candy as a Freeze. A one-season candy collab that never returned.","callout":{"label":"Replaced by","text":"Rotated out after 2016."}},{"name":"Airheads Blue Raspberry Freeze","info":"Late 2016 – 2017","desc":"Blue raspberry Airheads-branded Freeze. The second Airheads collab after White Mystery.","callout":{"label":"Replaced by","text":"Rotated out."}},{"name":"Jolly Rancher Watermelon Freeze","info":"2020","desc":"A watermelon-flavored Jolly Rancher Freeze LTO.","callout":{"label":"Replaced by","text":"Rotated out."}},{"name":"Jolly Rancher Green Apple Freeze","info":"2021","desc":"A green apple Jolly Rancher Freeze LTO.","callout":{"label":"Replaced by","text":"Rotated out."}},{"name":"Mtn Dew Distortion (DEWmocracy II)","info":"September 2013 – March 2014","desc":"A sour lime Mountain Dew from the 2010 DEWmocracy II retail vote. Selected via Taco Bell fan vote for the House of Dew launch, ranking first among new LTO candidates. Replaced by Kickstart Black Cherry in March 2014.","callout":{"label":"Replaced by","text":"Rotated out at the end of its LTO window. The Freeze machine’s third slot cycles to the next seasonal flavor."},"notes":"DEWmocracy II (2010) pitted Distortion, Typhoon, and White Shark against each other in a retail vote. White Shark won. Both Distortion and Typhoon were revived here three years later."},{"name":"Mtn Dew Typhoon (DEWmocracy II)","info":"September 2013 – June 2014","desc":"A tropical punch Mountain Dew from the same DEWmocracy II retail run. Ranked third overall in the House of Dew fan vote — second among new LTO candidates, with Baja Blast (already permanent) holding the #2 slot. Ran slightly longer than Distortion.","callout":{"label":"Replaced by","text":"Rotated out at the end of its LTO window. The Freeze machine’s third slot cycles to the next seasonal flavor."}},{"name":"Mtn Dew Typhoon","info":"Into 2014","desc":"Continuation of the Typhoon Freeze into early 2014. Ran the longest of the two original DEWmocracy flavors before Dr Pepper Vanilla Float Freeze replaced it in June 2014.","callout":{"label":"Replaced by","text":"Rotated out at the end of its LTO window. The Freeze machine’s third slot cycles to the next seasonal flavor."}},{"name":"Mtn Dew Kickstart Black Cherry","info":"March – ~June 2014","desc":"A brief run from the Kickstart line — the black cherry energy variant. Replaced Distortion in March 2014 but lasted only a few months. Among the shortest documented runs in the LTO calendar.","callout":{"label":"Replaced by","text":"Rotated out at the end of its LTO window. The Freeze machine’s third slot cycles to the next seasonal flavor."}},{"name":"Mtn Dew Sangrita Blast","info":"May – September 2015","desc":"The Freeze companion to the Sangrita Blast fountain exclusive. Launched May 2015 and ran one season before Starburst Cherry Freeze took the slot.","callout":{"label":"Replaced by","text":"Rotated out at the end of its LTO window. The Freeze machine’s third slot cycles to the next seasonal flavor."},"notes":"The only time Sangrita Blast existed in Freeze format. The fountain flavor ran 2013–2017; this Freeze appeared and disappeared in four months.","cta":"/taco-bell-sangrita-blast.html"},{"name":"Mtn Dew Spiked Lemonade Freeze","info":"Early – September 2017","desc":"The Freeze companion to the Spiked Lemonade fountain flavor — non-alcoholic, prickly pear cactus juice. Ran briefly in early 2017 before Strawberry Poppin'' Candy Freeze replaced it in September. A much shorter run than the fountain version, which continued until March 2019.","callout":{"label":"Replaced by","text":"Rotated out at the end of its LTO window. The Freeze machine’s third slot cycles to the next seasonal flavor."}},{"name":"Mtn Dew Frostbite","info":"2020","desc":"A coconut-lime Mountain Dew available only as a Freeze — no retail soda version. Blue-green in color. Appeared one season in 2019 and did not return.","callout":{"label":"Replaced by","text":"Rotated out at the end of its LTO window. The Freeze machine’s third slot cycles to the next seasonal flavor."},"notes":"One of the few Dew flavors created specifically for the Freeze machine rather than adapted from a retail product."},{"name":"Mtn Dew Birthday Baja Blast","info":"2019","desc":"Released in 2019 to mark Baja Blast''s 15th anniversary. A variation on the permanent Baja Blast Freeze with birthday cake flavoring — a rare spin-off of the first permanent slot.","callout":{"label":"Replaced by","text":"Rotated out at the end of its LTO window. The Freeze machine’s third slot cycles to the next seasonal flavor."}},{"name":"Mtn Dew Spark","info":"2021 – ~2022","desc":"A pink lemonade-flavored Mountain Dew in Freeze form. Part of the broader Spark product line. Ran in the LTO slot across 2021 and into 2022.","callout":{"label":"Replaced by","text":"Rotated out at the end of its LTO window. The Freeze machine’s third slot cycles to the next seasonal flavor."}},{"name":"Mtn Dew Baja Blast Colada","info":"2021","desc":"A colada-flavored variation on Baja Blast — tropical-lime with coconut cream. Part of the 2021 Summer of Baja promotional push alongside retail Baja Punch and Baja Flash cans.","callout":{"label":"Replaced by","text":"Rotated out at the end of its LTO window. The Freeze machine’s third slot cycles to the next seasonal flavor."},"notes":"One of very few times the Baja Blast formula was modified for a seasonal LTO spin-off."}]},{"name":"Limeade Sparklers","color":11,"ribbon":{"text":"Discontinued","tone":"gone"},"items":[{"name":"Classic Limeade Sparkler","info":"~2010 – 2012","desc":"A made-to-order drink built from Sierra Mist, lime juice concentrate, and a real lime wedge in a clear plastic cup so the carbonation was visible. Taco Bell’s attempt at a Sonic-style handcrafted fountain drink — required staff to build each order individually rather than pour from a valve.","callout":{"label":"Replaced by","text":"The Freeze machine rollout in 2013 ended the Sparkler program."},"notes":"Available elsewhere? No. Unique to Taco Bell, never sold at retail. Priced at $1.69 for 16 oz. The \"sparkler\" name referred to the visible carbonation rising through the lime syrup."},{"name":"Cherry Limeade Sparkler","info":"~2010 – 2012","desc":"The signature variant. Cherry syrup pooled beneath the Sierra Mist and lime base, creating a two-tone red-green gradient visible through the clear cup. More visually striking than the Classic — and far more remembered. TikTok tributes years after its discontinuation regularly hit millions of views.","callout":{"label":"Replaced by","text":"Same — the entire Sparkler program ended with the Freeze machine arrival."},"notes":"Available elsewhere? No. TikTok mourning videos still surface, but the product is completely gone. Of all items in this archive, the Cherry Limeade Sparkler may have the highest nostalgia-to-quantity-sold ratio of any Taco Bell drink."}]},{"name":"Non-Carbonated Fountain","color":12,"ribbon":{"text":"Discontinued","tone":"gone"},"items":[{"name":"Lipton Brisk Lemon","info":"1999 – 2020","desc":"Standard lemon iced tea from the Brisk line, a PepsiCo/Unilever joint venture. Held the iced tea fountain valve at Taco Bell for twenty-one years — longer than most food items last on the menu. Replaced by Brisk Raspberry in 2020.","callout":{"label":"Replaced by","text":"Brisk Raspberry took the iced tea valve in 2020."},"notes":"Available elsewhere? Yes. Brisk Lemon is widely available in cans and bottles at retail. Twenty-one years is an exceptionally long run for a non-core beverage."},{"name":"Hot Tea (select markets)","info":"2014 – 2020","desc":"Hot tea service available at a subset of Taco Bell locations, typically those with full hot beverage stations installed during the breakfast expansion. Never achieved national distribution.","callout":{"label":"Replaced by","text":"Quietly removed as hot beverage equipment was simplified."},"notes":"Available elsewhere? No TB-specific tea product. Limited to markets with breakfast-capable hot beverage equipment."},{"name":"Tropicana Pink Lemonade","info":"~2014 – 2023","desc":"Tropicana’s pink lemonade on the Taco Bell fountain — a sweet, slightly tart alternative to standard Tropicana lemonade. Quietly removed in 2023; its departure sparked a wave of fan petitions on TikTok.","callout":{"label":"Replaced by","text":"Regular Tropicana Lemonade remains on the fountain. The Dirty Sips line (2026) added a vanilla cream version but did not replace the pink variant."},"notes":"Available elsewhere? Yes. Tropicana Pink Lemonade is widely available at retail. One of the most mourned recent discontinuations among regular Taco Bell customers."},{"name":"Brisk Iced Tea and Lemonade","info":"December 2013 – ~2020","desc":"A half-and-half blend of Brisk iced tea and lemonade, introduced as part of the December 2013 PepsiCo fountain expansion. An Arnold Palmer–style drink on the Taco Bell fountain.","callout":{"label":"Replaced by","text":"Valve reassigned during PepsiCo’s fountain portfolio rotation."},"notes":"Available elsewhere? Not in this specific fountain format. Part of the same 6-drink PepsiCo expansion that brought Mtn Dew Sangrita Blast."},{"name":"Brisk Raspberry Iced Tea","info":"~2015 – ~2020","desc":"Brisk’s raspberry-flavored iced tea on the Taco Bell fountain. A fruity twist on the standard Brisk Lemon that rotated through select locations before being phased out.","callout":{"label":"Replaced by","text":"Valve reassigned to other Brisk or PepsiCo non-carbonated options."},"notes":"Available elsewhere? Brisk Raspberry Iced Tea has also been largely discontinued by PepsiCo. Fans on TikTok have asked PepsiCo why the raspberry flavor was pulled.","cta":"/taco-bell-brisk-raspberry.html"},{"name":"SoBe Lifewater Yumberry Pomegranate","info":"December 2013 – ~2017","desc":"A zero-calorie, nutrient-enhanced water from PepsiCo’s SoBe brand, introduced at Taco Bell in December 2013 as part of the same 6-drink fountain expansion. The only enhanced water ever offered on a Taco Bell fountain.","callout":{"label":"Replaced by","text":"Removed when PepsiCo began phasing out the SoBe brand nationally (~2017)."},"notes":"Available elsewhere? No. SoBe Lifewater has been largely discontinued by PepsiCo. SoBe supply began dwindling around 2017; the brand was quietly abandoned by PepsiCo."}]},{"name":"Defunct Fountain Sodas","color":13,"ribbon":{"text":"Discontinued","tone":"gone"},"items":[{"name":"Sierra Mist","info":"2003 – 2023","desc":"PepsiCo’s lemon-lime soda, distributed nationally through Taco Bell fountains from 2003 until its discontinuation in 2023. Replaced systemwide by Starry, PepsiCo’s new lemon-lime brand.","callout":{"label":"Replaced by","text":"Starry replaced Sierra Mist on all PepsiCo fountain accounts."},"notes":"Available elsewhere? No. The brand was permanently killed by PepsiCo. Starry is the replacement. Sierra Mist had been reformulated multiple times during its run, including a brief rebrand as \"Mist Twst\" in 2016–2018."},{"name":"Pepsi Max → Zero Sugar (renamed)","info":"2008 – 2016","desc":"A zero-calorie Pepsi variant available on Taco Bell fountains. Originally branded as Pepsi Max, later rebranded to Pepsi Zero Sugar at retail — but the fountain version was removed from most Taco Bell locations around 2016.","callout":{"label":"Replaced by","text":"The zero-calorie valve was dropped from TB’s fountain config."},"notes":"Available elsewhere? Yes. Pepsi Zero Sugar is widely available at retail and other fountains — just not at TB. Pepsi Zero Sugar continued at retail and at other fountain chains; the discontinuation was specific to Taco Bell’s fountain configuration."},{"name":"Tropicana Twister","info":"2003 – ~2010","desc":"A fruit-flavored juice drink from PepsiCo’s Tropicana line, available at Taco Bell fountains during the 2000s. Occupied the non-carbonated juice slot before being phased out around 2010.","callout":{"label":"Replaced by","text":"The non-carbonated juice slot was phased out entirely."},"notes":"Available elsewhere? No. The Tropicana Twister brand was discontinued at retail too. The Tropicana Twister brand was eventually discontinued at retail as well."},{"name":"Brisk Dragon Paradise","info":"2022 – 2025","desc":"A dragonfruit-flavored iced tea from the Brisk line, added to Taco Bell fountains in 2022. One of the more recent fountain additions before being removed in 2025.","callout":{"label":"Replaced by","text":"Removed from the fountain tea valve in 2025."},"notes":"Available elsewhere? No. A fountain-only product with no retail equivalent. Part of Taco Bell’s effort to expand the iced tea valve beyond standard lemon."}]}]}'::jsonb)
) as v(wiki_id, page_id, position, component, data)
where not exists (select 1 from public.sections s
  where s.wiki_id = 'taco-bell' and s.page_id = 'taco-bell-discontinued-drinks');

-- ── taco-bell / taco-bell-sangrita-blast (2 sections) ──
insert into public.pages (wiki_id, id, slug, title, type) values
  ('taco-bell', 'taco-bell-sangrita-blast', 'taco-bell-sangrita-blast.html', 'Sangrita Blast', 'standard')
on conflict (wiki_id, id) do update set slug = excluded.slug, title = excluded.title, type = excluded.type;
insert into public.sections (wiki_id, page_id, position, component, data)
select * from (values
  ('taco-bell', 'taco-bell-sangrita-blast', 0, 'hero', '{"eyebrow":"Mountain Dew · PepsiCo · 2013–2017","title":"Mtn Dew<br>Sangrita Blast","subtitle":null,"subtitle_meta":null,"desc":"A cherry-citrus punch soda produced by PepsiCo under the Mountain Dew brand. Introduced in December 2013 and discontinued in 2017.","stats":[],"search":false,"search_placeholder":null,"spotlight":null,"feature":null}'::jsonb),
  ('taco-bell', 'taco-bell-sangrita-blast', 1, 'overview', '{"tone":"b","heading":"Background","paragraphs":["Mtn Dew Sangrita Blast was a franchise-exclusive Mountain Dew flavor produced by PepsiCo for Taco Bell restaurants. It launched in December 2013 as part of a six-drink PepsiCo fountain expansion that also included Diet Baja Blast, Brisk Iced Tea and Lemonade, Brisk Mango Fiesta, SoBe Lifewater Yumberry Pomegranate, and Kickstart Orange Citrus.","The drink was maroon in color, achieved through a combination of Red 40 and Blue 1 dyes. PepsiCo’s official flavor descriptor was “citrus punch,” though consumer descriptions frequently referenced cherry, pomegranate, cranberry, and raspberry notes.","In April 2015, PepsiCo released Sangrita Blast in cans and bottles alongside Baja Blast’s second retail run. This remains the only retail release of Sangrita Blast. A frozen Freeze variant was also available at Taco Bell from May to September 2015.","Sangrita Blast was discontinued from Taco Bell fountains in 2017 and replaced by Mtn Dew Spiked (Lemonade). No official reason was given for the discontinuation. PepsiCo has not re-released the flavor in any format since."],"infobox":null}'::jsonb)
) as v(wiki_id, page_id, position, component, data)
where not exists (select 1 from public.sections s
  where s.wiki_id = 'taco-bell' and s.page_id = 'taco-bell-sangrita-blast');

-- ── taco-bell / taco-bell-brisk-raspberry (2 sections) ──
insert into public.pages (wiki_id, id, slug, title, type) values
  ('taco-bell', 'taco-bell-brisk-raspberry', 'taco-bell-brisk-raspberry.html', 'Brisk Raspberry Tea', 'standard')
on conflict (wiki_id, id) do update set slug = excluded.slug, title = excluded.title, type = excluded.type;
insert into public.sections (wiki_id, page_id, position, component, data)
select * from (values
  ('taco-bell', 'taco-bell-brisk-raspberry', 0, 'hero', '{"eyebrow":"Brisk · PepsiCo / Unilever · 1991–present","title":"Brisk Raspberry<br>Iced Tea","subtitle":null,"subtitle_meta":null,"desc":"A raspberry-flavored iced tea produced by the Pepsi Lipton Partnership (PepsiCo/Unilever). Available in retail since the 1990s; discontinued from Taco Bell fountains around 2020.","stats":[],"search":false,"search_placeholder":null,"spotlight":null,"feature":null}'::jsonb),
  ('taco-bell', 'taco-bell-brisk-raspberry', 1, 'overview', '{"tone":"b","heading":"Background","paragraphs":["Brisk Raspberry Iced Tea is a ready-to-drink flavored iced tea produced through the Pepsi Lipton Tea Partnership, a joint venture established in 1991 between PepsiCo and Unilever. The Brisk brand crossed $1 billion in annual revenue by 2012, making it one of PepsiCo’s 22 billion-dollar brands.","The raspberry variant adds natural raspberry flavoring to the standard Brisk black tea base. It is available in retail as cans, bottles, and fountain syrup (3-gallon bag-in-box format distributed through PepsiCo Partners).","Brisk Raspberry Iced Tea appeared on Taco Bell fountains around 2015 as part of the PepsiCo non-carbonated fountain portfolio. It was removed around 2020 during a routine portfolio refresh. The retail product was not affected and remains in active production.","In late 2025, PepsiCo announced plans to eliminate approximately 20% of its U.S. product lineup by early 2026. Brisk Raspberry Iced Tea survived this cut in retail, though its presence at Taco Bell had already ended years earlier."],"infobox":null}'::jsonb)
) as v(wiki_id, page_id, position, component, data)
where not exists (select 1 from public.sections s
  where s.wiki_id = 'taco-bell' and s.page_id = 'taco-bell-brisk-raspberry');

-- ── taco-bell / taco-bell-pina-colada-frutista (2 sections) ──
insert into public.pages (wiki_id, id, slug, title, type) values
  ('taco-bell', 'taco-bell-pina-colada-frutista', 'taco-bell-pina-colada-frutista.html', 'Pina Colada Frutista', 'standard')
on conflict (wiki_id, id) do update set slug = excluded.slug, title = excluded.title, type = excluded.type;
insert into public.sections (wiki_id, page_id, position, component, data)
select * from (values
  ('taco-bell', 'taco-bell-pina-colada-frutista', 0, 'hero', '{"eyebrow":"Frutista Freeze · Taco Bell · 2009–2013","title":"Piña Colada<br>Frutista Freeze","subtitle":null,"subtitle_meta":null,"desc":"A hand-blended pineapple-coconut frozen drink produced exclusively for Taco Bell as part of the Frutista Freeze program (2008–2013).","stats":[],"search":false,"search_placeholder":null,"spotlight":null,"feature":null}'::jsonb),
  ('taco-bell', 'taco-bell-pina-colada-frutista', 1, 'overview', '{"tone":"b","heading":"Background","paragraphs":["The Piña Colada Frutista Freeze was a pineapple-coconut frozen beverage introduced in spring 2009 as part of Taco Bell’s Frutista Freeze program. It launched alongside the Strawberry Colada variant as part of the program’s tropical rotation.","Frutista Freezes were hand-blended per order using a commercial blender with fruit syrups, ice, and real fruit toppings. The Piña Colada variant was topped with actual pineapple chunks.","The Frutista Freeze program ran from May 2008 to late 2012, producing 13 flavors across seasonal rotations. In January 2013, Taco Bell replaced the commercial blenders with automated Taylor Freeze machines. A non-Frutista “Piña Colada Freeze” briefly appeared on the Taylor machine from January to September 2013 as a transitional product, but it was a different formulation without the hand-blended preparation or real fruit.","The Piña Colada Frutista Freeze was never sold in retail (cans, bottles) or at any location outside Taco Bell."],"infobox":null}'::jsonb)
) as v(wiki_id, page_id, position, component, data)
where not exists (select 1 from public.sections s
  where s.wiki_id = 'taco-bell' and s.page_id = 'taco-bell-pina-colada-frutista');

-- ── taco-bell / taco-bell-spiked-lemonade (2 sections) ──
insert into public.pages (wiki_id, id, slug, title, type) values
  ('taco-bell', 'taco-bell-spiked-lemonade', 'taco-bell-spiked-lemonade.html', 'Spiked Lemonade', 'standard')
on conflict (wiki_id, id) do update set slug = excluded.slug, title = excluded.title, type = excluded.type;
insert into public.sections (wiki_id, page_id, position, component, data)
select * from (values
  ('taco-bell', 'taco-bell-spiked-lemonade', 0, 'hero', '{"eyebrow":"Mountain Dew · PepsiCo · 2017–2019","title":"Mtn Dew<br>Spiked Lemonade","subtitle":null,"subtitle_meta":null,"desc":"A non-alcoholic lemonade soda with prickly pear cactus juice, produced by PepsiCo under the Mountain Dew brand. Available from 2017 to 2019.","stats":[],"search":false,"search_placeholder":null,"spotlight":null,"feature":null}'::jsonb),
  ('taco-bell', 'taco-bell-spiked-lemonade', 1, 'overview', '{"tone":"b","heading":"Background","paragraphs":["Mtn Dew Spiked was a lemonade-flavored Mountain Dew variant introduced in early 2017 as a replacement for Sangrita Blast on Taco Bell’s dedicated Mountain Dew fountain valve. The drink was marketed as being “spiked” with prickly pear cactus juice, though it contained no alcohol.","PepsiCo simultaneously released retail 16-ounce cans in two flavors: Lemonade and Raspberry Lemonade. The drink was promoted during Comedy Central’s Colossal Clusterfest in 2017.","A Freeze variant was available at Taco Bell from early 2017 through September 2017, when it was replaced by the Strawberry Poppin’ Candy Freeze. Retail cans were discontinued in 2018. The Taco Bell fountain version was phased out between December 2018 and March 2019 to make room for the introduction of Baja Blast Zero Sugar.","In Canada, the product was sold under the name “Mtn Dew Extra (Lemonade)” to avoid confusion about the “Spiked” name’s implied alcohol content."],"infobox":null}'::jsonb)
) as v(wiki_id, page_id, position, component, data)
where not exists (select 1 from public.sections s
  where s.wiki_id = 'taco-bell' and s.page_id = 'taco-bell-spiked-lemonade');

