  ('taco-bell', 'taco-bell-sauces', 0, 'hero', '{"eyebrow":"Condiment · Packet · Cult","title":"Sauces","subtitle":null,"subtitle_meta":null,"desc":"Four packet tiers, ten in-restaurant condiments, six discontinued legends, and roughly 8 billion packets distributed every year. Sorted, scaled, and quoted.","stats":[{"num":"8.2B","label":"packets / yr"},{"num":"0 cal","label":"Mild–Diablo"},{"num":"~4,500","label":"Scoville · Diablo"},{"num":"1980s","label":"Mild &amp; Hot debut"}],"search":false,"search_placeholder":null,"spotlight":null,"feature":{"head_left":"★ Tier IV · Spotlight","head_right":"Est. 2015","title":"Diablo","desc":"The hottest production packet. Chipotle base, cayenne back-end, with a fruity aji panca note that separates it from the others.","chips":[{"key":"Heat","val":"~4,500 SHU"},{"key":"Cal","val":"0"},{"key":"Sodium","val":"95mg"}]}}'::jsonb),
  ('taco-bell', 'taco-bell-sauces', 1, 'overview', '{"tone":"b","heading":"","paragraphs":[],"infobox":null}'::jsonb)
) as v(wiki_id, page_id, position, component, data)
