-- ── taco-bell / taco-bell-menus (2 sections) ──
insert into public.pages (wiki_id, id, slug, title, type) values
  ('taco-bell', 'taco-bell-menus', 'taco-bell-menus.html', 'Menus', 'standard')
on conflict (wiki_id, id) do update set slug = excluded.slug, title = excluded.title, type = excluded.type;
insert into public.sections (wiki_id, page_id, position, component, data)
select * from (values
  ('taco-bell', 'taco-bell-menus', 0, 'hero', '{"eyebrow":"Menu History · 1962 – Present","title":"Taco Bell Menus","subtitle":null,"subtitle_meta":null,"desc":"Fourteen sub-menus across sixty-four years — from a five-item 19-cent founding card to today''s Cantina Chicken line, every strategic menu move Taco Bell has ever made, catalogd and archived.","stats":[{"num":"14","label":"Total menus"},{"num":"3","label":"Active today"},{"num":"1962","label":"First menu"},{"num":"64 yr","label":"Archive span"}],"search":false,"search_placeholder":null,"spotlight":null,"feature":null}'::jsonb),
  ('taco-bell', 'taco-bell-menus', 1, 'overview', '{"tone":"b","heading":"Every sub-menu was a strategic move.","paragraphs":["Taco Bell doesn''t launch sub-menus for variety''s sake. Each one is a response to a specific pressure — a competitor move, a cultural moment, a demographic it isn''t reaching. The <strong>Original 19-Cent Menu</strong> was a founding price signal; the <strong>59¢/79¢/99¢ Value Menu</strong> was a direct answer to McDonald''s Dollar Menu dominance. When the industry went low-fat in the mid-''90s, Taco Bell had <strong>Border Lights</strong> within a year.","The pattern accelerates after 2008. As fast-casual began threatening the QSR segment, Taco Bell launched <strong>Cantina Bell</strong> with a celebrity chef and upmarket positioning — two years before Chipotle peaked. The <strong>National Breakfast Menu</strong> in 2014 was the most-watched single-day QSR expansion in industry history. What these moments share is timing: Taco Bell tends to move early, before the market confirms the opportunity is real.","Not every move lands. The <strong>Volcano Menu</strong> was retired in 2013 after five years, then revived in 2023 when demand signals made the case again. The <strong>$2 Meal Deals</strong> ran three years before being absorbed into a cleaner value structure. <strong>Fresco</strong> began as a POS modifier in 2003 and launched as a dedicated branded sub-menu nationwide in 2008, running until August 2020, when it was retired as part of a COVID-19 menu simplification. The \"Fresco Style\" modifier remains available as a digital ordering option. Failure has its own pattern here: menus that try to own a single attribute (heat, price, freshness) without a broader identity tend to age out faster.","The two active sub-brands today — <strong>National Breakfast</strong> and <strong>Cantina Chicken</strong> — both have dedicated sourcing, distinct positioning, and their own visual identity within Taco Bell''s system. The newer <strong>Luxe Value Menu</strong> signals a return to tiered value as the broader QSR sector re-engages with price-sensitive customers. The archive below is organized by status: what''s running now, and what ran before."],"infobox":null}'::jsonb)
) as v(wiki_id, page_id, position, component, data)
where not exists (select 1 from public.sections s
  where s.wiki_id = 'taco-bell' and s.page_id = 'taco-bell-menus');

-- ── taco-bell / taco-bell-menu-cantina-chicken (3 sections) ──
insert into public.pages (wiki_id, id, slug, title, type) values
  ('taco-bell', 'taco-bell-menu-cantina-chicken', 'taco-bell-menu-cantina-chicken.html', 'Cantina Chicken', 'standard')
on conflict (wiki_id, id) do update set slug = excluded.slug, title = excluded.title, type = excluded.type;
insert into public.sections (wiki_id, page_id, position, component, data)
select * from (values
  ('taco-bell', 'taco-bell-menu-cantina-chicken', 0, 'hero', '{"eyebrow":"Sub-brand · Active · Est. 2024","title":"Cantina Chicken Menu","subtitle":null,"subtitle_meta":null,"desc":"Slow-roasted chicken in garlic, onions, and Mexican chilies — across tacos, burritos, quesadillas, and bowls. Launched nationwide March 21, 2024.","stats":[{"num":"9","label":"Menu items"},{"num":"5","label":"Categories"},{"num":"2024","label":"Launched"},{"num":"Active","label":"Status","color":"#c084fc"}],"search":false,"search_placeholder":null,"spotlight":null,"feature":null}'::jsonb),
  ('taco-bell', 'taco-bell-menu-cantina-chicken', 1, 'overview', '{"tone":"a","heading":"A protein pivot, not a variety play.","paragraphs":["Launched nationwide on <strong>March 21, 2024</strong>, the Cantina Chicken Menu is Taco Bell''s most deliberate bid yet to compete at the fast-casual tier — not on price, but on ingredient quality. The strategic target was explicit: Chipotle, CAVA, and the broader daytime fast-casual segment that has eroded legacy QSR market share through the 2010s and early 2020s. The line debuted at Taco Bell''s inaugural <em>Live Más LIVE</em> event in Las Vegas in February 2024, followed by a Taco Bell Rewards early-access window on March 14 and 18 before the full nationwide roll-out one week later.","The entire line is built around a single new protein: slow-roasted chicken prepared in a savory blend of garlic, onions, and authentic Mexican chilies. This is a distinct offering from the chain''s standard shredded or grilled chicken — a separate preparation with its own seasoning profile and supply chain. Taco Bell deploys it across every major format in its menu architecture (tacos, burritos, quesadillas, bowls), which is the vertical logic of the sub-line: one elevated protein, maximum menu surface area.","To distinguish the line visually and texturally from standard builds, Taco Bell introduced a suite of fresh ingredients not previously deployed at scale: <strong>shredded purple cabbage</strong> for crunch and color, <strong>pico de gallo</strong> prepared fresh daily, <strong>white corn tortilla shells</strong> fried in-house daily for the crispy items, and the <strong>Avocado Verde Salsa</strong> — a new packet-based sauce formulated with real avocado pulp, tomatillos, and green chili peppers, included automatically with every Cantina order. The fresh-produce commitment alone projected 2.5 million additional pounds of usage in the first year.","The precedent is <strong>Cantina Bell</strong> (2012–2014), which attempted the same fast-casual pivot through a broader ingredient overhaul with chef Lorena Garcia. It lasted two years. Cantina Chicken narrows the bet to a single protein and owns the preparation rather than overhauling the entire ingredient stack. Consumer response to the initial five-item launch was strong enough that the culinary team permanently expanded the line — adding the <strong>Cantina Chicken Rolled Quesadilla</strong> and the <strong>Cantina Chicken Mexican Pizza</strong> to the permanent roster, raising the item count above the launch configuration catalogd here."],"infobox":null}'::jsonb),
  ('taco-bell', 'taco-bell-menu-cantina-chicken', 2, 'catalog', '{"title":"Every menu item","unit":"item","visual":"catalog","tone":"b","categories":[{"name":"Tacos","color":14,"items":[{"name":"Cantina Chicken Crispy Taco","status":"active","desc":"A freshly fried white corn shell filled with slow-roasted chicken, creamy jalapeño sauce, and a three-cheese blend — with a signature grilled cheese crust on the outside of the shell.","groups":[{"label":"Ingredients","pills":["Freshly fried white corn shell","Slow-roasted chicken","Creamy jalapeño sauce","Three-cheese blend","Grilled cheese crust (exterior)"]}]},{"name":"Cantina Chicken Soft Taco","status":"active","desc":"A warm flour tortilla containing slow-roasted chicken, iceberg lettuce, shredded purple cabbage, avocado ranch sauce, cheddar cheese, and fresh pico de gallo.","groups":[{"label":"Ingredients","pills":["Flour tortilla","Slow-roasted chicken","Iceberg lettuce","Shredded purple cabbage","Avocado ranch sauce","Cheddar cheese","Fresh pico de gallo"]}]}]},{"name":"Burritos","color":15,"items":[{"name":"Cantina Chicken Burrito","status":"active","desc":"A grilled flour tortilla packed with a double portion of slow-roasted chicken, lettuce, purple cabbage, avocado ranch, cheddar cheese, and fresh pico de gallo.","groups":[{"label":"Ingredients","pills":["Grilled flour tortilla","Double slow-roasted chicken","Iceberg lettuce","Shredded purple cabbage","Avocado ranch sauce","Cheddar cheese","Fresh pico de gallo"]}]}]},{"name":"Quesadillas","color":17,"items":[{"name":"Cantina Chicken Quesadilla","status":"active","desc":"A flour tortilla filled with slow-roasted chicken, a three-cheese blend, and creamy chipotle sauce — built with a grilled cheese layer on the outside.","groups":[{"label":"Ingredients","pills":["Flour tortilla","Slow-roasted chicken","Three-cheese blend","Creamy chipotle sauce","Grilled cheese crust (exterior)"]}]},{"name":"Cantina Chicken Rolled Quesadilla","status":"active","desc":"A permanent expansion item — slow-roasted chicken layered with a three-cheese blend and creamy chipotle sauce, tightly rolled and grilled until the exterior is crisp.","groups":[{"label":"Ingredients","pills":["Flour tortilla (rolled)","Slow-roasted chicken","Three-cheese blend","Creamy chipotle sauce"]}]}]},{"name":"Bowls","color":16,"items":[{"name":"Cantina Chicken Bowl","status":"active","desc":"A base of seasoned rice and black beans topped with slow-roasted chicken, iceberg lettuce, purple cabbage, cheddar cheese, sour cream, fresh guacamole, pico de gallo, and avocado ranch sauce.","groups":[{"label":"Ingredients","pills":["Seasoned rice","Black beans","Slow-roasted chicken","Iceberg lettuce","Shredded purple cabbage","Cheddar cheese","Sour cream","Fresh guacamole","Fresh pico de gallo","Avocado ranch sauce"]}]}]},{"name":"Mexican Pizza","color":21,"items":[{"name":"Cantina Chicken Mexican Pizza","status":"active","desc":"A Cantina Chicken twist on the classic Mexican Pizza — slow-roasted chicken, black beans, green chile sauce, a three-cheese blend, purple cabbage, and pico de gallo layered between two crispy pizza shells.","groups":[{"label":"Ingredients","pills":["Two crispy pizza shells","Slow-roasted chicken","Black beans","Green chile sauce","Three-cheese blend","Shredded purple cabbage","Fresh pico de gallo"]}]}]},{"name":"Nachos","color":20,"items":[{"name":"Cantina Chicken Verde Nachos","status":"active","desc":"A permanent addition to the Cantina Chicken line — slow-roasted chicken layered over crispy tortilla chips with Avocado Verde Salsa, a three-cheese blend, shredded purple cabbage, and fresh pico de gallo. The verde sauce ties the nachos directly to the sub-line''s signature sauce, distinguishing them from the chain''s standard nacho builds.","groups":[{"label":"Ingredients","pills":["Crispy tortilla chips","Slow-roasted chicken","Avocado Verde Salsa","Three-cheese blend","Shredded purple cabbage","Fresh pico de gallo"]}]}]},{"name":"Caliente Line","color":19,"items":[{"name":"Caliente Cantina Chicken Crispy Taco","status":"discontinued","desc":"A limited-edition variant of the Cantina Chicken Crispy Taco drizzled with a spicy, red-jalapeño-based Caliente Sauce in place of the standard creamy jalapeño sauce.","groups":[{"label":"Ingredients","pills":["Freshly fried white corn shell","Slow-roasted chicken","Caliente Sauce (spicy red jalapeño)","Three-cheese blend","Grilled cheese crust (exterior)"]}]},{"name":"Caliente Cantina Chicken Soft Taco","status":"discontinued","desc":"A limited-edition variant of the Cantina Chicken Soft Taco with an added layer of Caliente Sauce over the standard build.","groups":[{"label":"Ingredients","pills":["Flour tortilla","Slow-roasted chicken","Caliente Sauce (spicy)","Iceberg lettuce","Shredded purple cabbage","Cheddar cheese","Fresh pico de gallo"]}]},{"name":"Caliente Cantina Chicken Burrito","status":"discontinued","desc":"The double-chicken burrito built with Caliente Sauce in place of the standard avocado ranch — a spicier, hotter profile across the same base build.","groups":[{"label":"Ingredients","pills":["Grilled flour tortilla","Double slow-roasted chicken","Caliente Sauce (spicy red jalapeño)","Iceberg lettuce","Shredded purple cabbage","Cheddar cheese","Fresh pico de gallo"]}]},{"name":"Caliente Cantina Chicken Quesadilla","status":"discontinued","desc":"The grilled-cheese exterior quesadilla variant utilizing the spicy Caliente Sauce formulation in place of creamy chipotle.","groups":[{"label":"Ingredients","pills":["Flour tortilla","Slow-roasted chicken","Three-cheese blend","Caliente Sauce (spicy)","Grilled cheese crust (exterior)"]}]},{"name":"Caliente Cantina Chicken Bowl","status":"discontinued","desc":"The full Cantina Chicken protein bowl topped with a heavy drizzle of Caliente Sauce over the standard bowl build.","groups":[{"label":"Ingredients","pills":["Seasoned rice","Black beans","Slow-roasted chicken","Iceberg lettuce","Shredded purple cabbage","Cheddar cheese","Sour cream","Fresh guacamole","Fresh pico de gallo","Caliente Sauce (heavy drizzle)"]}]},{"name":"Caliente Cantina Chicken Nacho Fries","status":"discontinued","desc":"A limited mashup — crispy seasoned fries loaded with slow-roasted chicken, warm nacho cheese sauce, cheddar cheese, fiesta strips, sour cream, and a drizzle of Caliente Sauce.","groups":[{"label":"Ingredients","pills":["Seasoned Nacho Fries","Slow-roasted chicken","Warm nacho cheese sauce","Cheddar cheese","Fiesta strips","Sour cream","Caliente Sauce"]}]}]}]}'::jsonb)
) as v(wiki_id, page_id, position, component, data)
where not exists (select 1 from public.sections s
  where s.wiki_id = 'taco-bell' and s.page_id = 'taco-bell-menu-cantina-chicken');

-- ── taco-bell / taco-bell-menu-2-dollar-deals (3 sections) ──
insert into public.pages (wiki_id, id, slug, title, type) values
  ('taco-bell', 'taco-bell-menu-2-dollar-deals', 'taco-bell-menu-2-dollar-deals.html', '$2 Meal Deals', 'standard')
on conflict (wiki_id, id) do update set slug = excluded.slug, title = excluded.title, type = excluded.type;
insert into public.sections (wiki_id, page_id, position, component, data)
select * from (values
  ('taco-bell', 'taco-bell-menu-2-dollar-deals', 0, 'hero', '{"eyebrow":"Value · Retired · 2010–2013","title":"$2 Meal Deals","subtitle":null,"subtitle_meta":null,"desc":"Three items for two dollars — an entrée, a small bag of Doritos chips, and a medium drink. A Frito-Lay partnership that gave Taco Bell a value story competitors couldn''t replicate item-for-item.","stats":[{"num":"$2","label":"Price point"},{"num":"3 yr","label":"Active run"},{"num":"2010","label":"Launched"},{"num":"Retired","label":"Status","color":"#9ca3af"}],"search":false,"search_placeholder":null,"spotlight":null,"feature":null}'::jsonb),
  ('taco-bell', 'taco-bell-menu-2-dollar-deals', 1, 'overview', '{"tone":"a","heading":"The bundle as the differentiator.","paragraphs":["The $2 Meal Deals launched around 2010 as Taco Bell''s most direct response to the dollar-menu wars being fought between McDonald''s, Burger King, and Wendy''s. Rather than matching competitors item-for-item at the dollar price point, Taco Bell offered something structurally different: three components for two dollars — an entrée, a small bag of Nacho Cheese Doritos, and a medium fountain drink. The Doritos inclusion was a Frito-Lay partnership and the key structural move. Dollar menus sold items; the $2 Meal Deals sold a complete occasion.","The operational logic was straightforward. Taco Bell''s core items — the Crunchy Taco, the Soft Taco, the Bean Burrito — were already priced below a dollar individually at full margin. Bundling them with a fountain drink and a snack-size Doritos bag at two dollars gave the customer a perceived deal while maintaining reasonable unit economics — both chips and fountain drinks carry extremely low wholesale cost relative to perceived value. The format also gave Taco Bell a story: not \"we have cheap items,\" but \"we give you more.\"","The timing placed the $2 Meal Deals squarely within the <strong>Why Pay More!? / Big Bell Value Menu</strong> era — Taco Bell''s broader early-2010s push to own the value segment outright. The two programs ran in parallel: the Big Bell Value Menu covered individual items at low price points; the $2 Meal Deals covered the bundle-and-drink occasion. Together they attempted to make Taco Bell the default answer to any fast-food budget decision.","The format was retired around 2013. Its replacement was the <strong>Cravings Value Menu</strong> (2014), which brought a cleaner tiered architecture — $1, $2, and $3 levels — that absorbed the bundle logic without requiring a dedicated program. The $2 Meal Deals served their purpose: they established the bundle as a legitimate value format at Taco Bell, and the Cravings menu inherited that framing at scale."],"infobox":null}'::jsonb),
  ('taco-bell', 'taco-bell-menu-2-dollar-deals', 2, 'catalog', '{"title":"Every documented deal","unit":"option","visual":"catalog","tone":"b","categories":[{"name":"Tacos","color":14,"items":[{"name":"Double Decker Taco","desc":"Seasoned beef, shredded cheddar, and lettuce in a crunchy corn shell, wrapped in a soft flour tortilla with a layer of warm refried beans as the structural adhesive between the two shells. Bundled with a Nacho Cheese Doritos bag and a medium drink for $2.","groups":[{"label":"Ingredients","pills":["Soft flour tortilla (outer)","Warm refried beans (adhesive layer)","Crunchy corn shell (inner)","Seasoned beef","Shredded cheddar","Shredded lettuce"]}],"notes":"Letter B — based on official press listing order. Operational letter codes not independently documented."}]},{"name":"Burritos","color":15,"items":[{"name":"Grilled Chicken Burrito","desc":"Grilled chicken, seasoned rice, and avocado ranch sauce in a flour tortilla. A simpler build than later premium chicken burritos — three ingredients plus the tortilla. Bundled with a Nacho Cheese Doritos bag and a medium drink for $2.","groups":[{"label":"Ingredients","pills":["Flour tortilla","Grilled chicken","Seasoned rice","Avocado ranch sauce"]}],"notes":"Letter A — based on official press listing order. Operational letter codes not independently documented."},{"name":"Beefy 5-Layer Burrito","desc":"Seasoned beef, nacho cheese sauce, sour cream, seasoned beans, and three-cheese blend in a steamed flour tortilla. Unlike the Quesarito or Grilled Stuft Burrito, the Beefy 5-Layer has never been run through the grill press — it is warmed and wrapped. Bundled with a Nacho Cheese Doritos bag and a medium drink for $2.","groups":[{"label":"Ingredients","pills":["Steamed flour tortilla","Seasoned beef","Nacho cheese sauce","Seasoned beans","Sour cream","Three-cheese blend"]}],"notes":"Letter D — based on official press listing order. Operational letter codes not independently documented."}]},{"name":"Gorditas","color":17,"items":[{"name":"Gordita Supreme","desc":"Seasoned beef, sour cream, three-cheese blend, diced tomatoes, and shredded lettuce in a thick flatbread pocket. Bundled with a Nacho Cheese Doritos bag and a medium drink for $2.","groups":[{"label":"Ingredients","pills":["Gordita flatbread","Seasoned beef","Sour cream","Three-cheese blend","Diced tomatoes","Shredded lettuce"]}],"notes":"Letter C — based on official press listing order. Operational letter codes not independently documented."}]}]}'::jsonb)
) as v(wiki_id, page_id, position, component, data)
where not exists (select 1 from public.sections s
  where s.wiki_id = 'taco-bell' and s.page_id = 'taco-bell-menu-2-dollar-deals');

-- ── taco-bell / taco-bell-menu-fresco (3 sections) ──
insert into public.pages (wiki_id, id, slug, title, type) values
  ('taco-bell', 'taco-bell-menu-fresco', 'taco-bell-menu-fresco.html', 'Fresco Menu', 'standard')
on conflict (wiki_id, id) do update set slug = excluded.slug, title = excluded.title, type = excluded.type;
insert into public.sections (wiki_id, page_id, position, component, data)
select * from (values
  ('taco-bell', 'taco-bell-menu-fresco', 0, 'hero', '{"eyebrow":"Health-Forward · Retired Aug. 2020 · Est. 2003","title":"Fresco Menu","subtitle":null,"subtitle_meta":null,"desc":"A dedicated sub-menu built around a single substitution: replace cheese and sauce with Fiesta Salsa — Taco Bell''s fresh-daily blend of tomatoes, onions, cilantro, and chili. Every item under nine grams of fat. No upcharge.","stats":[{"num":"2003","label":"Launched"},{"num":"&lt;9g","label":"Fat per item"},{"num":"2010","label":"Drive-Thru Diet"},{"num":"Retired","label":"Status","color":"#9ca3af"}],"search":false,"search_placeholder":null,"spotlight":null,"feature":null}'::jsonb),
  ('taco-bell', 'taco-bell-menu-fresco', 1, 'overview', '{"tone":"a","heading":"One swap. Nine items. No upcharge.","paragraphs":["The Fresco Menu launched in 2003 as Taco Bell''s first dedicated health-oriented sub-line. The concept was structurally simple: any item served Fresco style had its cheese and sauce components removed and replaced with <strong>Fiesta Salsa</strong> — a fresh-daily preparation of diced tomatoes, white onions, cilantro, and chili seasonings. The result was a calorie and fat reduction of between 20 and 100 calories per item and up to 50% less fat, with no change to price. The Fresco menu was not a separate ordering system — it was a modifier applied to existing items, and kitchen staff were trained to execute it as a standard customisation.","The 2003 launch committed to a specific nutritional threshold: all items on the dedicated Fresco menu would come in under nine grams of fat. This was an unusual move for a QSR brand at the time. Fast food chains had experimented with \"lite\" or \"low-fat\" items before, but dedicated sub-menus with publicly enforced nutritional ceilings were rare in the segment. The Fresco Menu predated the broader fast-food health wave that would follow — Subway''s Jared campaign had run since 2000, but no major QSR had operationalised a full modifiable sub-line with the same consistency.","The menu gained its highest national profile in January 2010 with the launch of the <strong>Drive-Thru Diet</strong> campaign — Taco Bell''s most controversial marketing move in the Fresco line''s history. The campaign featured Christine Dougherty, who claimed to have lost 54 pounds over two years by choosing Fresco items as part of a calorie-controlled diet. Taco Bell''s own disclaimer acknowledged the results were not typical and that Fresco items were \"not a low calorie food\" — the campaign''s value was in calorie <em>reduction relative to the standard menu</em>, not in positioning Taco Bell as a health food destination.","The standalone Fresco Menu — as a named, dedicated section on physical menu boards and digital drive-thrus — was permanently retired in <strong>August 2020</strong> as part of a sweeping corporate simplification driven by the COVID-19 pandemic. Taco Bell cut roughly 12 menu items and several sub-menu sections to reduce kitchen complexity and speed up service times. However, the <strong>\"Fresco Style\" modifier itself was not retired</strong>: it remains active today as a button on kitchen registers, digital kiosks, and the mobile app. The ingredient it substitutes changed in the same 2020 cut — Pico de Gallo (Fiesta Salsa) was discontinued, so ordering Fresco Style now replaces cheese and dairy with standard diced tomatoes rather than the original fresh-daily salsa preparation. The no-upcharge policy remains in place."],"infobox":null}'::jsonb),
  ('taco-bell', 'taco-bell-menu-fresco', 2, 'catalog', '{"title":"Every Fresco item","unit":"item","visual":"catalog","tone":"b","note":"all under 9g fat","categories":[{"name":"Tacos","color":14,"items":[{"name":"Fresco Crunchy Taco","info":"150 cal · 7g fat","desc":"Seasoned beef, shredded lettuce, and diced tomatoes in a crunchy corn shell. The only change from the standard Crunchy Taco is the removal of shredded cheddar cheese — the shell, beef, and lettuce remain identical.","groups":[{"label":"Ingredients","pills":["Crunchy corn shell","Seasoned beef","Shredded lettuce","Diced tomatoes"]},{"label":"Replaced by Fresco modifier","pills":[{"text":"Shredded cheddar cheese","struck":true}]}]},{"name":"Fresco Soft Taco","info":"180 cal · 7g fat","desc":"Seasoned beef, shredded lettuce, and diced tomatoes in a warm flour tortilla. Cheese removed and replaced with diced tomatoes under the Fresco modifier.","groups":[{"label":"Ingredients","pills":["Flour tortilla","Seasoned beef","Shredded lettuce","Diced tomatoes"]},{"label":"Replaced by Fresco modifier","pills":[{"text":"Shredded cheddar cheese","struck":true}]}]},{"name":"Fresco Grilled Chicken Soft Taco","info":"170 cal · 4g fat","desc":"Grilled chicken breast, shredded lettuce, and diced tomatoes in a warm flour tortilla. At the time of the 2007 Fresco Menu launch, Taco Bell used grilled chicken breast for its chicken soft taco builds — the shredded chicken variant (slow-cooked in a tomato-chile broth) was not introduced to the assembly line until 2011. Both the avocado ranch sauce and the shredded cheese are removed by the Fresco modifier — diced tomatoes replace both. One of the lowest-fat items across the full Fresco line at 4g.","groups":[{"label":"Ingredients","pills":["Flour tortilla","Grilled chicken breast","Shredded lettuce","Diced tomatoes"]},{"label":"Replaced by Fresco modifier","pills":[{"text":"Avocado ranch sauce","struck":true},{"text":"Shredded cheese","struck":true}]}]},{"name":"Fresco Grilled Steak Soft Taco","info":"160 cal · 4.5g fat","desc":"Grilled steak, shredded lettuce, and diced tomatoes in a warm flour tortilla. At 160 calories, the lowest-calorie item in the Fresco taco tier.","groups":[{"label":"Ingredients","pills":["Flour tortilla","Grilled steak","Shredded lettuce","Diced tomatoes"]},{"label":"Replaced by Fresco modifier","pills":[{"text":"Shredded cheese","struck":true},{"text":"Creamy sauce","struck":true}]}]}]},{"name":"Burritos","color":15,"items":[{"name":"Fresco Burrito Supreme","info":"330 cal · 8g fat","desc":"Seasoned beef, refried beans, red sauce, shredded lettuce, onions, and diced tomatoes in a flour tortilla. The Fresco modifier removes only the sour cream and cheddar cheese — the red sauce, shredded lettuce, and onions are all explicitly retained. Refried beans serve as a core structural component alongside the beef. Diced tomatoes replace the two dairy items removed.","groups":[{"label":"Ingredients","pills":["Flour tortilla","Seasoned beef","Refried beans","Red sauce","Shredded lettuce","Onions","Diced tomatoes"]},{"label":"Replaced by Fresco modifier","pills":[{"text":"Sour cream","struck":true},{"text":"Cheddar cheese","struck":true}]}]},{"name":"Fresco Bean Burrito","info":"340 cal · 8g fat","desc":"Refried beans, red sauce, onions, and diced tomatoes in a flour tortilla. Red sauce is retained — it is the only sauce preserved under the Fresco modifier because its calorie count is low enough to remain across all applicable items.","groups":[{"label":"Ingredients","pills":["Flour tortilla","Refried beans","Red sauce","Onions","Diced tomatoes"]},{"label":"Replaced by Fresco modifier","pills":[{"text":"Shredded cheddar cheese","struck":true}]}]},{"name":"Fresco Beef Premium Burrito","info":"340 cal · 9g fat","desc":"Seasoned beef, seasoned rice, red sauce, and diced tomatoes in a flour tortilla. The Premium Burrito format adds seasoned rice as a filling layer alongside the beef — at 9g fat this sits at the exact ceiling of the Fresco nutritional threshold.","groups":[{"label":"Ingredients","pills":["Flour tortilla","Seasoned beef","Seasoned rice","Red sauce","Diced tomatoes"]},{"label":"Replaced by Fresco modifier","pills":[{"text":"Shredded cheese","struck":true},{"text":"Creamy sauce","struck":true}]}]},{"name":"Fresco Chicken Enchirito","info":"250 cal · 6g fat","desc":"Grilled chicken breast and onions rolled in a soft flour tortilla, smothered in red sauce, and topped with diced tomatoes. During the 2008–2010 Fresco Menu era, Taco Bell used chunky grilled chicken breast across all chicken builds — the slow-cooked shredded chicken variant was not introduced until 2011. The Enchirito format — rolled and sauce-smothered rather than folded — distinguishes it from the burrito items on the Fresco line. Shredded cheese, the standard Enchirito topping, is replaced by diced tomatoes.","groups":[{"label":"Ingredients","pills":["Soft flour tortilla (rolled)","Grilled chicken breast","Onions","Red sauce (smothered)","Diced tomatoes (topping)"]},{"label":"Replaced by Fresco modifier","pills":[{"text":"Shredded cheese","struck":true}]}]}]},{"name":"Specialties","color":16,"items":[{"name":"Fresco Fiesta Taco Salad","info":"420 cal · 8g fat","desc":"Seasoned beef, seasoned rice, refried beans, shredded lettuce, onions, and diced tomatoes served in a crispy tortilla bowl. The Fresco version omits cheese, sour cream, the salad dressing, and the crispy red tortilla chip strips — the strips were counted as part of the high-fat profile corporate needed to remove to hit the sub-9g-fat threshold. The tortilla bowl itself is retained as the structural container.","groups":[{"label":"Ingredients","pills":["Crispy tortilla bowl","Seasoned beef","Seasoned rice","Refried beans","Shredded lettuce","Onions","Diced tomatoes"]},{"label":"Replaced by Fresco modifier","pills":[{"text":"Shredded cheese","struck":true},{"text":"Sour cream","struck":true},{"text":"Salad dressing","struck":true},{"text":"Crispy red tortilla strips","struck":true}]}]}]}]}'::jsonb)
) as v(wiki_id, page_id, position, component, data)
where not exists (select 1 from public.sections s
  where s.wiki_id = 'taco-bell' and s.page_id = 'taco-bell-menu-fresco');

-- ── taco-bell / taco-bell-menu-big-bell-value (3 sections) ──
insert into public.pages (wiki_id, id, slug, title, type) values
  ('taco-bell', 'taco-bell-menu-big-bell-value', 'taco-bell-menu-big-bell-value.html', 'Big Bell Value', 'standard')
on conflict (wiki_id, id) do update set slug = excluded.slug, title = excluded.title, type = excluded.type;
insert into public.sections (wiki_id, page_id, position, component, data)
select * from (values
  ('taco-bell', 'taco-bell-menu-big-bell-value', 0, 'hero', '{"eyebrow":"Value · Retired · 2004 – 2008","title":"Big Bell Value Menu","subtitle":null,"subtitle_meta":null,"desc":"The answer to McDonald''s Dollar Menu wasn''t a dollar — it was a half-pound. Launched February 2004, the Big Bell Value Menu won the early-2000s value war through sheer portion size rather than rock-bottom pricing.","stats":[{"num":"2004","label":"Launched"},{"num":"99¢","label":"Starting price"},{"num":"½ lb","label":"Signature format"},{"num":"Retired","label":"Status","color":"#9ca3af"}],"search":false,"search_placeholder":null,"spotlight":null,"feature":null}'::jsonb),
  ('taco-bell', 'taco-bell-menu-big-bell-value', 1, 'overview', '{"tone":"a","heading":"Win on weight, not on cents.","paragraphs":["The Big Bell Value Menu launched on <strong>February 2004</strong> as Taco Bell''s calculated response to the early-2000s fast-food value wars. McDonald''s Dollar Menu — introduced in 2002 — had set the industry reference point: one dollar, one item, no negotiation. Burger King and Wendy''s followed with comparable offerings. Rather than match them dollar-for-dollar, Taco Bell''s strategy was to reframe the value equation entirely. Instead of asking \"is this cheap?\" the Big Bell Value Menu asked \"how much do you get?\" The answer, on most items, was a half pound — a portion size that made the comparable Dollar Menu burger look visibly inadequate.","The menu launched with nine permanent items, five of which were billed as \"grande\" or \"½ lb\" to foreground their size advantage — three half-pound burritos, the Grande Soft Taco, and the Double Decker Taco. The Cheesy Double Beef Burrito — filled with a double portion of seasoned beef and nacho cheese sauce — became the program''s signature item and its most enduring legacy. The Caramel Apple Empanada anchored the dessert slot, and the Beef Combo Burrito gave the menu a low-cost beef-and-bean entry point at 99¢. Prices ranged from 99¢ to approximately $1.29 across the lineup.","The timing was deliberately competitive. In 2003, Taco Bell''s same-store sales had been under pressure from the broader QSR value push, and the brand needed a value narrative that was both differentiated and operationally executable at scale. The Big Bell Value Menu achieved both: it used existing kitchen infrastructure and inventory, required no new equipment, and communicated its advantage through menu board language (\"grande,\" \"½ lb\") rather than through price comparison. <em>Volume</em> was the positioning — the consumer''s sense that they were getting substantially more than a dollar could buy at a burger chain.","The program ran from 2003 until <strong>2008</strong>, when the 2008 recession prompted a strategic pivot. As consumer disposable income contracted sharply, the \"½ lb for 99¢\" pitch was superseded by a more urgent proposition: exact pocket-change pricing at three rigid tiers. The Big Bell Value Menu was retired and replaced by the <strong>79¢ / 89¢ / 99¢ \"Why Pay More!?\" Value Menu</strong> — same franchise, different economic moment, fundamentally different strategy. Several Big Bell items carried forward into the Why Pay More lineup, including the Cheesy Double Beef Burrito and Caramel Apple Empanada, but the \"grande\" branding and volume-first positioning did not."],"infobox":null}'::jsonb),
  ('taco-bell', 'taco-bell-menu-big-bell-value', 2, 'catalog', '{"title":"Every Big Bell item","unit":"item","visual":"catalog","tone":"b","note":"99¢ – $1.29","categories":[{"name":"½ lb heavy burritos","color":18,"items":[{"name":"½ lb. Cheesy Double Beef Burrito","info":"$1.19–$1.29","desc":"The signature item of the Big Bell Value Menu. A large flour tortilla packed with a double portion of seasoned beef, warm nacho cheese sauce, seasoned rice, and reduced-fat sour cream — a build substantially more filling than a competing dollar-tier burger. This item carried directly into the Why Pay More!? menu in 2008 at the 89¢ tier and survived into the Cravings era.","groups":[{"label":"Ingredients","pills":["Large flour tortilla","Seasoned beef (double portion)","Nacho cheese sauce","Seasoned rice","Reduced-fat sour cream"]}]},{"name":"½ lb. Beef & Potato Burrito","info":"$1.19","desc":"A half-pound burrito pairing seasoned beef with crispy potato bites, warm nacho cheese sauce, and sour cream in a flour tortilla. The potato component extended perceived volume at low wholesale cost — a high-margin combination that let the item compete on portion size while protecting food cost.","groups":[{"label":"Ingredients","pills":["Flour tortilla","Seasoned beef (double portion)","Crispy potato bites","Nacho cheese sauce","Sour cream"]}]},{"name":"½ lb. Spicy Chicken Burrito","info":"$1.19","desc":"The chicken variant in the ½ lb tier — shredded spicy chicken, seasoned rice, and a heavy drizzle of Creamy Jalapeño sauce in a warm flour tortilla. The Creamy Jalapeño sauce differentiates it from the Spicy Chicken Soft Taco in the Grande tier.","groups":[{"label":"Ingredients","pills":["Flour tortilla","Shredded spicy chicken","Seasoned rice","Creamy Jalapeño sauce"]}]}]},{"name":"Grande &amp; multi-layer specialties","color":15,"items":[{"name":"Grande Soft Taco","info":"99¢","desc":"The defining structural feature of the Grande Soft Taco was two flour tortillas bonded together with a layer of warm nacho cheese sauce — a soft-on-soft counterpart to the Double Decker Taco''s crunchy-shell architecture. The nacho cheese adhesive was then topped with a double portion of seasoned beef, shredded lettuce, and cheddar cheese. The ''Grande'' designation referred to the layered dual-shell format as much as portion size.","groups":[{"label":"Ingredients","pills":["Flour tortilla (outer)","Warm nacho cheese sauce (adhesive layer)","Flour tortilla (inner)","Seasoned beef (double portion)","Shredded lettuce","Cheddar cheese"]}]},{"name":"Double Decker Taco","info":"99¢","desc":"A crunchy corn taco shell filled with seasoned beef, shredded lettuce, and cheddar cheese, nested inside a soft flour tortilla — the two shells bonded together by a thick layer of warm refried beans serving as structural adhesive.","groups":[{"label":"Ingredients","pills":["Soft flour tortilla (outer)","Warm refried beans (structural adhesive)","Crunchy corn shell (inner)","Seasoned beef","Shredded cheddar","Shredded lettuce"]}]},{"name":"Spicy Chicken Soft Taco","info":"99¢","desc":"Distinct from the ½ lb. Spicy Chicken Burrito — a taco-format item with shredded spicy chicken, shredded lettuce, and a fresh scoop of Fiesta Salsa (pico de gallo) in a soft flour tortilla. The Fiesta Salsa build gives it a lighter, fresher character than its burrito counterpart.","groups":[{"label":"Ingredients","pills":["Soft flour tortilla","Shredded spicy chicken","Shredded lettuce","Fiesta Salsa (pico de gallo)"]}]}]},{"name":"Value classics &amp; sweet additions","color":16,"items":[{"name":"Cheesy Bean and Rice Burrito","info":"89¢","desc":"Warm refried beans, seasoned rice, nacho cheese sauce, and Creamy Jalapeño sauce rolled in a soft flour tortilla. The dual-sauce component gave this Big Bell era build a richer, more layered flavour profile than later iterations on successor menus.","groups":[{"label":"Ingredients","pills":["Flour tortilla","Warm refried beans","Seasoned rice","Nacho cheese sauce","Creamy Jalapeño sauce"]}]},{"name":"Beef Combo Burrito","info":"89¢–99¢","desc":"Seasoned beef, warm refried beans, a splash of red sauce, and cheddar cheese rolled into a soft flour tortilla. A combination burrito rooted in Taco Bell''s earliest menu architecture — the beef-and-bean burrito in its most direct form.","groups":[{"label":"Ingredients","pills":["Soft flour tortilla","Seasoned beef","Warm refried beans","Red sauce","Cheddar cheese"]}]},{"name":"Caramel Apple Empanada","info":"89¢–99¢","desc":"A crispy, golden-brown deep-fried pastry turnover filled with warm diced apples and a rich caramel sauce pocket, dusted with cinnamon sugar. The dessert anchor of the Big Bell Value Menu and one of the few items with genuine longevity — present here in 2003 and carried through the Why Pay More!? era and beyond.","groups":[{"label":"Ingredients","pills":["Fried pastry shell (golden-brown)","Warm diced apple filling","Caramel sauce pocket","Cinnamon sugar dusting"]}]}]},{"name":"Late-era promotional rotations","color":17,"items":[{"name":"Extreme Cheese & Beef Quesadilla","info":"$1.29","desc":"A limited-time addition (2006–2007) as corporate tested cheese-forward formats ahead of the 2008 platform transition. A flat-pressed quesadilla layered with seasoned beef, nacho cheese sauce, and a melted three-cheese blend of cheddar, mozzarella, and pepper jack.","groups":[{"label":"Ingredients","pills":["Flour tortilla (flat-pressed)","Seasoned beef","Nacho cheese sauce","Cheddar cheese","Mozzarella","Pepper jack cheese"]}]}]}]}'::jsonb)
) as v(wiki_id, page_id, position, component, data)
where not exists (select 1 from public.sections s
  where s.wiki_id = 'taco-bell' and s.page_id = 'taco-bell-menu-big-bell-value');

-- ── taco-bell / taco-bell-menu-luxe-value (3 sections) ──
insert into public.pages (wiki_id, id, slug, title, type) values
  ('taco-bell', 'taco-bell-menu-luxe-value', 'taco-bell-menu-luxe-value.html', 'Luxe Value Menu', 'standard')
on conflict (wiki_id, id) do update set slug = excluded.slug, title = excluded.title, type = excluded.type;
insert into public.sections (wiki_id, page_id, position, component, data)
select * from (values
  ('taco-bell', 'taco-bell-menu-luxe-value', 0, 'hero', '{"eyebrow":"Value · Active · Jan. 2026","title":"Luxe Value Menu","subtitle":null,"subtitle_meta":null,"desc":"Ten items. Three dollars or less. Five new creations paired with five Cravings Value Menu survivors — Taco Bell''s direct answer to the 2025 fast-food value wars and a deliberate repositioning of what \"cheap\" can mean at the chain.","stats":[{"num":"$3","label":"Price ceiling"},{"num":"10","label":"Items"},{"num":"Jan ''26","label":"Launched"},{"num":"Active","label":"Status","color":"#86efac"}],"search":false,"search_placeholder":null,"spotlight":null,"feature":null}'::jsonb),
  ('taco-bell', 'taco-bell-menu-luxe-value', 1, 'overview', '{"tone":"a","heading":"Value that doesn''t taste like it.","paragraphs":["The Luxe Value Menu launched nationwide on <strong>January 22, 2026</strong>, replacing the Cravings Value Menu that had anchored Taco Bell''s value tier since 2014. The name was deliberate: \"luxe\" as a direct reframe of what fast-food value positioning could communicate. Where the Cravings menu had emphasised familiarity and affordability, the Luxe menu was designed to carry a premium connotation — the idea that a $2.49 item could feel like an indulgence rather than a fallback. The menu was first teased at Live Más Live 2025 and formally announced on January 13, 2026, with Rewards member early access running from January 16.","The programme was tested in <strong>Indianapolis, Indiana</strong> beginning July 17, 2025 — the same regional-test-then-national-rollout cadence Taco Bell used for the Cantina Chicken Menu in 2024. The Indianapolis test ran five new items alongside five Cravings holdovers, giving corporate a direct read on which innovations held up operationally before committing to a national launch. The nationwide rollout replicated the test menu''s structure almost exactly: the same five new items, the same five carried-forward items, with the Avocado Ranch Chicken Stacker''s name refined from \"Chipotle Ranch Chicken Stacker\" in the test to the final version.","The competitive context was explicit. By 2025, every major QSR chain had launched or reaffirmed a sub-$3 value tier in response to consumer price sensitivity following several years of industry-wide menu inflation. McDonald''s, Burger King, and Wendy''s had all made high-profile value commitments. Taco Bell''s CMO Luis Restrepo framed the Luxe launch directly against this backdrop: <em>\"This isn''t just a menu refresh, it''s a new standard for value at Taco Bell and across the industry.\"</em> The ten-item ceiling of $3 — versus the previous Cravings menu''s $1–$3 spread — positioned the Luxe menu as a more coherent, easier-to-communicate value proposition on the menu board.","The five carried-forward items — Cheesy Roll Up, Spicy Potato Soft Taco, Cheesy Bean and Rice Burrito, 3 Cheese Chicken Flatbread Melt, and Cheesy Double Beef Burrito — were not accidents. Each had ranked among the highest-volume items on the Cravings menu, meaning the transition preserved the operational infrastructure already in place while the five new items introduced the format diversity that justified the \"luxe\" positioning. The <strong>Salted Caramel Churros</strong>, the only limited-time item in the launch lineup and its lowest price point at $1.99, served as an accessible entry point and a social-media-friendly novelty simultaneously."],"infobox":null}'::jsonb),
  ('taco-bell', 'taco-bell-menu-luxe-value', 2, 'catalog', '{"title":"Every item on the Luxe lineup","unit":"item","visual":"catalog","tone":"b","note":"all $3 or less","categories":[{"name":"New additions","color":14,"items":[{"name":"Mini Taco Salad","status":"active","info":"$2.49","desc":"A new take on the classic taco salad in a compact format — seasoned beef, creamy Chipotle Sauce, cheddar cheese, shredded lettuce, diced tomatoes, and refried beans in a crispy, golden tortilla bowl. First teased at Live Más Live 2025 before the Indianapolis test in July 2025.","groups":[{"label":"Ingredients","pills":["Crispy golden tortilla bowl","Seasoned beef","Creamy Chipotle Sauce","Cheddar cheese","Shredded lettuce","Diced tomatoes","Refried beans"]}]},{"name":"Beefy Potato Loaded Griller","status":"active","info":"$2.49","desc":"A grilled burrito format loaded with seasoned beef, seasoned potato bites, and warm nacho cheese sauce. The griller format — a tightly wrapped, grilled-on-the-outside burrito — gives the item its distinctive crisp exterior without the complexity of a quesadilla press.","groups":[{"label":"Ingredients","pills":["Flour tortilla (grilled)","Seasoned beef","Seasoned potato bites","Nacho cheese sauce"]}]},{"name":"Chips & Nacho Supreme Dip","status":"active","info":"$2.49","desc":"Seasoned tortilla chips served with a warm, loaded nacho dip featuring seasoned beef, refried beans, sour cream, and nacho cheese sauce. Positions the Luxe menu in the shareable/snack occasion typically dominated by the Nachos format.","groups":[{"label":"Ingredients","pills":["Seasoned tortilla chips","Nacho cheese sauce","Seasoned beef","Refried beans","Sour cream"]}]},{"name":"Avocado Ranch Chicken Stacker","status":"active","info":"$2.99","desc":"The highest-priced item on the Luxe Value Menu and the one most directly aimed at the premium-value consumer. Grilled chicken, avocado ranch sauce, cheddar cheese, and shredded lettuce in a stacked tortilla format. Note: in the July 2025 Indianapolis test, this item was called the Chipotle Ranch Chicken Stacker — the sauce was reformulated and the name updated before the national launch.","groups":[{"label":"Ingredients","pills":["Flour tortilla","Grilled chicken","Avocado ranch sauce","Cheddar cheese","Shredded lettuce"]}]}]},{"name":"Cravings carry-overs","color":15,"items":[{"name":"Cheesy Roll Up","status":"active","info":"$1.19","desc":"The lowest-priced item on the Luxe Value Menu and one of the simplest items on the entire Taco Bell menu — a warm flour tortilla rolled around a three-cheese blend. A Cravings Value Menu original, retained as the accessible entry point of the Luxe lineup.","groups":[{"label":"Ingredients","pills":["Flour tortilla","Three-cheese blend (warm)"]}]},{"name":"Spicy Potato Soft Taco","status":"active","info":"$1.29","desc":"Crispy seasoned potato bites, chipotle sauce, lettuce, and cheddar cheese in a warm flour tortilla. A vegetarian item and a consistent top-performer on the Cravings menu, retained in full on the Luxe lineup.","groups":[{"label":"Ingredients","pills":["Flour tortilla","Crispy seasoned potato bites","Chipotle sauce","Shredded lettuce","Cheddar cheese"]}]},{"name":"Cheesy Bean and Rice Burrito","status":"active","info":"$1.49","desc":"Seasoned beans, seasoned rice, and a warm three-cheese blend in a flour tortilla. A fully vegetarian burrito and one of the lowest-cost complete-meal items in the fast-food segment at $1.49.","groups":[{"label":"Ingredients","pills":["Flour tortilla","Seasoned beans","Seasoned rice","Three-cheese blend"]}]},{"name":"3 Cheese Chicken Flatbread Melt","status":"active","info":"$2.29","desc":"Grilled chicken and a three-cheese blend melted on a warm flatbread. The flatbread format differentiates it from the tortilla-based items elsewhere on the menu, offering a different texture profile at a mid-tier price point.","groups":[{"label":"Ingredients","pills":["Flatbread","Grilled chicken","Three-cheese blend (melted)"]}]},{"name":"Cheesy Double Beef Burrito","status":"active","info":"$2.79","desc":"A double portion of seasoned beef with warm nacho cheese sauce in a flour tortilla. The highest-priced of the five Cravings carry-overs, and the most protein-forward item retained from the previous menu.","groups":[{"label":"Ingredients","pills":["Flour tortilla","Seasoned beef (double)","Nacho cheese sauce"]}]}]},{"name":"Limited-time","color":17,"items":[{"name":"Salted Caramel Churros","status":"limited","info":"$1.99","desc":"Crispy fried churro bites dusted with cinnamon sugar and drizzled with salted caramel sauce. The only limited-time item in the January 2026 launch lineup and the only dessert — positioned as the social-media-friendly novelty of the menu and its second-lowest price point. The LTO slot is designed to rotate new items through the year.","groups":[{"label":"Ingredients","pills":["Fried churro bites","Cinnamon sugar dusting","Salted caramel drizzle"]}]}]}]}'::jsonb)
) as v(wiki_id, page_id, position, component, data)
where not exists (select 1 from public.sections s
  where s.wiki_id = 'taco-bell' and s.page_id = 'taco-bell-menu-luxe-value');

-- ── taco-bell / taco-bell-slogans (2 sections) ──
insert into public.pages (wiki_id, id, slug, title, type) values
  ('taco-bell', 'taco-bell-slogans', 'taco-bell-slogans.html', 'Slogans', 'standard')
on conflict (wiki_id, id) do update set slug = excluded.slug, title = excluded.title, type = excluded.type;
insert into public.sections (wiki_id, page_id, position, component, data)
select * from (values
  ('taco-bell', 'taco-bell-slogans', 0, 'hero', '{"eyebrow":"Marketing · From the Archive","title":"Taco Bell Slogans","subtitle":null,"subtitle_meta":null,"desc":"Nine slogans across sixty-four years — the full archive of every era, from the 1977 debut tagline to Live Más, including the $42M lawsuit that ended the chihuahua campaign.","stats":[{"num":"9","label":"Slogans"},{"num":"62 yr","label":"Span"},{"num":"1962","label":"Founded"},{"num":"$42M","label":"Lawsuit"}],"search":false,"search_placeholder":null,"spotlight":null,"feature":null}'::jsonb),
  ('taco-bell', 'taco-bell-slogans', 1, 'overview', '{"tone":"b","heading":"From no tagline to Live Más.","paragraphs":["Taco Bell was founded by Glen Bell in Downey, California in 1962 and operated for fifteen years without a national advertising tagline, growing to more than a thousand locations on the strength of its menu and price point alone. That changed in 1977 when PepsiCo — which had acquired the chain the previous year — brought the marketing infrastructure required to push a coordinated national voice. <strong>The Fresh Food Place</strong> became the first tagline with genuine national reach.","What followed was a forty-year search for the right register. The 1980s moved quickly through four slogans in roughly a decade, each attempting to land on a differentiator — freshness, customisation, friendliness — before the chain discovered in 1988 that its most powerful advertising asset was atmosphere rather than product. <strong>Make a Run for the Border</strong> ran for six years and embedded itself in American vernacular, particularly among the late-night college audience.","The 1990s produced Taco Bell''s most studied campaign: <strong>Yo Quiero Taco Bell</strong> and Gidget the Chihuahua. Brand awareness hit record highs while same-store sales declined — a real-world demonstration that recognition and purchase intent are distinct quantities. The campaign was retired in 2001 and became the subject of a $42 million lawsuit over creative ownership.","<strong>Think Outside the Bun</strong> then ran for eleven years, the longest primary slogan in the chain''s history. In 2012, at the 50th anniversary mark, the chain replaced it with two words: <strong>Live Más.</strong> Launched alongside Doritos Locos Tacos — the best-selling product launch in fast-food history — the tagline repositioned Taco Bell from a food destination to a lifestyle brand. It is still active today."],"infobox":null}'::jsonb)
) as v(wiki_id, page_id, position, component, data)
where not exists (select 1 from public.sections s
  where s.wiki_id = 'taco-bell' and s.page_id = 'taco-bell-slogans');

-- ── apple / apple-home (2 sections) ──
insert into public.pages (wiki_id, id, slug, title, type) values
  ('apple', 'apple-home', 'apple.html', 'Apple', 'home')
on conflict (wiki_id, id) do update set slug = excluded.slug, title = excluded.title, type = excluded.type;
insert into public.sections (wiki_id, page_id, position, component, data)
select * from (values
  ('apple', 'apple-home', 0, 'hero', '{"eyebrow":"Visual Wiki · Vol. 3","title":"Apple","subtitle":null,"subtitle_meta":null,"desc":"Founded April 1, <strong>1976</strong> on Crist Drive in Los Altos by Steve <strong>Jobs</strong>, Steve Wozniak, and Ronald Wayne. Forty-nine years later the same company sells nearly a billion handheld computers a year and is, by market value, the largest single business in human history.","stats":[{"num":"1,142","label":"Entries"},{"num":"1976","label":"Founded"},{"num":"$3.66T","label":"Market cap"},{"num":"164K","label":"Employees"}],"search":true,"search_placeholder":"Search 1,142 entries — try ''iPhone'', ''iPod touch 4G'', ''Mac mini''…","spotlight":{"eyebrow":"★ Spotlight","title":"iPhone","desc":"The handheld computer that redefined consumer electronics. Launched in 2007 — 18 years and 3 billion units later, Apple''s most defining product and the largest single-revenue product line in human history.","tags":["2007","Flagship","$200B+/yr"],"cta":"Open entry →"},"feature":null}'::jsonb),
  ('apple', 'apple-home', 1, 'overview', '{"tone":"b","heading":"A company built on the bitten apple, the bezier curve, and the relentless deletion of anything that doesn''t ship.","paragraphs":["<strong>Apple Inc.</strong> is an American technology company headquartered in Cupertino, California. It designs and sells consumer electronics, computer software, online services, and — since 2020 — its own silicon. The company is structured around vertical integration across hardware, software, and services, a model Steve Jobs called \"the whole widget.\"","Apple''s history splits cleanly into five eras. The <strong>founding period</strong> (1976–1985) produced the Apple I, II, and the original 1984 Macintosh. The <strong>wilderness years</strong> (1985–1997) saw three CEOs and a billion-dollar loss. The <strong>restoration</strong> (1997–2007) brought the iMac, OS X, and the iPod. The <strong>iPhone era</strong> (2007–2011) reshaped consumer electronics globally. The <strong>Cook era</strong> (2011–present) made Apple the first company to cross $1T, $2T, and $3T in market capitalisation."],"infobox":{"label":null,"title":"Apple Inc.","sublabel":null,"rows":[["Founded","April 1, 1976"],["Founders","Jobs · Wozniak · Wayne"],["HQ","1 Apple Park Way, Cupertino"],["CEO","Tim Cook (Aug 2011 –)"],["Ticker","NASDAQ: AAPL"],["Revenue","$391.0B (FY24)"],["Employees","164,000"]],"badge":null}}'::jsonb)
) as v(wiki_id, page_id, position, component, data)
where not exists (select 1 from public.sections s
  where s.wiki_id = 'apple' and s.page_id = 'apple-home');

-- ── apple / apple-ipod-touch-2g (12 sections) ──
insert into public.pages (wiki_id, id, slug, title, type) values
  ('apple', 'apple-ipod-touch-2g', 'apple-ipod-touch-2g.html', 'iPod touch (2nd gen)', 'standard')
on conflict (wiki_id, id) do update set slug = excluded.slug, title = excluded.title, type = excluded.type;
insert into public.sections (wiki_id, page_id, position, component, data)
select * from (values
  ('apple', 'apple-ipod-touch-2g', 0, 'hero', '{"eyebrow":"iPod touch · 2nd Generation · 2008 – 2010","title":"iPod touch","subtitle":"(2nd generation)","subtitle_meta":"Model A1288","desc":"The second iPod touch fixed the most glaring omission of the first:\n        it arrived with a <strong>built-in speaker</strong>. Redesigned with a\n        rounded stainless back that echoed the iPhone 3G, it also added\n        <strong>Nike+ wireless</strong> support without an adapter, external\n        volume buttons, and a flush headphone jack. The same 3.5-inch display.\n        Faster internals. A shape refined enough to last as the template for\n        the next several generations.","stats":[{"num":"Sep 2008","label":"Released"},{"num":"128 MB","label":"RAM"},{"num":"8–32 GB","label":"Storage"},{"num":"~2 yrs","label":"Lifespan"}],"search":false,"search_placeholder":null,"spotlight":null,"feature":null}'::jsonb),
  ('apple', 'apple-ipod-touch-2g', 1, 'overview', '{"tone":"a","heading":"The first iPod touch that felt finished.","paragraphs":["The original iPod touch launched in 2007 as a screen-first proposition — a pocket-sized multi-touch display for music, the web, and eventually apps. It was remarkable hardware for its moment, but it shipped with one obvious gap: <strong>no speaker</strong>. Listening required headphones, always. The second generation closed that gap, and in doing so made the device feel categorically more useful.","Announced on <strong>September 9, 2008</strong> at Apple''s \"Let''s Rock\" music-focused media event, the second-generation touch debuted alongside updated iPod nano and iPod classic models. It shipped the same day at $229 (8 GB), $299 (16 GB), and $399 (32 GB). The price positioned it squarely as a premium music device — not a phone, but closer to the total iPhone experience than anything else Apple made.","The redesign was substantial. The flat aluminum back of the first generation gave way to a <strong>polished stainless steel curved back</strong> that matched the iPhone 3G''s aesthetic. The device became 30% thinner — 8.5 mm at its thickest, tapering toward the edges — and lighter at 115 grams. External volume buttons appeared on the left edge for the first time, the headphone jack was recessed flush with the casing, and the internal speaker sat behind a small grille at the top of the back panel.","<strong>Nike+ wireless support</strong> arrived without any external adapter. Where the original required a small receiver plugged into the dock connector to communicate with Nike+ sensor-equipped shoes, the second generation handled it natively over a built-in wireless module. For runners already in the Nike+ ecosystem, this alone was a meaningful upgrade.","Internally, the device carried a Samsung-manufactured ARM processor running at 533 MHz — faster than its predecessor — paired with 128 MB of RAM. It launched running <strong>iPhone OS 2.1</strong> with full App Store access, a category the original touch received only via a $9.95 paid software update in 2008. The second generation had it from day one.","Software support extended through <strong>iOS 4.2.1</strong>, released in November 2010 — a notably extended lifespan for a device discontinued in June of that year. After discontinuation, the third generation (September 2009) continued with the same external design, differing primarily in processor speed. The second generation''s form factor was, in effect, the template that defined the iPod touch''s look for four years."],"infobox":{"label":null,"title":"iPod touch","sublabel":null,"rows":[["Model","A1288"],["Developer","Apple Inc."],["Generation","2nd of 7"],["Announced","September 9, 2008"],["Released","September 9, 2008"],["Predecessor","iPod touch (1st gen)"],["Successor","iPod touch (3rd gen)"],["Event","Let''s Rock · Sep 9, 2008"],["OS at launch","iPhone OS 2.1"],["Max OS","iOS 4.2.1"],["Processor","Samsung ARM 533 MHz"],["RAM","128 MB"],["Storage","8 · 16 · 32 GB"],["Display","3.5-inch IPS · 480×320 · 163 ppi"],["Dimensions","110 × 61.8 × 8.5 mm"],["Weight","115 g (4.05 oz)"],["Speaker","Mono (first iPod touch with speaker)"],["Nike+ wireless","Built-in (no adapter required)"],["Battery","36 hrs audio · 6 hrs video"],["Price at launch","$229 · $299 · $399"],["Colors","Polished stainless steel (black)"]],"badge":"Discontinued · June 2010"}}'::jsonb),
  ('apple', 'apple-ipod-touch-2g', 2, 'photo-rail', '{"photos":[{"src":"https://photos2.insidercdn.com/ipod-touch-2g-unbox-1.jpg","alt":"iPod touch 2G unboxing","strong":"Unboxing","source":"· 2008"},{"src":"https://i.redd.it/ipod-touch-2nd-gen-v0-bsz39n8xtl2h1.jpg?width=3024&format=pjpg&auto=webp&s=f2ee8d5051c4e3c4fc3a25c61c69eb9916814576","alt":"iPod touch 2nd gen","strong":"iPod touch 2G","source":"· Reddit"},{"src":"https://i.redd.it/my-new-ipod-touch-2nd-generation-v0-itxpy328f5be1.jpg?width=3024&format=pjpg&auto=webp&s=af4673bd34b3a92451c708609d6642686313df63","alt":"My new iPod touch 2G","strong":"New arrival","source":"· Reddit"},{"src":"https://files.lesterchan.net/images/apple/ipod_touch_2g.jpg","alt":"iPod touch 2G","strong":"iPod touch 2G","source":"· lesterchan.net"},{"src":"https://media.512pixels.net/wp-content/uploads/2017/09/touch-gen-2-and-3.jpg","alt":"iPod touch 2G and 3G","strong":"2G and 3G","source":"· 512pixels"},{"src":"https://allaboutstevejobs.com/resources/img/pics/2008-09-09_04117.jpg","alt":"Steve Jobs iPod touch 2G announcement 2008","strong":"Let''s Rock · Sep 9, 2008","source":"· Steve Jobs"}]}'::jsonb),
  ('apple', 'apple-ipod-touch-2g', 3, 'timeline', '{"heading":"Every milestone,<br>in order.","visual":"timeline","events":[{"month":"Jul","day":"11","year":"2008","tag":"Software","title":"App Store launches.","preview":"500 apps. The 2G ships into a live ecosystem — and unlike 1st gen owners, pays nothing to access it.","body":"<p>Apple’s App Store opened alongside iPhone OS 2.0, transforming the iPod touch from a fixed-feature device into a software platform. At launch, approximately 500 apps were available. For iPod touch 1st generation owners, accessing the App Store required a $9.95 paid software update. The 2nd generation, launching two months later, shipped with App Store access built in at no charge. By the time the 2G went on sale, the store had already recorded 60 million downloads.</p>"},{"month":"Sep","day":"9","year":"2008","tag":"Launch","title":"iPod touch 2G unveiled.","preview":"Contoured stainless back. Speaker. Volume buttons. Nike+. Ships same day at $229, $299, $399.","body":"<p>At the Yerba Buena Center for the Arts in San Francisco, Apple introduced the 2nd generation iPod touch at its “Let’s Rock” keynote. A contoured, polished stainless steel back replaced the flat aluminum of the original, tapering toward the edges. Physical volume buttons appeared on the left edge for the first time. A mono speaker sat behind a grille at the top. Nike+iPod support was built in natively.</p><p>The device shipped the same day it was announced — running iPhone OS 2.1.1 out of the box, with full App Store access. Pricing was $229 (8GB), $299 (16GB), and $399 (32GB).</p>"},{"month":"Nov","day":"21","year":"2008","tag":"Software","title":"iPhone OS 2.2.","preview":"Street View in Maps. Transit routing. Podcast downloads over WiFi.","body":"<p>iPhone OS 2.2 was the first significant update the 2G received after launch. Google Street View was integrated into Maps. Public transit routing was added. Podcast downloading came to the iTunes app, letting users subscribe and receive episodes over WiFi without syncing to a computer.</p>"},{"month":"Feb","day":"5","year":"2009","tag":"Milestone","title":"20 million iPod touches sold.","preview":"Holiday demand for the 2G cited as the primary driver. A market validated fast.","body":"<p>Apple publicly announced that cumulative iPod touch sales had reached 20 million units worldwide. The 2nd generation model was credited as the primary driver of that demand surge — the redesigned form factor and native App Store access had significantly broadened the device’s appeal.</p>"},{"month":"Mar","day":"17","year":"2009","tag":"Software","title":"iPhone OS 3.0 previewed.","preview":"Bluetooth unlocked — the chip was always there, silently waiting.","body":"<p>At Apple’s campus in Cupertino, the company previewed iPhone OS 3.0. Among the announcements specific to the 2G: the update would unlock Bluetooth functionality — not by adding new hardware, but by enabling a Samsung/Broadcom chip that had been present inside the device from launch, silently dormant.</p>"},{"month":"Jun","day":"17","year":"2009","tag":"Software","title":"iPhone OS 3.0 ships.","preview":"Cut, copy, paste. Bluetooth gaming. Costs iPod touch users $9.95.","body":"<p>iPhone OS 3.0 was released as a free update for iPhone users. iPod touch owners were charged $9.95. Apple cited Sarbanes-Oxley accounting rationale. On the 2G, the update delivered cut, copy, and paste, Spotlight search, peer-to-peer Bluetooth gaming, and parental controls.</p>"},{"month":"Sep","day":"9","year":"2009","tag":"Hardware","title":"Lineup revised. MC model arrives.","preview":"16GB and 32GB discontinued. Revised 8GB MC at $199 patches the BootROM exploit.","body":"<p>Apple permanently discontinued the original 16GB and 32GB iPod touch 2G models. In their place, Apple introduced a revised 8GB model — the “MC” series (MC086LL/A) — distinguishable from the original “MB” line by an updated BootROM that patched a hardware-level jailbreak exploit. The revised model shipped at $199 with iPhone OS 3.1 pre-installed.</p>"},{"month":"Feb","day":"2","year":"2010","tag":"Software","title":"iPhone OS 3.1.3.","preview":"The last update the 2G runs without performance degradation.","body":"<p>iPhone OS 3.1.3 brought minor bug fixes and security patches. For the 2G specifically, it is widely regarded as the final software version the device ran without meaningful performance degradation — the hardware’s 128MB of RAM and ARMv6 processor were still adequate at this version.</p>"},{"month":"Jun","day":"21","year":"2010","tag":"Software","title":"iOS 4.0 — free, but limited.","preview":"First free major upgrade. No multitasking, no wallpapers. Hardware ceiling reached.","body":"<p>Apple released iOS 4.0 — the first time a major version upgrade was delivered to iPod touch users free of charge. Because the 2G featured only 128MB of RAM and an older ARMv6 processor, it could not support multitasking, custom home screen wallpapers, or Bluetooth keyboard support.</p>"},{"month":"Sep","day":"1","year":"2010","tag":"Hardware","title":"iPod touch 2G discontinued.","preview":"The 8GB MC model pulled. Entire 2nd generation family ends production.","body":"<p>On September 1, 2010, Apple removed the iPod touch 2nd generation 8GB MC model from sale, ending production for the entire 2nd generation family. Software support continued for another fourteen months.</p>"},{"month":"Nov","day":"22","year":"2010","tag":"Software","title":"iOS 4.2.1 — the final OS.","preview":"Game Center. AirPlay audio. The last software this hardware will ever run.","body":"<p>iOS 4.2.1 served as the final operating system for the iPod touch 2nd generation. It brought Game Center, AirPlay audio streaming, and on-device playlist creation. The limitations remained: no multitasking, no wallpapers, no Bluetooth keyboard.</p>"},{"month":"Mar","day":"9","year":"2011","tag":"Software","title":"iOS 4.3 drops the 2G.","preview":"Device absent from the compatibility list. Official support ends permanently.","body":"<p>Apple released iOS 4.3 on March 9, 2011, and the iPod touch 2nd generation was entirely absent from the device compatibility list. This was the formal end of software support. App Store applications requiring iOS 4.3 or later were immediately inaccessible.</p>"},{"month":"Jun","year":"2011","tag":"Legacy","title":"End of life. 60M units.","preview":"Total iPod touch sales surpass 60 million. The 2G was the primary driver.","body":"<p>As the 2nd generation reached true end-of-life status, Apple’s metrics showed total iPod touch sales across all generations had surpassed 60 million units worldwide. The 2nd generation had been the primary driver of adoption.</p>"}]}'::jsonb),
  ('apple', 'apple-ipod-touch-2g', 4, 'delta', '{"heading":"What changed.<br>1st &#8594; 2nd generation.","intro":"The iPod touch 2nd generation was not a reinvention of the first — it was a completion of it. Every significant gap in the original was addressed: the missing speaker, the missing volume buttons, the recessed headphone jack, the external Nike+ receiver, the flat back that didn’t sit well in the hand. On the software side, the 2G shipped into a live App Store with 60 million downloads already recorded, with access included free on day one — no paid upgrade required.","footnote":"Specs: iPod touch 1st gen (A1213) · Sep 5, 2007 · $299 (8 GB), $399 (16 GB) &nbsp;/&nbsp; iPod touch 2nd gen (A1288) · Sep 9, 2008 · $229 (8 GB), $299 (16 GB), $399 (32 GB)","prev":{"name":"iPod touch (1st gen)","year":"September 2007"},"current":{"name":"iPod touch (2nd gen)","year":"September 2008"},"hardware":[{"label":"Back design","old":"Flat polished aluminum, uniform thickness throughout","new":"<strong>Curved polished stainless steel</strong>, tapered toward edges — same profile as iPhone 3G","chip":"changed","chip_text":"Redesigned"},{"label":"Speaker","old":"Not present. Headphones required for all audio.","new":"<strong>Built-in mono speaker</strong> — grille at top rear of device","no_old":true,"chip":"better","chip_text":"New"},{"label":"Volume buttons","old":"Not present. Volume controlled via on-screen slider only.","new":"<strong>Physical volume up/down</strong> on left edge","no_old":true,"chip":"better","chip_text":"New"},{"label":"Headphone jack","old":"Recessed — standard plugs didn’t fit. Required a flush adapter accessory.","new":"<strong>Flush with casing</strong> — any standard 3.5 mm plug fits directly","chip":"better","chip_text":"Flush"},{"label":"Nike+ wireless","old":"Supported via external dock connector receiver sold separately","new":"<strong>Built-in wireless module</strong> — no adapter or accessory required","chip":"feature","chip_text":"Native"},{"label":"Processor","old":"Samsung ARM11 · 400 MHz","new":"Samsung ARM11 · <strong>533 MHz</strong> — 33% faster","chip":"better","chip_text":"+33%"},{"label":"Bluetooth chip","old":"No Bluetooth hardware present at all","new":"<strong>Samsung/Broadcom chip present</strong> — dormant at launch, unlocked via iPhone OS 3.0 in June 2009","no_old":true,"chip":"better","chip_text":"New"},{"label":"Weight","old":"120 g (4.23 oz)","new":"<strong>115 g</strong> (4.05 oz) — 5 g lighter","chip":"better","chip_text":"−5 g"}],"software":[{"label":"Launch OS","old":"iPhone OS 1.1 — no App Store, no third-party apps","new":"<strong>iPhone OS 2.1.1</strong> — App Store included, third-party apps from day one","chip":"better","chip_text":"Newer"},{"label":"App Store access","old":"Not available at launch. Required a $9.95 paid upgrade when App Store launched July 2008.","new":"<strong>Included free from day one</strong> — no paid upgrade required","chip":"better","chip_text":"Free"},{"label":"Third-party apps","old":"None at launch. Web apps only. Paid update added access eight months in.","new":"<strong>Available at launch</strong> — 500+ apps on day one, 60M+ downloads already recorded by launch date","chip":"better","chip_text":"Day one"},{"label":"Maximum OS","old":"iPhone OS 3.1.3 — dropped before iOS 4","new":"<strong>iOS 4.2.1</strong> — one full major version further, support until November 2010","chip":"better","chip_text":"Further"},{"label":"Bluetooth","old":"Never available — no hardware present","new":"Chip present at launch. <strong>Unlocked via iPhone OS 3.0</strong> (June 2009) — peer-to-peer gaming, Bluetooth accessories","no_old":true,"chip":"better","chip_text":"New"},{"label":"Nike+ integration","old":"Supported via accessory. Required dock connector receiver; no native wireless support.","new":"<strong>Native wireless support</strong> — no receiver needed, works out of box with Nike+ sensor shoes","chip":"feature","chip_text":"Native"}]}'::jsonb),
  ('apple', 'apple-ipod-touch-2g', 5, 'config', '{"heading":"Four SKUs. One finish.<br>Only storage differs.","visual":"config","chart_title":"Storage configurations and launch pricing","intro":["The iPod touch 2nd generation was sold in a single finish — polished stainless steel with a black front bezel — across four distinct SKUs. At launch in September 2008, three storage tiers were available: <strong>8 GB, 16 GB, and 32 GB</strong>, priced at $229, $299, and $399 respectively. Every unit shared the same processor, RAM, display, speaker, Nike+ wireless, and battery.","All three launch models were discontinued simultaneously in September 2009, replaced by a single revised <strong>8 GB \"MC\" model</strong> at a new entry price of $199. The revision patched a hardware-level jailbreak exploit and shipped with iPhone OS 3.1 pre-installed."],"divider_label":"Revised model &middot; Sep 2009","footer":"All configurations: 533 MHz ARM &middot; 128 MB RAM &middot; 3.5&Prime; IPS 480&times;320 &middot; 36h audio &middot; 115 g &middot; Polished stainless steel &middot; Black front bezel","items":[{"capacity":8,"unit":"GB","model":"MB528LL/A","price":"$229","dates":"Sep 2008 &ndash; Sep 2009","colors":[{"name":"Silver","hex":"#d4d4d8","ring":true}]},{"capacity":16,"unit":"GB","model":"MB533LL/A","price":"$299","dates":"Sep 2008 &ndash; Sep 2009","colors":[{"name":"Silver","hex":"#d4d4d8","ring":true}]},{"capacity":32,"unit":"GB","model":"MB376LL/A","price":"$399","dates":"Sep 2008 &ndash; Sep 2009","colors":[{"name":"Silver","hex":"#d4d4d8","ring":true}]},{"capacity":8,"unit":"GB","model":"MC086LL/A &middot; Rev.","price":"$199","dates":"Sep 2009 &ndash; Sep 2010","revised":true,"colors":[{"name":"Silver","hex":"#d4d4d8","ring":true}]}]}'::jsonb),
  ('apple', 'apple-ipod-touch-2g', 6, 'prose-rail', '{"eyebrow":"Cultural impact","icon":"gamepad-2","anchor":"gaming-section","heading":"The gateway to<br>mobile gaming.","body":[{"text":"The iPod touch 2nd generation launched in September 2008 — two months after the App Store opened with 500 applications. Games were the dominant category from the start, and the 2G was the first iPod touch to ship with native App Store access. Where the 1st generation had been a music player that could browse the web, the 2nd generation arrived as a pocket gaming console that happened to play music."},{"text":"The timing was structurally significant. The 2G’s 3.5-inch multi-touch display, built-in accelerometer, and responsive capacitive screen made it a natural fit for the wave of touch-native games that defined the App Store’s first year: <strong>Tap Tap Revenge, Fieldrunners, Rolando, Flight Control</strong>. These were not ports of console games — they were designed from scratch for a touchscreen, and the iPod touch was the cheapest way to play them."},{"text":"Apple recognized this quickly. By 2009, the company’s marketing had shifted to position the iPod touch explicitly as a gaming device. The <strong>“Funnest iPod ever” campaign</strong> ran television spots showing games, not music. Steve Jobs showed game demos at keynote events. In multiple quarters between 2008 and 2010, iPod touch unit sales exceeded those of the Nintendo DS and Sony PSP."},{"text":"The absence of a cellular contract was the key. The iPhone cost $199 <em>plus</em> a two-year AT&T commitment at $60–100 per month. The iPod touch 2G cost $229 with no recurring cost. It introduced a generation of users to the concept that a pocket-sized touchscreen could be a primary gaming device — a market category that did not meaningfully exist before the App Store."}],"rail":{"title":"Archive","photos":[{"src":"https://allaboutstevejobs.com/resources/img/pics/2008-09_ipod_touch_2G_05865.jpg","alt":"iPod touch 2G launch event 2008","strong":"Let''s Rock · Sep 9, 2008"},{"src":"https://preview.redd.it/does-any-one-still-playing-games-with-ipod-touch-4-v0-yalmn8ts8cef1.jpeg?auto=webp&s=1a10b21d04de6af4d97e9323525c0d55017e003b","alt":"iPod touch gaming","strong":"Still gaming"},{"src":"https://lh3.googleusercontent.com/proxy/HQNC-iFbmZ3FepTv7j1Ux3EXjgO09Td_p7t1ApRxFL9leT1hpOjQ2bW0y8Klvs853hxr-JHMnF5iD724G2u5Vjx33fufhlRP0Pum","alt":"iPod touch App Store gaming era","strong":"App Store era"},{"src":"https://i.redd.it/facu419yvypf1.png","alt":"iPod touch nostalgia","strong":"Nostalgia"},{"src":"https://pbs.twimg.com/media/HBEVKY2WIAAu_dk.jpg?name=orig","alt":"iPod touch gaming collection","strong":"The collection"},{"src":"https://phonedb.net/img/gallery/apple_ipod_touch_2nd_generation_in_hand.jpg","alt":"iPod touch 2G in hand","strong":"iPod touch 2G in hand"},{"src":"https://media.guitarcenter.com/is/image/MMGS7/583425000000000-01-260x260.jpg","alt":"iPod touch 2G hardware","strong":"The hardware"}]}}'::jsonb),
  ('apple', 'apple-ipod-touch-2g', 7, 'prose-rail', '{"eyebrow":"Market positioning","icon":"users","anchor":"budget-section","heading":"The budget<br>smartphone alternative.","body":[{"text":"In 2008, the iPhone was not a mass-market device. It required an AT&T contract — the only carrier that sold it — at a minimum monthly cost of roughly $70. Over two years, the total cost of ownership exceeded $1,900. For a significant segment of the market, iOS was appealing but the economics were prohibitive."},{"text":"The iPod touch 2nd generation addressed this directly. At $229 for the entry model, with no contract, no monthly fee, and no carrier lock-in, the 2G delivered the core of the iPhone experience over WiFi: <strong>the same App Store, the same Safari, the same Maps, Mail, YouTube, Calendar, and Music</strong>. The only things missing were cellular data, a phone, and GPS."},{"text":"Apple announced <strong>20 million cumulative iPod touch sales</strong> by February 2009, less than five months after the 2G launched. The device found its largest audiences among <strong>students, teenagers, international users</strong> in countries where the iPhone had not yet launched, and cost-conscious consumers who wanted iOS without committing to a carrier."},{"text":"The revised 8GB model at $199 in September 2009 pushed this further. The iPod touch became the volume driver that expanded the iOS installed base beyond what the iPhone alone could have achieved — validating Apple’s belief that there was a market for a non-phone iOS device at a consumer price point."}]}'::jsonb),
  ('apple', 'apple-ipod-touch-2g', 8, 'prose-rail', '{"eyebrow":"Industrial design","icon":"palette","anchor":"design-section","heading":"Design blueprint<br>longevity.","body":[{"text":"The iPod touch 1st generation had a flat aluminum back, sharp edges, and a recessed headphone jack. The 2nd generation replaced all of it: a <strong>curved, polished stainless steel back that tapered toward the edges</strong>, matching the iPhone 3G''s silhouette. Volume buttons appeared on the left edge. The speaker sat behind a grille at the top. The headphone jack sat flush."},{"text":"This design became the template. The <strong>3rd generation</strong>, announced in September 2009, was externally identical: same curved back, same dimensions, same button placement, same speaker position. The only way to distinguish a 2G from a 3G was to check the model number."},{"text":"The <strong>4th generation</strong> in September 2010 added a Retina display, cameras, and the A4 chip but retained the fundamental design language: curved stainless back, chrome edge, front-face proportions. The 2G''s form factor defined what the iPod touch <em>looked like</em> for four consecutive hardware generations spanning 2008 through 2012."},{"text":"It was not until the <strong>5th generation</strong> in October 2012 that Apple broke the pattern entirely, introducing a thinner aluminum unibody with a 4-inch display. The stainless-and-chrome design language that the 2G had introduced was retired after four years."}],"rail":{"title":"Archive","photos":[{"src":"https://media.guitarcenter.com/is/image/MMGS7/249993000000000-00-2000x2000.jpg","alt":"iPod touch 2nd generation","strong":"iPod touch 2G · 2008"},{"src":"https://spaceforfreedom.wordpress.com/wp-content/uploads/2017/11/s-l1000.jpg?w=486&h=486","alt":"iPod touch 2nd generation detail","strong":"iPod touch 2G · detail"},{"src":"https://www.slashgear.com/img/gallery/apple-ipod-touch-2g-video-unboxing/intro-import.jpg","alt":"iPod touch 2G unboxing","strong":"iPod touch 2G · unboxing"}]}}'::jsonb),
  ('apple', 'apple-ipod-touch-2g', 9, 'lifecycle-lane', '{"heading":"Three major versions. Two eras.<br>One hardware ceiling.","title":"Software lifecycle: iPhone OS 2.1.1 through iOS 4.2.1","paragraphs":["The iPod touch 2nd generation shipped with <strong>iPhone OS 2.1.1</strong> in September 2008 and received its final update, <strong>iOS 4.2.1</strong>, in November 2010 — a support window of just over two years across ten distinct OS versions.","When <strong>iOS 4.0</strong> arrived in June 2010, it was the first major upgrade delivered free to iPod touch users. But the 2G received the new interface without three of iOS 4’s headline features: <strong>multitasking, custom home screen wallpapers, and Bluetooth keyboard support</strong>. The hardware’s memory and processor architecture simply could not sustain them.","When iOS 4.3 shipped in March 2011, the iPod touch 2nd generation was absent from the compatibility list entirely — not partially supported, simply gone. The App Store ecosystem began to move away within months."],"segments":[{"ver":"2.1.1","date":"Sep 2008","type":"full","badge":"Launch","badge_type":"ship"},{"ver":"3.0","date":"Jun 2009","type":"full","badge":"$9.95","badge_type":"paid"},{"ver":"4.0","date":"Jun 2010","type":"partial","badge":"Limited","badge_type":"limited"},{"ver":"4.2.1","date":"Nov 2010","type":"partial","badge":"Final","badge_type":"final"},{"ver":"4.3","date":"Mar 2011","type":"dropped","badge":"Dropped","badge_type":"dropped"}],"notes":[{"status":"final","label":"OS 3.0","text":"$9.95 paid upgrade for iPod touch users. Unlocked a dormant Bluetooth chip present since launch."},{"status":"limited","label":"iOS 4.0+","text":"No multitasking, no wallpapers, no Bluetooth keyboard. 128 MB RAM ceiling."},{"status":"final","label":"iOS 4.2.1","text":"Final update — a maintenance release, November 2010. The last build the 2nd generation ever ran."},{"status":"dropped","label":"iOS 4.3","text":"Device omitted from compatibility list. All future support ended."}]}'::jsonb),
  ('apple', 'apple-ipod-touch-2g', 10, 'prose-rail', '{"eyebrow":"Controversies","icon":"scale","anchor":"controversies-section","heading":"Known issues and<br>public disputes.","body":[{"icon":"lock","subtitle":"Paid software upgrades","text":"iPod touch users were charged $9.95 for the iPhone OS 2.0 update (App Store access) and $9.95 again for iPhone OS 3.0, while iPhone users received both for free. Apple attributed the fee to Sarbanes-Oxley accounting regulations. The explanation was legally defensible but commercially unpopular — particularly given that the 3.0 update unlocked Bluetooth hardware that had been physically present in their device since purchase."},{"icon":"cpu","subtitle":"Dormant Bluetooth chip","text":"The 2nd generation shipped with a Samsung/Broadcom Bluetooth chip inside every unit from September 2008 onward, but the chip was disabled at the firmware level. It was not enabled until iPhone OS 3.0 in June 2009 — nine months after launch. Apple never publicly explained why the chip shipped dormant. The decision to charge $9.95 to unlock hardware the user already owned compounded the controversy."},{"icon":"x","subtitle":"iOS 4 feature exclusions","text":"When iOS 4.0 was released in June 2010, the 2G received the update but was excluded from multitasking, custom home screen wallpapers, and Bluetooth keyboard support. Some users and developers disputed this, noting that jailbroken 2G units could run basic multitasking with acceptable performance, and that the wallpaper restriction in particular seemed more like a product decision than a hardware limitation."},{"icon":"shield","subtitle":"Jailbreak and BootROM exploit","text":"The original \"MB\" series models contained a hardware-level BootROM vulnerability that allowed unconditional jailbreaking — a persistent exploit that could not be patched via software update. Apple''s response was the revised \"MC\" model in September 2009 with a patched BootROM. The original MB units remained permanently exploitable, creating a secondary market where un-patched 2G units commanded a premium."},{"icon":"hourglass","subtitle":"Performance degradation on iOS 4","text":"Users who upgraded to iOS 4.0 widely reported slower performance and reduced responsiveness compared to iPhone OS 3.1.3. Apple did not offer a way to downgrade once the update was installed, leaving users on a version of the operating system their hardware was not fully equipped to run smoothly. This pattern would recur across Apple''s product line in later years and eventually result in regulatory scrutiny."}],"rail":{"title":"Press archive","photos":[{"src":"https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQ88lSJO-eWnlywawjggbaUy2Yp5ccD_ujrzw&s","alt":"Paid upgrade controversy","strong":"Paid upgrade controversy"},{"src":"https://i.ytimg.com/vi/MflAs6JDcWs/hq720.jpg?sqp=-oaymwEhCK4FEIIDSFryq4qpAxMIARUAAAAAGAElAADIQj0AgKJD&rs=AOn4CLBumKUJU4nUV9MS_p8pwfvGCyeV5w","alt":"iOS 4 performance issues","strong":"iOS 4 degradation"}]}}'::jsonb),
  ('apple', 'apple-ipod-touch-2g', 11, 'spec', '{"heading":"The complete sheet.","device":"iPod touch (2nd generation) · A1288","cards":[{"title":"General Device Info","icon":"globe","rows":[["Model number","A1288"],["Codename","iPod2,1"],["Generation","2nd"],["Released","September 9, 2008"]]},{"title":"Processor & memory","icon":"cpu","rows":[["CPU","Samsung S5L8720 · ARM11"],["Clock speed","533 MHz"],["RAM","128 MB DRAM"],["GPU","PowerVR MBX Lite"],["Architecture","ARMv6 (32-bit)"]]},{"title":"Display","icon":"monitor","rows":[["Size","3.5 inches"],["Type","TFT LCD, backlit"],["Resolution","480 × 320 px"],["Density","163 ppi"],["Input","Capacitive multi-touch"]]},{"title":"Storage & capacity","icon":"hard-drive","rows":[["Launch tiers","8 / 16 / 32 GB"],["Revised model","8 GB (MC086LL/A)"],["Type","NAND flash"],["Expandable","No"]]},{"title":"Connectivity","icon":"radio","rows":[["Wi-Fi","802.11 b/g"],["Bluetooth","2.1 + EDR (unlocked iOS 3.0)"],["Cellular","None"],["GPS","None"],["Port","30-pin dock connector"],["Audio jack","3.5 mm (flush)"]]},{"title":"Audio & sensors","icon":"music","rows":[["Speaker","Built-in mono"],["Accelerometer","Yes (3-axis)"],["Nike+","Built-in wireless"],["Formats","AAC, MP3, ALAC, AIFF, WAV"]]},{"title":"Physical","icon":"smartphone","rows":[["Height","110.0 mm"],["Width","61.8 mm"],["Depth","8.5 mm"],["Weight","115 g"],["Casing","Polished stainless steel"],["Front bezel","Black"]]},{"title":"Power","icon":"zap","rows":[["Battery","Built-in Li-ion rechargeable"],["Audio playback","Up to 36 hours"],["Video playback","Up to 6 hours"],["Charging","USB / dock connector"]]},{"title":"Software","icon":"layers","rows":[["Shipped with","iPhone OS 2.1.1"],["Final version","iOS 4.2.1"],["Major versions","2.x · 3.x · 4.x"],["Support window","Sep 2008 – Nov 2010"]]}]}'::jsonb)
) as v(wiki_id, page_id, position, component, data)
where not exists (select 1 from public.sections s
  where s.wiki_id = 'apple' and s.page_id = 'apple-ipod-touch-2g');

