insert into public.sections (wiki_id, page_id, position, component, data)
select * from (values
  ('apple', 'apple-ipod-touch-3g', 0, 'hero', '{"eyebrow":"iPod touch · 3rd Generation · 2009 – 2010","title":"iPod touch","subtitle":"(3rd generation)","subtitle_meta":"Model A1318","desc":"The third iPod touch wore the same face as the second but hid a fundamentally different machine inside. A new processor, doubled RAM, and a gaming-grade GPU transformed it from a music player that could run apps into something Apple had never explicitly made before: a <strong>dedicated handheld gaming device</strong>.","stats":[{"num":"Sep 2009","label":"Released"},{"num":"256 MB","label":"RAM"},{"num":"32–64 GB","label":"Storage"},{"num":"~1 yr","label":"Lifespan"}],"search":false,"search_placeholder":null,"spotlight":null,"feature":null}'::jsonb),
  ('apple', 'apple-ipod-touch-3g', 1, 'overview', '{"tone":"a","heading":"The fastest iPod touch ever made.","paragraphs":["The third-generation iPod touch was announced September 9, 2009 at Apple''s <strong>\"It''s Only Rock and Roll\"</strong> music event — the same event that introduced iTunes 9 and refreshed the iPod lineup. In a break from the iPhone-centric framing of previous iPod touch launches, Apple positioned the 3G almost entirely around gaming, benchmarking it against the Nintendo DS and PlayStation Portable.","Inside the unchanged aluminum and stainless steel chassis sat hardware borrowed directly from the <strong>iPhone 3GS</strong>: a Samsung ARMv7 Cortex-A8 core clocked at 600 MHz, the PowerVR SGX535 GPU with OpenGL ES 2.0 support, and 256 MB of RAM — double the 2nd generation''s ceiling. Apple called it \"50% faster.\" In practice the gap was wider, particularly in 3D games where the SGX535''s shader pipeline ran circles around the older MBX Lite.","The storage lineup contracted sharply. Gone was the 8 GB entry tier and the 16 GB mid-tier. The 3rd generation shipped in <strong>32 GB and 64 GB</strong> only — the latter the largest iPod touch Apple had ever shipped. Pricing held at $299 and $399.","One notable first: the 3rd generation was the first iPod touch to ship with <strong>earbuds that included a remote and microphone</strong>, enabling Voice Control — a feature previously exclusive to iPhone 3GS.","What Apple did not announce was a camera. Pre-release leaks, third-party case packaging at Best Buy, and a subsequent iFixit teardown all told the same story: the 3rd generation was designed to include a rear camera, the socket was physically present inside the device, and something — a manufacturing problem, a cost decision, or a strategic choice — removed it at the last moment. Apple said nothing.","iOS support extended to iOS 5.1.1, released May 2012 — nearly three years of updates. The device could not run iOS 6, which required ARMv7 features the 3G''s SoC technically met but Apple chose not to support."],"infobox":{"label":null,"title":"iPod touch","sublabel":null,"rows":[["Model","A1318"],["Developer","Apple Inc."],["Generation","3rd of 7"],["Announced","September 9, 2009"],["Released","September 9, 2009"],["Predecessor","iPod touch (2nd gen)"],["Successor","iPod touch (4th gen)"],["Event","\"It''s Only Rock and Roll\" · Sep 9, 2009"],["OS at launch","iPhone OS 3.1.1"],["Max OS","iOS 5.1.1"],["Processor","Samsung ARMv7 Cortex-A8 600 MHz"],["GPU","PowerVR SGX535"],["RAM","256 MB"],["Storage","32 · 64 GB"],["Display","3.5-inch IPS · 480×320 · 163 ppi"],["Dimensions","110 × 61.8 × 8.5 mm"],["Weight","115 g (4.05 oz)"],["Speaker","Mono built-in"],["Accessories","Earbuds with remote + mic (first)"],["Battery","30 hrs audio · 6 hrs video"],["Price","$299 · $399"]],"badge":"Discontinued · September 2010"}}'::jsonb),
  ('apple', 'apple-ipod-touch-3g', 2, 'timeline', '{"heading":"From game changer to end of line.","visual":"timeline","events":[{"month":"Sep","day":"9","year":"2009","tag":"Launch","title":"iPod touch 3G announced and available.","preview":"50% faster. 256 MB RAM. Gaming GPU. Philip Schiller pitches it against the DS and PSP.","body":"<p>Apple''s \"It''s Only Rock and Roll\" event unveiled the 3rd generation iPod touch. Philip Schiller led the introduction, positioning the device explicitly as a gaming platform and benchmarking it against the Nintendo DS and PlayStation Portable. The App Store already carried over 21,000 game titles.</p><p>Unlike previous iPod touch generations, the 3G launched and shipped on the same day. The 32 GB ($299) and 64 GB ($399) models were available immediately. An 8 GB model at $199 was also listed — but used 2nd generation internals, not the new Cortex-A8 hardware.</p>"},{"month":"Sep","day":"9","year":"2009","tag":"Hardware","title":"The 8GB discrepancy.","preview":"Apple lists an 8GB model. It is a 2nd generation device in everything but name.","body":"<p>Simultaneously with the keynote, Apple updated the entry-level price point with an 8 GB iPod touch at $199. This model did not carry the new 3rd generation internals — no Cortex-A8, no 256 MB RAM, no Voice Control hardware. It was the 2nd generation MC revision sold alongside the new device.</p><p>Apple never explicitly labelled it as 2nd generation in this context. Resellers and media compounded the confusion by listing it as a 3rd generation model. The distinction remained a persistent source of misidentification in secondary markets for years.</p>"},{"month":"Feb","day":"2","year":"2010","tag":"Software","title":"iPhone OS 3.1.3 — the last of the old naming.","preview":"Final update before Apple renames the platform iOS. Bug fixes and security patches.","body":"<p>iPhone OS 3.1.3 was the last software release to carry the \"iPhone OS\" name. It addressed battery accuracy reporting bugs and security vulnerabilities. No new features were introduced for iPod touch users.</p><p>The following summer, Apple rebranded the platform as iOS at WWDC 2010 — a deliberate move to signal that the operating system was no longer iPhone-centric. The 3rd generation iPod touch would receive every major iOS release through version 5.</p>"},{"month":"Apr","day":"8","year":"2010","tag":"Software","title":"iOS 4 preview — 3G confirmed for full support.","preview":"Multitasking and wallpapers confirmed for 3G. The 2G is explicitly cut off.","body":"<p>At Apple''s iOS 4 preview event, the company confirmed that the 3rd generation iPod touch would receive full iOS 4 support — including native multitasking and custom home screen wallpapers. The 2nd generation was explicitly excluded from both features due to hardware limitations.</p><p>This confirmation drew a clear line between the two generations. The 3G''s doubled RAM and Cortex-A8 architecture gave it the headroom the 2G lacked. For owners who had bought a 3G specifically for its internals, the announcement validated the purchase.</p>"},{"month":"Jun","day":"21","year":"2010","tag":"Software","title":"iOS 4.0 — full support, no upgrade fee.","preview":"App folders, multitasking, wallpapers. First iPod touch major update shipped free.","body":"<p>iOS 4 launched with complete feature support on the 3rd generation iPod touch. App folders, unified Mail, home screen wallpapers, and multitasking hooks all present — no exclusions, unlike the 2G''s stripped-down iOS 4 experience.</p><p>Critically, this was the first major iOS upgrade delivered free to iPod touch users. Previous major versions — iPhone OS 2.0 and 3.0 — had required a $9.95 purchase due to Sarbanes-Oxley accounting rules. Apple cited a change in revenue recognition methodology for dropping the fee.</p>"},{"month":"Sep","day":"1","year":"2010","tag":"Hardware","title":"iPod touch 3G discontinued.","preview":"One year on sale. Replaced by the 4th generation with Retina display and cameras.","body":"<p>Apple discontinued the 3rd generation iPod touch on September 1, 2010 — exactly one year after launch — replacing it with the 4th generation iPod touch. The 4G brought Apple''s A4 chip, a Retina display at 960×640, and both front and rear-facing cameras.</p><p>The camera inclusion on the 4G made the 3G''s missing-camera story feel retroactively stranger. Whatever had prevented a camera in September 2009 had been resolved by September 2010. Apple never commented on the gap.</p>"},{"month":"Sep","day":"8","year":"2010","tag":"Software","title":"iOS 4.1 — Game Center arrives.","preview":"Game Center launches on the 3G. Multiplayer matchmaking, leaderboards, achievements.","body":"<p>iOS 4.1 introduced Game Center to the 3rd generation iPod touch — Apple''s native multiplayer gaming platform with matchmaking, leaderboards, and achievements. The 3G''s 256 MB RAM and SGX535 GPU made it a capable Game Center device for most titles through 2011.</p><p>The update also introduced HDR photo capabilities on devices with cameras — the 3G had no camera, but received the rest of the iOS 4.1 feature set without issue.</p>"},{"month":"Nov","day":"22","year":"2010","tag":"Software","title":"iOS 4.2.1 — AirPlay and Find My iPod.","preview":"AirPlay, AirPrint, and free Find My iPod tracking come to the 3G.","body":"<p>iOS 4.2.1 brought AirPlay audio and video streaming, AirPrint wireless printing, and a free tier of Find My iPod touch — previously a paid MobileMe feature — to the 3rd generation. The update unified the iOS feature set across iPhone, iPod touch, and iPad for the first time.</p><p>This was the same version number that ended 2nd generation software support entirely. For 3G owners, it was simply another update in a continuing sequence that would run for nearly two more years.</p>"},{"month":"Mar","day":"9","year":"2011","tag":"Software","title":"iOS 4.3 — Nitro JavaScript engine.","preview":"Safari gets dramatically faster. Nitro engine transforms web browsing on the Cortex-A8.","body":"<p>iOS 4.3 integrated the Nitro JavaScript engine into mobile Safari, delivering a dramatic improvement in web performance on the 3rd generation''s Cortex-A8 processor. Benchmark scores roughly doubled. Pages that had felt sluggish loaded noticeably faster.</p><p>The update also brought iTunes Home Sharing improvements and Personal Hotspot — the latter iPhone-only, but the performance lift in Safari was universally felt. iOS 4.3 was the last significant feature update before iOS 5 completed the 3G''s software lifecycle.</p>"},{"month":"Oct","day":"12","year":"2011","tag":"Software","title":"iOS 5.0 — iCloud, iMessage, Notification Center.","preview":"The 3G''s penultimate major version. OTA updates arrive. Siri does not.","body":"<p>iOS 5 brought iCloud backup, iMessage Wi-Fi messaging, Notification Center, Reminders, and over-the-air updates to the 3rd generation iPod touch. It was the device''s penultimate major iOS version and the first update that could be applied without connecting to a computer.</p><p>Siri, introduced simultaneously on iPhone 4S, was not available on the 3G. The 256 MB RAM ceiling became increasingly visible under iOS 5 — Safari tabs reloaded more aggressively, and the system carried a heavier memory footprint than iOS 4. The device remained functional but was beginning to show its age.</p>"},{"month":"Nov","day":"8","year":"2011","tag":"Software","title":"iOS 5.0.1 — first OTA bug fix.","preview":"Battery life issues patched. The first purely over-the-air update Apple ever pushed.","body":"<p>iOS 5.0.1 addressed significant battery drain issues that had emerged after the iOS 5.0 launch, along with bug fixes for iCloud storage syncing and accessibility improvements. It was delivered entirely over the air — no iTunes connection required — marking a milestone in how Apple distributed software updates.</p><p>For 3G users, the battery fix was particularly relevant given the device''s already reduced audio playback time compared to the 2G.</p>"},{"month":"May","day":"7","year":"2012","tag":"Legacy","title":"iOS 5.1.1 — the final update.","preview":"Bug fixes. End of the line. iOS 6 will not follow.","body":"<p>iOS 5.1.1 was the last software update Apple delivered to the 3rd generation iPod touch. Released primarily as a stability and security fix — addressing iCloud syncing bugs, battery drainage, and Safari reliability — it closed the device''s software lifecycle at 32 months from launch.</p><p>iOS 6, announced in June 2012 and released in September, excluded the device entirely. The iPhone 3GS — sharing the same ARMv7 Cortex-A8 architecture — received iOS 6. No explanation was offered for the asymmetric treatment.</p>"},{"month":"Sep","day":"19","year":"2012","tag":"Legacy","title":"iOS 6 drops the 3G.","preview":"Same SoC family as iPhone 3GS, which got iOS 6. Apple said nothing.","body":"<p>iOS 6 launched alongside the iPhone 5 and 5th generation iPod touch, with no support for the 3rd generation. The device''s ARMv7 Cortex-A8 architecture nominally met the hardware requirements Apple cited for iOS 6 — the same SoC family used in the iPhone 3GS, which did receive iOS 6.</p><p>The practical consequence: a device discontinued in September 2010 lost active software support in September 2012. Less than 24 months of post-sale support for a device sold new at $299.</p>"},{"month":"Feb","day":"21","year":"2014","tag":"Legacy","title":"iOS 5.1.1 (9B206) — the goto fail patch.","preview":"Apple patches a critical SSL vulnerability in a surprise legacy update. The absolute final code delivery to this hardware.","body":"<p>In an unexpected move, Apple pushed a revised build of iOS 5.1.1 — build 9B206 — specifically to patch a severe SSL/TLS certificate verification vulnerability known as \"goto fail.\" The bug allowed man-in-the-middle attacks against secure connections on affected devices.</p><p>This was the absolute final software modification Apple ever delivered to 3rd generation iPod touch hardware. No subsequent updates of any kind were issued. The device''s software history ends here — a security patch, not a feature, as the last chapter.</p>"}]}'::jsonb),
  ('apple', 'apple-ipod-touch-3g', 3, 'delta', '{"heading":"What changed.<br>2nd &#8594; 3rd generation.","intro":"The exterior did not change by a single millimetre. The interior changed almost completely. Apple ported the iPhone 3GS''s processor platform into the iPod touch chassis — delivering the first iPod touch capable of console-quality mobile gaming.","footnote":"Specs: iPod touch 2nd gen (A1288) · Sep 9, 2008 · $229 / $299 / $399 &nbsp;/&nbsp; iPod touch 3rd gen (A1318) · Sep 9, 2009 · $299 (32 GB) / $399 (64 GB)","prev":{"name":"iPod touch (2nd gen)","year":"September 2008"},"current":{"name":"iPod touch (3rd gen)","year":"September 2009"},"hardware":[{"label":"Processor","old":"Samsung ARM11 · 400 MHz","new":"Samsung <strong>ARMv7 Cortex-A8</strong> · 600 MHz — 50% faster","chip":"better","chip_text":"+50%"},{"label":"RAM","old":"128 MB DRAM","new":"<strong>256 MB DRAM</strong> — doubled","chip":"better","chip_text":"×2"},{"label":"GPU","old":"PowerVR MBX Lite","new":"<strong>PowerVR SGX535</strong> — OpenGL ES 2.0","chip":"better","chip_text":"New"},{"label":"Storage tiers","old":"8 · 16 · 32 GB","new":"<strong>32 · 64 GB</strong> only — no entry tier","chip":"changed","chip_text":"No 8 GB"},{"label":"Included earbuds","old":"Standard earbuds only","new":"<strong>Earbuds with remote + mic</strong> — first iPod touch","chip":"better","chip_text":"New"},{"label":"Back design","old":"Curved polished stainless steel","new":"Curved polished stainless steel — <strong>unchanged</strong>","chip":"same","chip_text":"Same"},{"label":"Weight","old":"115 g (4.05 oz)","new":"<strong>115 g</strong> (4.05 oz) — unchanged","chip":"same","chip_text":"Same"}],"software":[{"label":"Launch OS","old":"iPhone OS 2.1.1","new":"<strong>iPhone OS 3.1.1</strong> — newer base","chip":"better","chip_text":"Newer"},{"label":"Voice Control","old":"Not present.","new":"<strong>Voice Control</strong> — first iPod touch","no_old":true,"chip":"better","chip_text":"New"},{"label":"OpenGL ES 2.0","old":"Not supported. ES 1.1 only.","new":"<strong>OpenGL ES 2.0</strong> — shader support","no_old":true,"chip":"better","chip_text":"New"},{"label":"Maximum OS","old":"iOS 4.2.1","new":"<strong>iOS 5.1.1</strong> — one major generation further","chip":"better","chip_text":"Further"},{"label":"Game Center","old":"Not supported.","new":"<strong>Game Center</strong> — iOS 4.1+","no_old":true,"chip":"better","chip_text":"New"}]}'::jsonb),
  ('apple', 'apple-ipod-touch-3g', 4, 'config', '{"heading":"Two SKUs. No entry tier.","visual":"config","chart_title":"Storage configurations and launch pricing","intro":["The iPod touch 3rd generation was sold in two storage configurations only — <strong>32 GB and 64 GB</strong>. The 8 GB tier was dropped entirely, and the 16 GB tier was never offered. This was the first iPod touch to ship without a sub-$300 option.","The 64 GB model was the highest-capacity iPod touch Apple had ever shipped at the time, and would remain so until the 4th generation. Both models launched September 9, 2009 and were discontinued simultaneously on September 1, 2010 — a lifespan of exactly one year."],"footer":"All configurations: 600 MHz ARMv7 · 256 MB RAM · 3.5&Prime; IPS 480&times;320 · 30h audio · 115 g · Curved stainless steel · Black front bezel","items":[{"capacity":32,"unit":"GB","model":"MC008LL/A","price":"$299","dates":"Sep 2009 &ndash; Sep 2010","colors":[{"name":"Silver","hex":"#d4d4d8","ring":true}]},{"capacity":64,"unit":"GB","model":"MC011LL/A","price":"$399","dates":"Sep 2009 &ndash; Sep 2010","colors":[{"name":"Silver","hex":"#d4d4d8","ring":true}]}]}'::jsonb),
  ('apple', 'apple-ipod-touch-3g', 5, 'prose-rail', '{"eyebrow":"Cultural impact","icon":"gamepad-2","anchor":"gaming-section","heading":"The game machine.","body":[{"text":"No previous iPod touch had been sold primarily as a gaming device. The third generation changed that. Apple''s September 2009 event benchmarked the 3G against the Nintendo DS and the Sony PlayStation Portable — two devices that had defined portable gaming for nearly a decade — and claimed superiority on available software alone. The App Store already carried over 21,000 game titles."},{"text":"The hardware justified the pitch. The PowerVR SGX535 GPU supported OpenGL ES 2.0, enabling per-pixel lighting, bloom effects, and shader-driven rendering that the previous generation''s MBX Lite could not produce. Titles like <strong>Modern Combat</strong>, <strong>Infinity Blade</strong>, and <strong>Real Racing</strong> were built specifically for the 3G''s graphics ceiling."},{"text":"Doubled RAM changed the experience more subtly but more fundamentally. The 2nd generation''s 128 MB ceiling forced developers to aggressively compress assets and limit scene complexity. At 256 MB, the 3G could hold larger textures, run more complex physics, and switch between apps without the hard reloads that characterized its predecessor."},{"text":"The 3G''s commercial timing was fortunate. iOS gaming was entering its first serious growth phase, and the 3G arrived exactly as the market needed a non-phone device capable of running its most demanding titles. It seeded a generation of players who had no console — only a pocket-sized slab with a touch screen and an App Store account."}]}'::jsonb),
  ('apple', 'apple-ipod-touch-3g', 6, 'prose-rail', '{"eyebrow":"Industrial design","icon":"palette","anchor":"design-section","heading":"The invisible upgrade.","body":[{"text":"The 3rd generation iPod touch was externally indistinguishable from the 2nd generation. Same curved polished stainless steel back. Same flush 3.5 mm headphone jack. Same 110 × 61.8 × 8.5 mm footprint. Same weight. The home button, the dock connector, the volume buttons — unchanged. A user holding both devices simultaneously could not tell them apart by touch."},{"text":"This was a deliberate choice. Apple had invested in the 2G chassis — the curved stainless rear, the form that sat better in the hand than the flat aluminum of the original — and saw no reason to retire it after a single cycle. The industrial design story for the 3G was not the shell but the interior: what Apple had managed to fit inside an unchanged body."},{"text":"The one visible difference was in the retail box. The 3G shipped with the new earbuds including a three-button remote and microphone — the same accessory included with the iPhone 3GS. The EarPods era was still two years away, but these earbuds represented a meaningful upgrade over the plain earbuds in previous iPod touch boxes."},{"text":"For case manufacturers, the unchanged design was a gift and, briefly, a source of embarrassment. Cases designed for the 2G fit the 3G perfectly — but those same manufacturers had already tooled up for a 3G with a rear camera cutout, based on leaked designs that never materialised. For a few weeks in September 2009, camera cases for a camera-less device sat on the shelves at Best Buy."}]}'::jsonb),
  ('apple', 'apple-ipod-touch-3g', 7, 'lifecycle-lane', '{"heading":"Three major versions. Nearly three years.<br>One cliff.","title":"Software lifecycle: iPhone OS 3.1.1 through iOS 5.1.1","paragraphs":["The iPod touch 3rd generation launched on iPhone OS 3.1.1 and received full software support for nearly three years — a notably longer run than the 2nd generation''s two-year window. The Cortex-A8 architecture gave it headroom the ARM11-based 2G lacked, enabling it to run iOS 4 without the feature exclusions that hobbled its predecessor.","Unlike the 2G, which received iOS 4 in a crippled form — no multitasking, no wallpapers, no Bluetooth keyboard — the 3G received iOS 4 fully. Multitasking, Game Center, FaceTime prep, AirPlay: all present. The 3G was the minimum viable platform for iOS 4''s marquee features.","The end came with iOS 6 in September 2012. The 3G''s ARMv7 architecture technically met iOS 6''s baseline requirements, making the cutoff a product decision rather than a hardware necessity. Apple''s stated reason was optimisation; the practical effect was that a device sold until September 2010 lost software support less than two years after discontinuation."],"segments":[{"ver":"3.1.1","date":"Sep 2009","type":"full","badge":"Launch","badge_type":"ship"},{"ver":"4.0","date":"Jun 2010","type":"full"},{"ver":"5.0","date":"Oct 2011","type":"full"},{"ver":"5.1.1","date":"May 2012","type":"full","badge":"Final","badge_type":"final"},{"ver":"6.0","date":"Sep 2012","type":"dropped","badge":"Dropped","badge_type":"dropped"}],"notes":[{"status":"full","label":"iOS 4.0","text":"Full iOS 4 support — multitasking, wallpapers, Game Center. No feature exclusions unlike 2nd gen."},{"status":"final","label":"iOS 5.1.1","text":"Final official update. May 7, 2012. ARMv7 architecture met iOS 6 requirements; Apple still cut it."},{"status":"dropped","label":"iOS 6","text":"Device dropped from compatibility list. ARMv7 requirement met but Apple chose not to support."}]}'::jsonb),
  ('apple', 'apple-ipod-touch-3g', 8, 'prose-rail', '{"eyebrow":"Controversies","icon":"scale","anchor":"controversies-section","heading":"Ghost in the machine.","body":[{"icon":"camera-off","subtitle":"The missing camera","text":"Before the September 9 launch, leaked images showed a 3rd generation iPod touch prototype with a rear camera centerd on the back panel. Case manufacturers — including products stocked at Best Buy retail locations — built and shipped camera-cutout cases based on these leaks. When the device launched with no camera and an unchanged back panel, the disconnect was immediate. A subsequent iFixit teardown of the 3rd generation confirmed the story: the camera socket was physically present inside the device. The hardware had been designed to accommodate a camera. Something — widely attributed to manufacturing yield problems with the camera module — removed it from the final product. Apple never commented. Prototypes with functioning cameras later surfaced on eBay in 2010, corroborating the teardown findings."},{"icon":"tag","subtitle":"The 8GB labeling confusion","text":"At launch, Apple continued selling the 2nd generation iPod touch in 8 GB form alongside the new 3G. Resellers — not Apple — began labeling these as \"3rd generation,\" creating persistent confusion in secondary markets that lasted years. The 8 GB model was hardware-identical to the original 2nd gen MC revision: same ARM11 processor, same 128 MB RAM, same GPU. It was not a 3rd generation device by any internal measure. Apple never publicly addressed the mislabeling."},{"icon":"ban","subtitle":"The iOS 6 cutoff","text":"The 3G''s ARMv7 Cortex-A8 architecture nominally met the hardware requirements Apple later cited for iOS 6 compatibility. The decision to exclude it was not driven by an absolute hardware barrier — the iPhone 3GS, using the same SoC family, received iOS 6. The practical effect was that owners of a device discontinued in September 2010 lost software support in September 2012: a window of less than 24 months post-sale."}]}'::jsonb),
  ('apple', 'apple-ipod-touch-3g', 9, 'spec', '{"heading":"The complete sheet.","device":"iPod touch (3rd generation) · A1318","cards":[{"title":"General Device Info","icon":"globe","rows":[["Model number","A1318"],["Codename","iPod3,1 / N18"],["Generation","3rd"],["Released","September 9, 2009"]]},{"title":"Processor & memory","icon":"cpu","rows":[["CPU","Samsung S5L8922 · ARMv7 Cortex-A8"],["Clock speed","600 MHz"],["RAM","256 MB DRAM"],["GPU","PowerVR SGX535"],["Architecture","ARMv7 (32-bit)"]]},{"title":"Display","icon":"monitor","rows":[["Size","3.5 inches"],["Type","TFT LCD, backlit"],["Resolution","480 × 320 px"],["Density","163 ppi"],["Input","Capacitive multi-touch"]]},{"title":"Storage & capacity","icon":"hard-drive","rows":[["Launch tiers","32 / 64 GB"],["Type","NAND flash"],["Expandable","No"]]},{"title":"Connectivity","icon":"radio","rows":[["Wi-Fi","802.11 b/g"],["Bluetooth","2.1 + EDR"],["Cellular","None"],["GPS","None"],["Port","30-pin dock connector"],["Audio jack","3.5 mm (flush)"]]},{"title":"Audio & sensors","icon":"music","rows":[["Speaker","Built-in mono"],["Microphone","None (via earbuds remote)"],["Accelerometer","Yes (3-axis)"],["Ambient light","Yes"],["Formats","AAC, MP3, ALAC, AIFF, WAV"]]},{"title":"Physical","icon":"smartphone","rows":[["Height","110.0 mm"],["Width","61.8 mm"],["Depth","8.5 mm"],["Weight","115 g"],["Casing","Polished stainless steel"],["Front bezel","Black"]]},{"title":"Power","icon":"zap","rows":[["Battery","Built-in Li-ion rechargeable"],["Audio","Up to 30 hours"],["Video","Up to 6 hours"],["Charging","USB / dock connector"]]},{"title":"Software","icon":"layers","rows":[["Shipped with","iPhone OS 3.1.1"],["Final version","iOS 5.1.1"],["Major versions","3.x · 4.x · 5.x"],["Support window","Sep 2009 – May 2012"]]}]}'::jsonb)
) as v(wiki_id, page_id, position, component, data)
where not exists (select 1 from public.sections s
  where s.wiki_id = 'apple' and s.page_id = 'apple-ipod-touch-3g');

