insert into public.sections (wiki_id, page_id, position, component, data)
select * from (values
  ('apple', 'apple-ipod-touch-4g', 0, 'hero', '{"eyebrow":"iPod touch · 4th Generation · 2010 – 2013","title":"iPod touch","subtitle":"(4th generation)","subtitle_meta":"Model A1367","desc":"The fourth generation iPod touch was the device that finally made people believe the iPod touch mattered. A <strong>Retina display</strong> sharp enough to embarrass every screen around it. <strong>Cameras</strong> — both front and rear — for the first time in the line''s history. FaceTime without a phone plan. It was the iPhone 4''s closest cousin, and for millions of people who couldn''t afford or didn''t want a carrier contract, it was the better deal.","stats":[{"num":"Sep 2010","label":"Released"},{"num":"326 ppi","label":"Retina display"},{"num":"256 MB","label":"RAM"},{"num":"3 years","label":"Sales lifespan"}],"search":false,"search_placeholder":null,"spotlight":null,"feature":null}'::jsonb),
  ('apple', 'apple-ipod-touch-4g', 1, 'overview', '{"tone":"a","heading":"The iPhone 4, without the phone.","paragraphs":["The fourth-generation iPod touch was announced September 1, 2010 at Apple''s annual iPod event and released twelve days later. It arrived in the same season as the iPhone 4, and Apple made no secret of the relationship — the two devices shared the same Apple A4 processor, the same Retina display at 960×640 and 326 PPI, the same FaceTime capability, and a form factor that was, at 7.2 mm, actually thinner than the iPhone 4.","The headline features were the cameras. For the first time in the iPod touch''s history, the device had both a front-facing FaceTime camera and a rear-facing iSight camera capable of 720p video. FaceTime over Wi-Fi — Apple''s video calling system, introduced months earlier with the iPhone 4 — was now available to anyone, without a phone plan or a carrier contract. For schools, for children, for anyone who wanted a connected device without a monthly bill, this was the entry point.","The Retina display was the other watershed moment. The jump from the 3G''s 163 PPI to 326 PPI was not incremental — it was a step change visible to the naked eye from the first glance. Text sharpened. Photos clarified. Games rendered at a pixel density that, in 2010, had no competition.","The hardware story had complications. The A4 chip ran at 800 MHz, faster than the 3G''s 600 MHz, but the RAM stayed at 256 MB — half the 512 MB Apple put in the iPhone 4. The rear camera, despite producing 720p video, captured stills at only 0.7 megapixels — a figure that drew immediate criticism given the iPhone 4''s 5 MP camera sat in the same device family.","The 4th generation had the longest sales lifespan of any iPod touch to that point: nearly three years, across multiple price drops and a mid-cycle expansion of the SKU lineup. It was discontinued in two phases — the 8 and 64 GB models in October 2012, the 16 and 32 GB models in May 2013 — and its final software update, iOS 6.1.6, arrived in February 2014."],"infobox":{"label":null,"title":"iPod touch","sublabel":null,"rows":[["Model","A1367"],["Developer","Apple Inc."],["Generation","4th of 7"],["Announced","September 1, 2010"],["Released","September 12, 2010"],["Discontinued","May 30, 2013 (final SKUs)"],["Predecessor","iPod touch (3rd gen)"],["Successor","iPod touch (5th gen)"],["Event","iPod music event · Sep 1, 2010"],["OS at launch","iOS 4.1"],["Max OS","iOS 6.1.6"],["Processor","Apple A4 · ARM Cortex-A8 800 MHz"],["GPU","PowerVR SGX535"],["RAM","256 MB"],["Storage","8 · 16 · 32 · 64 GB"],["Display","3.5-inch Retina · 960×640 · 326 ppi"],["Cameras","0.7 MP rear · 0.3 MP front"],["Dimensions","111 × 58.9 × 7.2 mm"],["Weight","86.3 g (3.04 oz)"],["Colors","Black · White (from Oct 2011)"],["Battery","~40 hrs audio · 7 hrs video"],["Price","body_class: wiki-page wiki-apple 99 · $249 · $299 · $399"]],"badge":"Discontinued · May 2013"}}'::jsonb),
  ('apple', 'apple-ipod-touch-4g', 2, 'photo-rail', '{"photos":[{"src":"https://i.ebayimg.com/images/g/TVcAAOSwzhNkQfbA/s-l1200.jpg","alt":"iPod touch 4th generation","strong":"Front view.","caption":"The 3.5-inch Retina display — 326 ppi, the headline feature of the 4th generation."},{"src":"https://cdn.mos.cms.futurecdn.net/bd36c0c29e32dccbfcb23b20c91ade9e-784-80.jpg","alt":"iPod touch 4th generation","strong":"In hand.","caption":"At 7.2 mm and 86 g, the thinnest and lightest iPod touch to that point."},{"src":"https://www.idemigods.com/v/vspfiles/photos/4G_BCKCVRTCH_64GB-2.jpg?v-cache=1645793973","alt":"iPod touch 4th generation rear","strong":"Polished rear.","caption":"The aluminum back with the protruding rear camera — the first camera in the line."},{"src":"https://everymac.com/images/ipod_pictures/apple-ipod-touch-5g.jpg","alt":"iPod touch","strong":"Product shot.","caption":"Apple marketing image. ⚠ Filename suggests 5th gen — verify this shows the 4th gen before publishing."}]}'::jsonb),
  ('apple', 'apple-ipod-touch-4g', 3, 'timeline', '{"heading":"Three years. One screen that changed everything.","visual":"timeline","events":[{"month":"Sep","day":"1","year":"2010","tag":"Launch","title":"iPod touch 4G announced.","preview":"Retina display. Cameras. FaceTime. 26% thinner. The iPhone 4''s sibling without the phone.","body":"<p>Apple announced the 4th generation iPod touch at its annual music event on September 1, 2010. Phil Schiller led the presentation, positioning it as the device that brought the iPhone 4''s most significant features — the Retina display, FaceTime, dual cameras — to the iPod touch line without requiring a carrier contract.</p><p>The Retina display at 326 PPI was the headline. The cameras — front-facing FaceTime, rear-facing 720p video — were the second headline. The device was 26% thinner than the 3rd generation and 25% lighter. It launched September 12 in black at $229 (8 GB), $299 (32 GB), and $399 (64 GB).</p>"},{"month":"Sep","day":"12","year":"2010","tag":"Hardware","title":"iPod touch 4G goes on sale.","preview":"Available in stores. Black only. 8, 32, 64 GB. iOS 4.1 out of the box.","body":"<p>The 4th generation iPod touch went on sale September 12, 2010, shipping with iOS 4.1. The release coincided with the public launch of Game Center — Apple''s multiplayer gaming platform — which arrived in the same iOS update.</p><p>An iFixit teardown the same week confirmed the device''s 256 MB of RAM — half the 512 MB in the iPhone 4, and equal to the iPad. The finding drew immediate attention from developers and enthusiasts who noted the RAM gap would have long-term implications for software support.</p>"},{"month":"Oct","year":"2010","tag":"Hardware","title":"8 GB price drops to $199.","preview":"Entry-tier now $199. Mass-market positioning solidified.","body":"<p>Apple reduced the price of the 8 GB iPod touch from $229 to $199 in October 2010, establishing it as a direct competitor to entry-level portable gaming devices. The price cut positioned the iPod touch explicitly against the Nintendo DS ($149–$179) and Sony PSP ($169–$199) — devices Apple had been benchmarking against since the 3rd generation launch.</p>"},{"month":"Oct","day":"4","year":"2011","tag":"Hardware","title":"White model announced.","preview":"A second color — over a year after launch. Announced alongside iPhone 4S.","body":"<p>Apple announced the white iPod touch 4th generation at its \"Let''s Talk iPhone\" event on October 4, 2011 — the same event that introduced the iPhone 4S and, notably, was Steve Jobs''s last Apple product event before his death the following day. The white model went on sale October 12, 2011 alongside iOS 5.0.</p>"},{"month":"Oct","day":"12","year":"2011","tag":"Software","title":"iOS 5.0 — iCloud, iMessage, OTA updates.","preview":"The 4G gets iCloud, iMessage, Newsstand, and the first OTA software update.","body":"<p>iOS 5 brought iCloud backup, iMessage Wi-Fi messaging, Notification Center, Reminders, and over-the-air updates to the 4th generation iPod touch. It was the first iOS update that required no computer connection. The 4G''s 256 MB RAM showed its limitations under iOS 5 — Safari tabs reloaded more aggressively — but the core experience remained functional.</p>"},{"month":"Sep","day":"12","year":"2012","tag":"Hardware","title":"5th gen launches. 4G lineup restructured.","preview":"8 and 64 GB discontinued. 16 GB added at $199. 32 GB drops to $249.","body":"<p>Apple announced the 5th generation iPod touch on September 12, 2012 — the same day as the iPhone 5. Simultaneously, the 4th generation lineup was restructured: the 8 GB and 64 GB models were discontinued, a new 16 GB model was introduced at $199, and the 32 GB price dropped to $249.</p><p>The 4th generation continued as the budget option in Apple''s iPod touch lineup, sitting below the new 5th generation''s $229 starting price. Both continued to be sold in parallel.</p>"},{"month":"May","day":"29","year":"2013","tag":"Hardware","title":"iPod touch 4G discontinued.","preview":"Eleven days before iOS 7 is announced. Apple says nothing about the timing.","body":"<p>Apple discontinued the final 4th generation iPod touch models — the 16 GB and 32 GB — on May 29, 2013. The device had been on sale for nearly three years, across four storage tiers and two colors.</p><p>What Apple did not announce was that iOS 7 — which would explicitly exclude the 4th generation — would be revealed eleven days later at WWDC 2013. Customers who purchased new 4th generation hardware in the final days of its sale had no way to know they were buying a device that would be left behind by the current iOS within weeks.</p>"},{"month":"Jun","day":"10","year":"2013","tag":"Software","title":"iOS 7 announced — 4G not supported.","preview":"WWDC 2013. iOS 7 requires 512 MB RAM. The 4G has 256 MB. It is excluded.","body":"<p>iOS 7 was announced at WWDC on June 10, 2013 — eleven days after the 4th generation was discontinued. The compatibility list did not include the iPod touch 4th generation. Apple''s stated reasoning centerd on RAM requirements: iOS 7 needed more memory than the 4G''s 256 MB could provide.</p><p>The iPhone 4 — with the same A4 processor family but 512 MB of RAM — received iOS 7. The asymmetric treatment highlighted the deliberate RAM difference Apple had built into the 2010 A4 device lineup, a decision that had seemed like a cost measure at the time but functioned as a structural end-of-life mechanism.</p>"},{"month":"Nov","day":"14","year":"2013","tag":"Legacy","title":"iOS 6.1.5 — FaceTime fix.","preview":"Surprise update. FaceTime calls had been failing. Apple patches the discontinued device.","body":"<p>Apple issued iOS 6.1.5 for the iPod touch 4th generation on November 14, 2013, six months after the device''s discontinuation. The update addressed a bug causing FaceTime calls to fail — a particularly relevant fix for a device whose FaceTime capability had been a primary selling point.</p>"},{"month":"Feb","day":"21","year":"2014","tag":"Legacy","title":"iOS 6.1.6 — goto fail. The final update.","preview":"Critical SSL patch. The last code Apple ever delivered to this hardware.","body":"<p>iOS 6.1.6 was released February 21, 2014 — the same goto fail SSL security patch issued simultaneously for the iPhone 3GS. It addressed a severe certificate verification vulnerability that had been discovered in Apple''s TLS implementation.</p><p>This was the absolute final software update Apple delivered to the 4th generation iPod touch. The device''s software history ends here: a security patch, not a feature, as the last act. The hardware had been discontinued nine months prior. The final update arrived nearly 3.5 years after launch.</p>"}]}'::jsonb),
  ('apple', 'apple-ipod-touch-4g', 4, 'delta', '{"heading":"What changed.<br>3rd &#8594; 4th generation.","intro":"The third generation changed nothing on the outside. The fourth generation changed almost everything — the display, the cameras, the thickness, the weight. For the first time, the iPod touch looked and felt like a genuinely new product rather than an internal upgrade.","footnote":"Specs: iPod touch 3rd gen (A1318) · Sep 9, 2009 · $299 / $399 &nbsp;/&nbsp; iPod touch 4th gen (A1367) · Sep 12, 2010 · $229 / $299 / $399","prev":{"name":"iPod touch (3rd gen)","year":"September 2009"},"current":{"name":"iPod touch (4th gen)","year":"September 2010"},"hardware":[{"label":"Display","old":"480×320 · 163 ppi · TFT LCD","new":"<strong>960×640 · 326 ppi · Retina</strong> — 4× pixel count","chip":"feature","chip_text":"Retina"},{"label":"Processor","old":"Cortex-A8 600 MHz","new":"Apple A4 <strong>Cortex-A8 800 MHz</strong> — 33% faster","chip":"better","chip_text":"+33%"},{"label":"RAM","old":"256 MB DRAM","new":"<strong>256 MB DRAM</strong> — unchanged","chip":"same","chip_text":"Same"},{"label":"Rear camera","old":"No camera.","new":"<strong>0.7 MP · 720p video</strong> — first in iPod touch line","no_old":true,"chip":"better","chip_text":"New"},{"label":"Front camera","old":"No front camera.","new":"<strong>0.3 MP FaceTime camera</strong> — first in iPod touch line","no_old":true,"chip":"better","chip_text":"New"},{"label":"Gyroscope","old":"Accelerometer only.","new":"<strong>3-axis gyroscope</strong> + accelerometer","no_old":true,"chip":"better","chip_text":"New"},{"label":"Microphone","old":"Via earbuds remote only.","new":"<strong>Built-in microphone</strong>","no_old":true,"chip":"better","chip_text":"New"},{"label":"Wi-Fi","old":"802.11 b/g","new":"<strong>802.11 b/g/n</strong> — 802.11n added","chip":"better","chip_text":"802.11n"},{"label":"Thickness","old":"8.5 mm","new":"<strong>7.2 mm</strong> — 15% thinner","chip":"better","chip_text":"-15%"},{"label":"Weight","old":"115 g (4.05 oz)","new":"<strong>86.3 g</strong> (3.04 oz) — 25% lighter","chip":"better","chip_text":"-25%"}],"software":[{"label":"Launch OS","old":"iPhone OS 3.1.1","new":"<strong>iOS 4.1</strong>","chip":"better","chip_text":"Newer"},{"label":"FaceTime","old":"Not supported.","new":"<strong>FaceTime over Wi-Fi</strong> — first iPod touch","no_old":true,"chip":"better","chip_text":"New"},{"label":"Maximum OS","old":"iOS 5.1.1","new":"<strong>iOS 6.1.6</strong> — one major generation further","chip":"better","chip_text":"Further"}]}'::jsonb),
  ('apple', 'apple-ipod-touch-4g', 5, 'config', '{"heading":"Three years. Four tiers. Two phases.","visual":"config","chart_title":"Storage configurations and launch pricing","intro":["The iPod touch 4th generation had the most complex SKU history of any iPod touch to that point. It launched in three capacities in September 2010, received a price reduction on the entry tier in October 2010, added a white color option in October 2011, added a 16 GB mid-tier in September 2012, and discontinued the 8 GB and 64 GB in the same month.","The 16 and 32 GB models continued until May 29, 2013 — the longest any 4th gen SKU stayed on sale, at nearly three years. The final lineup before discontinuation was 16 GB at $199 and 32 GB at $249."],"footer":"All configurations: 800 MHz Apple A4 · 256 MB RAM · 3.5&Prime; Retina 960&times;640 · 326 ppi · 0.7 MP + 0.3 MP cameras · 7.2 mm · 86.3 g","items":[{"capacity":8,"unit":"GB","model":"MC540LL/A","price":"$229 → $199","dates":"Sep 2010 &ndash; Oct 2012","colors":[{"name":"Black","hex":"#1d1d1f"},{"name":"White","hex":"#f5f5f7","ring":true}]},{"capacity":16,"unit":"GB","model":"ME178LL/A","price":"$199","dates":"Sep 2012 &ndash; May 2013","colors":[{"name":"Black","hex":"#1d1d1f"},{"name":"White","hex":"#f5f5f7","ring":true}]},{"capacity":32,"unit":"GB","model":"MC544LL/A","price":"$299 → $249","dates":"Sep 2010 &ndash; May 2013","colors":[{"name":"Black","hex":"#1d1d1f"},{"name":"White","hex":"#f5f5f7","ring":true}]},{"capacity":64,"unit":"GB","model":"MC547LL/A","price":"$399","dates":"Sep 2010 &ndash; Oct 2012","colors":[{"name":"Black","hex":"#1d1d1f"},{"name":"White","hex":"#f5f5f7","ring":true}]}]}'::jsonb),
  ('apple', 'apple-ipod-touch-4g', 6, 'prose-rail', '{"eyebrow":"Cultural impact","icon":"gamepad-2","anchor":"gaming-section","heading":"FaceTime without a phone.","body":[{"text":"When Apple introduced FaceTime with the iPhone 4 in June 2010, it required a phone. Specifically, an iPhone 4, on AT&T, in the United States, calling another iPhone 4. The feature was genuinely remarkable — and practically limited to a narrow audience."},{"text":"The 4th generation iPod touch changed the audience. FaceTime over Wi-Fi, on a device with no carrier requirement, no monthly bill, and a price starting at $229, brought video calling to students, to children, to anyone with a Wi-Fi connection. The iPod touch became the first mass-market video communication device that wasn''t a laptop."},{"text":"For families separated by geography, for students away at school, for children too young for a smartphone, the 4G iPod touch became the de facto FaceTime terminal for the first few years of video calling''s mainstream adoption. Apple TV commercials throughout 2010 and 2011 — some of the most emotionally direct advertising Apple ever made — showed FaceTime conversations between grandparents and grandchildren, between soldiers and families. Nearly all of those ads used the iPod touch."},{"text":"The gyroscope added another dimension to gaming that the 3G''s accelerometer-only setup had lacked. Combined with the Retina display''s pixel density — which made games look definitively better than any competing portable device — the 4G became the platform of choice for the most graphically ambitious App Store titles of 2011 and 2012. <strong>Infinity Blade</strong>, <strong>Real Racing 2</strong>, and <strong>Dead Space</strong> were designed around its capabilities."}],"rail":{"title":"Archive","photos":[{"src":"https://cdn.ecoustics.com/db0/wblob/17BA35E873D594/C1/CC86/U9IotdWynY6yS12wVnLQGZNntnEUmXJAFAiKFGF-MxE/648988.jpg","alt":"iPod touch 4th generation FaceTime","strong":"FaceTime for everyone.","caption":"Video calling over Wi-Fi, no carrier contract required — the 4th gen brought it to the masses."}]}}'::jsonb),
  ('apple', 'apple-ipod-touch-4g', 7, 'prose-rail', '{"eyebrow":"Industrial design","icon":"palette","anchor":"design-section","heading":"Thinner than the phone it resembled.","body":[{"text":"The fourth generation iPod touch was 7.2 mm thin — 15% thinner than the 3rd generation''s 8.5 mm, and actually slimmer than the iPhone 4 it visually referenced. At 86.3 grams, it weighed 25% less than its predecessor. Apple achieved this by moving away from the stainless steel-backed design of the 2nd and 3rd generations toward a polished aluminum rear with chamfered edges."},{"text":"The front face was entirely new: a Retina display with oleophobic coating, the same fingerprint-resistant treatment used on the iPhone 4. The volume buttons moved to the left edge. The headphone jack remained flush on the bottom — one of the iPod touch''s distinguishing design elements since the second generation."},{"text":"The device initially launched in black only. The white model followed in October 2011, announced at the same event as the iPhone 4S. White iPod touch models had been rare — the original iPod touch came in silver, and no white was offered until the 4th generation. Apple offered the 4G in both colors through the end of its sales lifecycle."},{"text":"The slimming came with a cost that went unannounced: the rear camera protrudes from the back panel, creating a slight bump. On a device this thin, the camera module''s depth was difficult to conceal. Apple chose performance over flush aesthetics — a tradeoff that would appear on every iPhone from the 6 onward and become an accepted convention of modern smartphone design."}],"rail":{"title":"Archive","photos":[{"src":"https://i5.walmartimages.com/asr/652b28dd-e1ee-4161-b9d0-8bb4bc0a8e78.bf330e5ca0c05730b446eb0e5c9f3dcb.jpeg?odnHeight=768&odnWidth=768&odnBg=FFFFFF","alt":"iPod touch 4th generation design","strong":"7.2 mm profile.","caption":"The polished aluminum back and chamfered edges — 15% thinner than the 3rd generation."},{"src":"https://www.bhphotovideo.com/images/fb/Apple_MD057LL_A_8GB_iPod_touch_White_825484.jpg","alt":"iPod touch 4th generation white","strong":"White model.","caption":"Introduced October 2011, over a year after the black launch — the first white iPod touch."}]}}'::jsonb),
  ('apple', 'apple-ipod-touch-4g', 8, 'lifecycle-lane', '{"heading":"Three major versions. One sharp cliff.","title":"Software lifecycle: iOS 4.1 through iOS 6.1.6","paragraphs":["The 4th generation iPod touch launched on iOS 4.1 and received full support through iOS 5.1.1, and partial support in iOS 6 — three major iOS versions total, the longest software run of any iPod touch up to that point. It received every feature its hardware could support: iCloud, iMessage, Game Center, Siri (dictation only, not the full assistant), Maps, FaceTime improvements.","The iOS 7 exclusion was the defining controversy of the device''s lifecycle. The 4G shared its Apple A4 processor architecture with the iPhone 4 — which received iOS 7. The difference was RAM: 256 MB on the iPod touch, 512 MB on the iPhone 4. Apple determined that iOS 7 was not viable on 256 MB, a judgment validated by independent testing showing the iPhone 4 itself ran iOS 7 poorly.","The timing was the problem. The 16 GB iPod touch 4th generation was sold as new hardware — at $199 — until May 29, 2013. Apple announced iOS 7 at WWDC on June 10, 2013: eleven days later. A customer who bought the device the day before discontinuation could not run the current iOS within two weeks of purchase. Apple offered no acknowledgment of the timing, no transition assistance, and no official comment."],"segments":[{"ver":"4.1","date":"Sep 2010","type":"full","badge":"Launch","badge_type":"ship"},{"ver":"5.0","date":"Oct 2011","type":"full"},{"ver":"6.0","date":"Sep 2012","type":"partial"},{"ver":"7.0","date":"Sep 2013","type":"dropped","badge":"Dropped","badge_type":"dropped"},{"ver":"6.1.6","date":"Feb 2014","type":"security","badge":"Security","badge_type":"security"}],"notes":[{"status":"partial","label":"iOS 6.0","text":"Partial iOS 6 support — Maps, Passbook, Siri dictation (not full assistant). Last major version."},{"status":"dropped","label":"iOS 7","text":"Excluded — 256 MB RAM vs required 512 MB. iPhone 4 with same A4 SoC received iOS 7."},{"status":"security","label":"iOS 6.1.6","text":"Post-EOL security patch — the goto fail SSL fix, Feb 21 2014. Final Apple software delivery to this hardware."}]}'::jsonb),
  ('apple', 'apple-ipod-touch-4g', 9, 'prose-rail', '{"eyebrow":"Controversies","icon":"scale","anchor":"controversies-section","heading":"The compromises behind the headlines.","body":[{"icon":"camera","subtitle":"The 0.7 megapixel rear camera","text":"The 4th generation iPod touch launched with a rear camera capable of 720p video — but still images were captured at 0.7 megapixels. The iPhone 4, announced three months earlier and sharing the same A4 processor family, had a 5-megapixel rear camera. Apple''s decision to fit a substantially inferior still camera into the iPod touch was widely criticized. The gap was not subtle: the iPhone 4''s camera was seven times higher resolution. Reviewers at the time speculated that Apple deliberately limited the iPod touch camera to protect iPhone margins and maintain a clear product hierarchy. Apple did not comment on the specification decision."},{"icon":"ban","subtitle":"The iOS 7 timing problem","text":"Apple discontinued the final 16 GB and 32 GB models of the 4th generation iPod touch on May 29, 2013. WWDC — where Apple announced iOS 7 — began eleven days later, on June 10. A customer who purchased the device new on May 28, 2013 would find, within two weeks, that the current iOS was incompatible with their new purchase. Apple offered no warning in the retail channel, no acknowledgment after the announcement, and no transition path. The company''s position that iOS 7 required more RAM than the device carried was technically defensible — the iPhone 4, with 512 MB, already ran iOS 7 poorly — but the timing made it indefensible to customers."},{"icon":"users","subtitle":"256 MB RAM — a ceiling the iPhone 4 didn''t have","text":"All three A4-based devices released in 2010 — the iPad, the iPod touch 4th generation, and the iPhone 4 — used the same Apple A4 processor. Apple gave the iPhone 4 512 MB of RAM. It gave the iPad and iPod touch 256 MB. The RAM differential had no immediate consequence in 2010, when iOS 4 ran adequately on 256 MB. Over time, as iOS updates consumed more memory, the gap widened. Safari tabs reloaded more aggressively, multitasking was more constrained, and the ultimate consequence was iOS 7 exclusion — an exclusion the iPhone 4, with its doubled RAM, avoided. The RAM decision looked like a cost-saving measure at launch; it looked like planned obsolescence by 2013."}],"rail":{"title":"Press archive","photos":[{"src":"https://www.cnet.com/a/img/resize/fb1891107ef4ba786a118c8bf2c6993a7ad26002/hub/2010/09/07/6b906e2a-6797-11e3-846b-14feb5ca9861/34167385_DT1.jpg?auto=webp&width=1200","alt":"iPod touch 4th generation camera","strong":"The 0.7 MP camera.","caption":"720p video but only 0.7 MP stills — a fraction of the iPhone 4’s 5 MP sensor."},{"src":"https://i.ebayimg.com/images/g/ij8AAOSwluVfzi1D/s-l400.jpg","alt":"iPod touch 4th generation rear camera","strong":"Single rear lens.","caption":"The protruding rear camera module — widely criticized for image quality at launch."},{"src":"https://preview.redd.it/black-or-white-ipod-touch-4-on-ios-7-1-2-v0-u9zwlnnuoyaf1.jpg?width=640&crop=smart&auto=webp&s=03e526604616bd590427a9d2c65055e90c3646e1","alt":"iPod touch 4th generation iOS 7","strong":"Unofficial iOS 7.","caption":"Enthusiasts later ported iOS 7 to the 4th gen — the version Apple said its 256 MB RAM couldn’t run."}]}}'::jsonb),
  ('apple', 'apple-ipod-touch-4g', 10, 'spec', '{"heading":"The complete sheet.","device":"iPod touch (4th generation) · A1367","cards":[{"title":"General Device Info","icon":"globe","rows":[["Model number","A1367"],["Codename","iPod4,1 / N81AP"],["Generation","4th"],["Announced","September 1, 2010"],["Released","September 12, 2010"],["Discontinued","May 30, 2013 (final SKUs)"]]},{"title":"Processor & memory","icon":"cpu","rows":[["CPU","Apple A4 (Samsung-Intrinsity)"],["Architecture","ARM Cortex-A8 · 32-bit"],["Clock speed","800 MHz"],["RAM","256 MB DRAM"],["GPU","PowerVR SGX535"]]},{"title":"Display","icon":"monitor","rows":[["Size","3.5 inches"],["Type","Retina IPS TFT LCD"],["Resolution","960 × 640 px"],["Density","326 ppi"],["Coating","Oleophobic fingerprint-resistant"]]},{"title":"Storage & capacity","icon":"hard-drive","rows":[["Launch tiers","8 / 32 / 64 GB"],["Added 2012","16 GB"],["Type","NAND flash"],["Expandable","No"]]},{"title":"Connectivity","icon":"radio","rows":[["Wi-Fi","802.11 b/g/n (2.4 GHz)"],["Bluetooth","2.1 + EDR"],["Cellular","None"],["GPS","None"],["Port","30-pin dock connector"],["Audio jack","3.5 mm (flush, bottom)"]]},{"title":"Camera & sensors","icon":"camera","rows":[["Rear camera","0.7 MP · f/2.4 · 720p video @ 30fps"],["Front camera","0.3 MP · FaceTime"],["Microphone","Built-in"],["Gyroscope","3-axis"],["Accelerometer","3-axis"],["Ambient light","Yes"]]},{"title":"Physical","icon":"smartphone","rows":[["Height","111.0 mm"],["Width","58.9 mm"],["Depth","7.2 mm"],["Weight","86.3 g"],["Rear casing","Polished aluminum"],["Colors","Black · White (Oct 2011+)"]]},{"title":"Power","icon":"zap","rows":[["Battery","Built-in Li-ion · 930 mAh"],["Audio","Up to 40 hours"],["Video","Up to 7 hours"],["Charging","USB / 30-pin dock connector"]]},{"title":"Software","icon":"layers","rows":[["Shipped with","iOS 4.1"],["Final version","iOS 6.1.6"],["Major versions","iOS 4 · 5 · 6"],["Support window","Sep 2010 – Feb 2014"]]}]}'::jsonb)
