select * from (values
  ('apple', 'apple-ipod-touch-6g', 0, 'hero', '{"eyebrow":"iPod touch · 6th Generation · 2015 – 2019","title":"iPod touch","subtitle":"(6th generation)","subtitle_meta":"Model A1574","desc":"After two and a half years of silence, the sixth generation iPod touch arrived with the <strong>Apple A8</strong> — the same chip as the iPhone 6 — an <strong>8 MP camera</strong>, <strong>1 GB of RAM</strong>, and a fresh palette topped by a new <strong>gold</strong> finish. The chassis was the thinnest Apple had ever shipped at 6.1 mm, externally near-identical to the 5G except for one thing: the pop-out Loop button was gone. It was the biggest internal leap in the line''s history wrapped in the most familiar body.","stats":[{"num":"6","label":"Launch colors"},{"num":"8 MP","label":"Rear camera"},{"num":"1 GB","label":"RAM"},{"num":"A8","label":"iPhone 6 chip"}],"search":false,"search_placeholder":null,"spotlight":null,"feature":null}'::jsonb),
  ('apple', 'apple-ipod-touch-6g', 1, 'overview', '{"tone":"a","heading":"The longest wait in the line — answered with the iPhone 6''s brain.","paragraphs":["The sixth generation iPod touch was released through the online Apple Store on July 15, 2015, alongside refreshed colors for the iPod nano and iPod shuffle. It was the first major update to the iPod touch in more than two and a half years — the 5th generation had launched in September 2012 — and Apple framed it as \"the best iPod touch yet.\" Manufactured by Foxconn, it carried the model number A1574 and the firmware identifier iPod7,1.","The headline was the processor. The 6G adopted the 64-bit Apple A8 — the same system-on-chip as the iPhone 6 and 6 Plus, the iPad mini 4, and later the Apple TV HD and HomePod — paired with the M8 motion coprocessor. RAM doubled from 512 MB to 1 GB of LPDDR3. The rear camera jumped from 5 MP to an 8 MP iSight with 1080p video, and Wi-Fi gained 802.11ac support. For the first time, the iPod touch shipped with the current iPhone''s processor rather than a hand-me-down a generation or two behind.","The color story expanded. The 6G launched in space gray, silver, gold, pink, blue, and (PRODUCT)RED. Gold was new to the line, mirroring the iPhone''s 2013 expansion. The space gray model had a black glass front; the other five had white fronts. The aluminum unibody was retained, but the pop-out Loop button — the signature flourish of the 5G — was quietly removed, leaving the only visible external difference between the two generations.","Storage was the most generous the line had ever offered: 16, 32, 64, and 128 GB, priced at body_class: wiki-page wiki-apple 99, $249, $299, and $399. The 128 GB tier was a first for any iPod touch. The device shipped with iOS 8.4, released two weeks earlier on June 30, 2015 alongside Apple Music and the Beats 1 radio station — making the 6G one of the launch vehicles for Apple''s streaming era.","There was a catch buried in the spec sheet. The A8 in the 6G was underclocked to 1.1 GHz, down from the 1.4 GHz of the iPhone 6, a concession to the smaller battery. The 16 GB base model also drew criticism for being cramped in the iOS 9 era. Still, the device aged remarkably well: it received iOS 9 through 12, was the oldest device to support iOS 10.3, and Apple has continued shipping iOS 12 security updates — the most recent, iOS 12.5.8, arrived in January 2026, more than a decade after launch. It was discontinued in two stages: the 16 and 64 GB tiers on July 27, 2017, and the 32 and 128 GB tiers on May 28, 2019, when the 7th generation arrived."],"infobox":{"label":null,"title":"iPod touch","sublabel":null,"rows":[["Model","A1574"],["Developer","Apple Inc."],["Manufacturer","Foxconn"],["Generation","6th of 7"],["Released","July 15, 2015"],["Discontinued","Jul 2017 / May 2019"],["Predecessor","iPod touch (5th gen)"],["Successor","iPod touch (7th gen)"],["Board","N102AP · iPod7,1"],["OS at launch","iOS 8.4"],["Max OS","iOS 12.5.8"],["Processor","Apple A8 · dual-core 1.1 GHz Typhoon"],["Coprocessor","Apple M8 motion"],["GPU","PowerVR GX6450 (quad-core)"],["RAM","1 GB LPDDR3"],["Storage","16 · 32 · 64 · 128 GB"],["Display","4-inch Retina · 1136×640 · 326 ppi"],["Rear camera","8 MP · LED flash · 1080p"],["Front camera","1.2 MP FaceTime HD · 720p"],["Connector","Lightning"],["Wi-Fi","802.11a/b/g/n/ac"],["Bluetooth","4.1"],["Dimensions","123.4 × 58.6 × 6.1 mm"],["Weight","88 g (3.1 oz)"],["Colors","Space Gray · Silver · Gold · Pink · Blue · (PRODUCT)RED"],["Battery","~40 hrs audio · 8 hrs video"],["Price","body_class: wiki-page wiki-apple 99 · $249 · $299 · $399"]],"badge":"Discontinued · May 2019"}}'::jsonb),
  ('apple', 'apple-ipod-touch-6g', 2, 'timeline', '{"heading":"One chip jump. Four years of updates. A decade of life.","visual":"timeline","events":[{"month":"Jul","day":"15","year":"2015","tag":"Launch","title":"iPod touch 6G released.","preview":"Apple A8. 8 MP camera. 1 GB RAM. Gold joins the palette. The Loop is gone.","body":"<p>Apple released the 6th generation iPod touch through its online store on July 15, 2015 — the first major update to the line in more than two and a half years. It carried the 64-bit Apple A8 processor (the iPhone 6''s chip), the M8 motion coprocessor, 1 GB of RAM, an 8 MP iSight camera, and 802.11ac Wi-Fi.</p><p>It launched in space gray, silver, gold, pink, blue, and (PRODUCT)RED, in 16, 32, 64, and 128 GB tiers at $199, $249, $299, and $399. The aluminum unibody and 4-inch Retina display carried over from the 5G; the pop-out Loop button did not. Apple called it \"the best iPod touch yet.\"</p>"},{"month":"Jul","day":"15","year":"2015","tag":"Software","title":"Ships with iOS 8.4 and Apple Music.","preview":"One of the first devices to carry Apple Music and Beats 1 out of the box.","body":"<p>The 6G shipped with iOS 8.4, released two weeks earlier on June 30, 2015. That version introduced Apple Music and the Beats 1 global radio station, making the new iPod touch one of the launch vehicles for Apple''s streaming service. For a product line that began as a music player, it was a fitting pivot toward streaming.</p>"},{"month":"Sep","year":"2015","tag":"Software","title":"iOS 9 — full support.","preview":"Unlike the 32-bit 5G, the 64-bit 6G runs iOS 9 and beyond without compromise.","body":"<p>iOS 9 shipped in September 2015 and the 6th generation received it in full. Where the contemporary 5th generation (a 32-bit A5 device) was about to be cut off by iOS 10, the 6G''s 64-bit A8 meant it had years of headroom. The device handled iOS 9''s full feature set comfortably.</p>"},{"month":"Sep","year":"2016","tag":"Software","title":"iOS 10 — oldest supported device.","preview":"iOS 10 dropped all 32-bit hardware. The 6G was the oldest device to make the cut.","body":"<p>iOS 10 (September 2016) dropped every 32-bit device, including the 5th generation iPod touch and the iPhone 5/5c. The 6G sailed through. It was, in fact, the oldest device Apple supported on iOS 10.3 — a distinction that underlined how much longevity the 64-bit A8 had bought the line.</p>"},{"month":"Jul","day":"27","year":"2017","tag":"Hardware","title":"16 GB and 64 GB tiers discontinued.","preview":"Apple trims the lineup. 32 GB becomes the new floor; 128 GB the ceiling.","body":"<p>On July 27, 2017, Apple discontinued the 16 GB and 64 GB configurations of the 6th generation iPod touch, leaving 32 GB and 128 GB in the lineup. The move retired the cramped 16 GB base model and simplified the range to two tiers. The 6G continued on sale, unchanged, for nearly two more years.</p>"},{"month":"May","day":"28","year":"2019","tag":"Hardware","title":"6th generation discontinued.","preview":"The 7th generation arrives with an A10 chip. The 6G''s nearly four-year run ends.","body":"<p>Apple discontinued the remaining 32 GB and 128 GB 6th generation models on May 28, 2019, with the launch of the 7th generation iPod touch. The 7G moved to the A10 Fusion processor and 2 GB of RAM, and carried the line forward to iOS 15. The 6G had been on sale for nearly four years — one of the longest single-model runs in the line.</p>"},{"month":"Sep","year":"2019","tag":"Software","title":"iOS 13 — the cutoff.","preview":"The 6G cannot run iOS 13. Feature updates end; security patches continue.","body":"<p>iOS 13, released in September 2019, did not support the 6th generation iPod touch — only the new A10-based 7th generation moved forward. Feature updates for the 6G ended at iOS 12. But, as with the iPhone 5s and iPhone 6 of the same vintage, Apple kept the device alive with iOS 12 security updates rather than abandoning it outright.</p>"},{"month":"Jan","year":"2026","tag":"Legacy","title":"iOS 12.5.8 — a decade-plus of support.","preview":"A certificate keep-alive patch, over ten years after launch. Among the longest tails in iOS.","body":"<p>In late January 2026, Apple released iOS 12.5.8 for the iPhone 5s, iPhone 6, iPhone 6 Plus, several iPads, and the 6th generation iPod touch. The update extended system certificates to keep FaceTime, iMessage, and device activation working past 2027 — a ''keep-alive'' patch rather than a feature release.</p><p>More than a decade after it went on sale, the 6G was still receiving code from Apple. It remains one of the longest-supported iOS devices ever made — a quiet testament to how much future-proofing the 64-bit A8 delivered in 2015.</p>"}]}'::jsonb),
  ('apple', 'apple-ipod-touch-6g', 3, 'delta', '{"heading":"What changed.<br>5th &#8594; 6th generation.","intro":"The fifth-to-sixth transition was the inverse of the fourth-to-fifth one. Where the 5G had overhauled everything visible — screen, body, connector, colors — the 6G left the exterior almost untouched and poured the entire upgrade into the silicon. Same 4-inch screen, same Lightning, same aluminum unibody. But a new 64-bit A8 processor, double the RAM, a sharper camera, and faster Wi-Fi. The only thing you could see was what went missing: the Loop button.","footnote":"Specs: iPod touch 5th gen (A1421) · Oct 11, 2012 &nbsp;/&nbsp; iPod touch 6th gen (A1574) · Jul 15, 2015","prev":{"name":"iPod touch (5th gen)","year":"October 2012"},"current":{"name":"iPod touch (6th gen)","year":"July 2015"},"hardware":[{"label":"Processor","old":"A5 · dual-core 1 GHz · 32-bit","new":"<strong>A8 · dual-core 1.1 GHz · 64-bit</strong> — the iPhone 6 chip","chip":"better","chip_text":"64-bit"},{"label":"RAM","old":"512 MB","new":"<strong>1 GB LPDDR3</strong> — doubled","chip":"better","chip_text":"2×"},{"label":"GPU","old":"PowerVR SGX543MP2","new":"<strong>PowerVR GX6450</strong> — quad-core, Metal support","chip":"feature","chip_text":"Metal"},{"label":"Rear camera","old":"5 MP · f/2.4 · 1080p","new":"<strong>8 MP · LED flash · 1080p</strong>","chip":"better","chip_text":"8 MP"},{"label":"Wi-Fi","old":"802.11a/b/g/n","new":"<strong>802.11a/b/g/n/ac</strong> — adds ac","chip":"better","chip_text":"ac"},{"label":"Bluetooth version","old":"4.0","new":"<strong>4.1</strong>","chip":"better","chip_text":"4.1"},{"label":"Max storage","old":"64 GB","new":"<strong>128 GB</strong> — new top tier","chip":"better","chip_text":"128 GB"},{"label":"Loop button","old":"Pop-out loop attachment","new":"<strong>Removed</strong>","chip":"worse","chip_text":"Gone"},{"label":"Colors","old":"Slate / Silver / Pink / Yellow / Blue / RED","new":"<strong>Space Gray / Silver / Gold / Pink / Blue / RED</strong> — gold new, yellow dropped","chip":"better","chip_text":"+ Gold"}],"software":[{"label":"OS at launch","old":"iOS 6.0","new":"<strong>iOS 8.4</strong> — launched with Apple Music","chip":"better","chip_text":"iOS 8.4"},{"label":"Final OS","old":"iOS 9.3.5 (2016)","new":"<strong>iOS 12.5.8 (2026)</strong>","chip":"better","chip_text":"iOS 12"}]}'::jsonb),
  ('apple', 'apple-ipod-touch-6g', 4, 'config', '{"heading":"Six colors. Four tiers. The first 128 GB iPod touch.","visual":"config","chart_title":"Storage configurations and launch pricing","intro":["The sixth generation iPod touch launched with four capacities — 16, 32, 64, and 128 GB — all sharing identical hardware and all available in the full six-color palette. The 128 GB tier was the largest ever offered on an iPod touch, and the line''s first move past 64 GB.","Unlike the 5th generation, there was no stripped-down budget variant. Every 6G is an A1574 with the same A8 processor, 1 GB of RAM, 8 MP camera, and Lightning connector — the only differences between units are storage and color."],"footer":"A1574: Apple A8 · M8 coprocessor · 1 GB RAM · 4&Prime; Retina 1136&times;640 · 8 MP + 1.2 MP cameras · Lightning · 6.1 mm · 802.11ac Wi-Fi · BT 4.1","items":[{"capacity":16,"unit":"GB","model":"A1574 · MKH62LL/A","price":"$199","dates":"Jul 2015 &ndash; Jul 2017","colors":[{"name":"Space Gray","hex":"#4a4a4f"},{"name":"Silver","hex":"#d8d8dc","ring":true},{"name":"Gold","hex":"#e8d3a8"},{"name":"Pink","hex":"#f472b6"},{"name":"Blue","hex":"#60a5fa"},{"name":"(RED)","hex":"#e3001b"}]},{"capacity":32,"unit":"GB","model":"A1574 · MKHC2LL/A","price":"$249","dates":"Jul 2015 &ndash; May 2019","colors":[{"name":"Space Gray","hex":"#4a4a4f"},{"name":"Silver","hex":"#d8d8dc","ring":true},{"name":"Gold","hex":"#e8d3a8"},{"name":"Pink","hex":"#f472b6"},{"name":"Blue","hex":"#60a5fa"},{"name":"(RED)","hex":"#e3001b"}]},{"capacity":64,"unit":"GB","model":"A1574 · MKHE2LL/A","price":"$299","dates":"Jul 2015 &ndash; Jul 2017","colors":[{"name":"Space Gray","hex":"#4a4a4f"},{"name":"Silver","hex":"#d8d8dc","ring":true},{"name":"Gold","hex":"#e8d3a8"},{"name":"Pink","hex":"#f472b6"},{"name":"Blue","hex":"#60a5fa"},{"name":"(RED)","hex":"#e3001b"}]},{"capacity":128,"unit":"GB","model":"A1574 · MKWR2LL/A","price":"$399","dates":"Jul 2015 &ndash; May 2019","colors":[{"name":"Space Gray","hex":"#4a4a4f"},{"name":"Silver","hex":"#d8d8dc","ring":true},{"name":"Gold","hex":"#e8d3a8"},{"name":"Pink","hex":"#f472b6"},{"name":"Blue","hex":"#60a5fa"},{"name":"(RED)","hex":"#e3001b"}]}]}'::jsonb),
  ('apple', 'apple-ipod-touch-6g', 5, 'prose-rail', '{"eyebrow":"Cultural impact","icon":"gamepad-2","anchor":"gaming-section","heading":"The pocket console that outlived its console moment.","body":[{"text":"By 2015, the iPod touch''s role as a gaming device had quietly become its most durable. With the A8 — the same chip driving the iPhone 6 — the 6G could run essentially every iOS game of its era at full fidelity. For parents, it remained the obvious answer: a device that played the same App Store games as an iPhone, took 8 MP photos, ran FaceTime over Wi-Fi, and cost a fraction of a phone, with no contract and no cellular bill."},{"text":"Apple''s A8 brought Metal, its low-overhead graphics API, to the iPod touch for the first time. Games like <strong>Asphalt 8</strong>, <strong>Real Racing 3</strong>, <strong>Modern Combat 5</strong>, and the wave of Metal-optimized titles that followed ran smoothly on the 6G. The device''s 64-bit architecture meant it stayed compatible with new App Store releases far longer than the 32-bit 5G, which was cut off at iOS 9."},{"text":"The 6G also landed at the dawn of Apple Music. Shipping with iOS 8.4 — the release that introduced Apple Music and the Beats 1 global radio station on June 30, 2015 — the device was one of the first to carry Apple''s streaming service out of the box. For a product line born as a music player, it was a fitting late-career pivot: the iPod touch became a streaming client as much as a library on a chip."},{"text":"Its longevity became the real story. The 6G received five years of major iOS updates and, remarkably, continued getting security patches into 2026 — over a decade after launch. Few consumer devices of its era stayed alive that long, and for a generation of kids it was a first computer, a first camera, and a first music app, all in a body thinner than the phone it borrowed its brain from."}]}'::jsonb),
  ('apple', 'apple-ipod-touch-6g', 6, 'prose-rail', '{"eyebrow":"Industrial design","icon":"palette","anchor":"design-section","heading":"The thinnest Apple had ever made — minus one button.","body":[{"text":"At 6.1 mm thick, the sixth generation iPod touch was the thinnest device Apple had ever shipped — more than a millimetre slimmer than the iPhone 6 (6.9 mm), and identical in profile to the 5G it succeeded. The dimensions were unchanged from the previous generation: 123.4 mm tall, 58.6 mm wide, 88 g in weight. The aluminum unibody, anodised in color, carried straight over."},{"text":"The one visible change was a subtraction. The pop-out Loop button — the small spring-loaded nub on the lower-left of the 5G''s back that ejected an anchor for a color-matched wrist strap — was removed entirely. The 6G''s back was clean. It was the only external way to tell the two generations apart, and it marked the end of the most playful piece of industrial design in the line''s history."},{"text":"The color palette was refreshed to match Apple''s broader 2015 lineup. Slate became space gray; yellow was dropped; gold was added. The result was space gray, silver, gold, pink, blue, and (PRODUCT)RED. As before, the space gray model wore a black glass front while every other color had a white front, so the front face told you the finish at a glance."},{"text":"The 4-inch 1136×640 Retina display was carried over unchanged — same panel, same 326 ppi, same 16:9 ratio, same oleophobic coating. By 2015 it was beginning to look small next to the 4.7-inch iPhone 6, but it kept the iPod touch pocketable and, crucially, cheap. The screen was the one piece of the device Apple chose not to touch."}]}'::jsonb),
  ('apple', 'apple-ipod-touch-6g', 7, 'lifecycle-lane', '{"heading":"Five major versions. A decade of security patches.","title":"Software lifecycle: iOS 8.4 through iOS 12.5.8","paragraphs":["The sixth generation iPod touch shipped with iOS 8.4 and went on to receive five major versions — iOS 8, 9, 10, 11, and 12. Its 64-bit A8 processor and 1 GB of RAM let it sail past the cliff that killed the 5G: where the 32-bit 5th generation was excluded from iOS 10 in 2016, the 6G ran it comfortably and was in fact the oldest device Apple supported on iOS 10.3.","The end of feature updates came with iOS 13 in 2019, which the 6G could not run. Its successor, the 7th generation with an A10 chip, launched the same year and carried the line forward to iOS 15. But Apple did not abandon the 6G: like the iPhone 5s, iPhone 6, and several iPads of the same vintage, it continued to receive iOS 12 security updates years after losing feature support.","Those updates kept coming for an extraordinarily long time. iOS 12.5.8, released in late January 2026, extended system certificates to keep services like FaceTime, iMessage, and device activation working past 2027 — a \"keep-alive\" patch rather than a feature release. More than a decade after it went on sale, the 6th generation iPod touch was still receiving code from Apple, one of the longest support tails of any iOS device."],"segments":[{"ver":"8.4","date":"Jul 2015","type":"full","badge":"Launch","badge_type":"ship"},{"ver":"9.0","date":"Sep 2015","type":"full"},{"ver":"10.0","date":"Sep 2016","type":"full"},{"ver":"11.0","date":"Sep 2017","type":"full"},{"ver":"12.0","date":"Sep 2018","type":"full"},{"ver":"13.0","date":"Sep 2019","type":"dropped","badge":"Dropped","badge_type":"dropped"},{"ver":"12.5.8","date":"Jan 2026","type":"security","badge":"Security","badge_type":"security"}],"notes":[{"status":"full","label":"iOS 8–12","text":"Full support — five major versions. The A8 and 1 GB RAM kept it current far longer than the 5G."},{"status":"full","label":"iOS 10.3","text":"The 6G was the oldest device Apple supported on iOS 10.3 — a 64-bit-only release."},{"status":"dropped","label":"iOS 13","text":"Excluded — required hardware the 6G lacked. The A10-based 7th gen carried the line forward."},{"status":"security","label":"iOS 12.5.8","text":"Post-EOL security patch — a certificate keep-alive update, January 2026. Over a decade after launch."}]}'::jsonb),
  ('apple', 'apple-ipod-touch-6g', 8, 'prose-rail', '{"eyebrow":"Controversies","icon":"scale","anchor":"controversies-section","heading":"Three things people questioned.","body":[{"icon":"alert-circle","subtitle":"The A8 was underclocked","text":"The 6th generation iPod touch used the same Apple A8 system-on-chip as the iPhone 6, but Apple ran it at 1.1 GHz rather than the iPhone 6''s 1.4 GHz — and well below the iPad mini 4''s 1.5 GHz implementation of the same chip. Apple attributed the lower clock to the iPod touch''s smaller battery and thermal envelope. In practice the device was still fast for its class, but the spec line meant that the ''iPhone 6 chip'' marketing came with an asterisk: same silicon, slower in this body."},{"icon":"memory-card","subtitle":"16 GB in the iOS 9 era","text":"The entry 6G shipped with 16 GB of storage at $199 — the same base capacity the line had used for years, but increasingly tight by 2015. iOS 9 and its updates, plus a single modern game or a short stretch of 1080p video from the new 8 MP camera, could fill the device quickly. Apple discontinued the 16 GB tier first, in July 2017, leaving 32 GB as the new floor. The base model was serviceable, but it asked buyers to manage storage carefully from day one."},{"icon":"bell","subtitle":"No Touch ID, no loop, no Apple Pay","text":"The 6G arrived without Touch ID, the fingerprint sensor that had been on iPhones since the 2013 5s, and without the Apple Pay capability that depended on it. It also dropped the 5G''s pop-out Loop attachment. For a 2015 device priced from $199, the omissions were defensible cost decisions — but they underlined the iPod touch''s status as a device deliberately kept a tier below the iPhone, sharing the processor while quietly lacking the features that defined the contemporary phone."}]}'::jsonb),
  ('apple', 'apple-ipod-touch-6g', 9, 'spec', '{"heading":"The complete sheet.","device":"iPod touch (6th generation) · A1574","cards":[{"title":"General Device Info","icon":"globe","rows":[["Model number","A1574"],["Board","N102AP"],["Firmware ID","iPod7,1"],["Generation","6th of 7"],["Manufacturer","Foxconn"],["Released","July 15, 2015"],["Discontinued","Jul 2017 (16/64 GB) · May 2019 (32/128 GB)"]]},{"title":"Processor & memory","icon":"cpu","rows":[["SoC","Apple A8"],["CPU","64-bit dual-core ARMv8-A Typhoon · 1.1 GHz"],["Coprocessor","Apple M8 motion"],["GPU","PowerVR Series 6XT GX6450 (quad-core)"],["RAM","1 GB LPDDR3"],["Graphics API","Metal"]]},{"title":"Display","icon":"monitor","rows":[["Type","LED-backlit IPS Retina"],["Size","4 inches diagonal"],["Resolution","1136×640 · 326 ppi"],["Aspect ratio","16:9"],["Contrast","800:1 (typical)"],["Brightness","500 cd/m² max"],["Coating","Fingerprint-resistant oleophobic"]]},{"title":"Storage","icon":"hard-drive","rows":[["Tiers","16 · 32 · 64 · 128 GB"],["Type","Flash memory"],["Top tier","128 GB — first on the line"]]},{"title":"Connectivity","icon":"radio","rows":[["Wi-Fi","802.11a/b/g/n/ac"],["Bluetooth","4.1"],["Connector","Lightning"],["AirPlay","Mirroring + video out to Apple TV"],["Siri","Yes"]]},{"title":"Camera & sensors","icon":"camera","rows":[["Rear camera","8 MP iSight · LED flash · 1080p @ 30fps"],["Front camera","1.2 MP FaceTime HD · 720p"],["Video out","Up to 1080p via Lightning AV adapter"],["Sensors","3-axis gyroscope · accelerometer · M8"]]},{"title":"Physical","icon":"smartphone","rows":[["Height","123.4 mm"],["Width","58.6 mm"],["Depth","6.1 mm"],["Weight","88 g (3.1 oz)"],["Rear casing","Anodised aluminum unibody"],["Colors","Space Gray · Silver · Gold · Pink · Blue · (PRODUCT)RED"]]},{"title":"Power","icon":"zap","rows":[["Battery","Built-in Li-ion"],["Audio","Up to 40 hours"],["Video","Up to 8 hours"],["Charging","Lightning"],["In box","EarPods (no remote/mic) · USB 2.0 Lightning cable"]]},{"title":"Software","icon":"layers","rows":[["Shipped with","iOS 8.4"],["Final version","iOS 12.5.8"],["Major versions","iOS 8 · 9 · 10 · 11 · 12 (full)"],["Excluded from","iOS 13 — superseded by A10 7th gen"]]}]}'::jsonb)
) as v(wiki_id, page_id, position, component, data)
where not exists (select 1 from public.sections s
  where s.wiki_id = 'apple' and s.page_id = 'apple-ipod-touch-6g');

-- ── apple / apple-ipod-touch-7g (11 sections) ──
insert into public.pages (wiki_id, id, slug, title, type) values
  ('apple', 'apple-ipod-touch-7g', 'apple-ipod-touch-7g.html', 'iPod touch (7th gen)', 'standard')
on conflict (wiki_id, id) do update set slug = excluded.slug, title = excluded.title, type = excluded.type;
insert into public.sections (wiki_id, page_id, position, component, data)
select * from (values
  ('apple', 'apple-ipod-touch-7g', 0, 'hero', '{"eyebrow":"iPod touch · 7th Generation · 2019 – 2022","title":"iPod touch","subtitle":"(7th generation)","subtitle_meta":"Model A2178","desc":"Four years after the 6G, the seventh and final iPod touch arrived with the <strong>Apple A10 Fusion</strong> — the iPhone 7 chip — paired with <strong>2 GB of RAM</strong> and a new <strong>256 GB</strong> top tier, the largest storage ever offered on an iPod. Externally it was indistinguishable from the 6G it replaced. It added support for <strong>Group FaceTime</strong> and <strong>augmented reality</strong>, became one of the launch devices for <strong>Apple Arcade</strong>, and on May 10, 2022 closed the book on a product line that had run for twenty-one years.","stats":[{"num":"6","label":"Launch colors"},{"num":"256 GB","label":"New top tier"},{"num":"2 GB","label":"RAM"},{"num":"A10","label":"iPhone 7 chip"}],"search":false,"search_placeholder":null,"spotlight":null,"feature":null}'::jsonb),
  ('apple', 'apple-ipod-touch-7g', 1, 'overview', '{"tone":"a","heading":"The final iPod — built around the iPhone 7''s chip.","paragraphs":["The seventh generation iPod touch was released on May 28, 2019, through the online Apple Store. Like the 6G four years earlier, it was a quiet press-release launch rather than a stage moment — but it carried the same model designation lineage, the same Foxconn manufacturing, and a successor''s part number: A2178, firmware identifier iPod9,1.","The headline, as in 2015, was the processor. Apple swapped the 6G''s A8 for the 64-bit A10 Fusion — the same chip that drove the iPhone 7 and 7 Plus in 2016 — paired with the M10 motion coprocessor. RAM doubled again, to 2 GB of LPDDR4. The PowerVR GT7600 Plus delivered Apple''s claim of three times faster graphics. The 7G also became the first iPod to support immersive augmented reality, Group FaceTime, and (later that fall) Apple Arcade — the streaming game service that arrived in September 2019.","The six colors carried over from the 6G unchanged: space gray, silver, gold, pink, blue, and (PRODUCT)RED. The aluminum unibody was identical down to the millimetre — same 6.1 mm depth, same 88 g weight, same 4-inch Retina display at 1136×640. Anyone holding a 6G and a 7G side by side could not distinguish them externally. The only way to tell was to look at the chip identifier in Settings.","Storage tiers were where the 7G made its other real move: 32, 128, and 256 GB at $199, $299, and $399. The 256 GB option was new — the largest capacity any iPod had ever offered, and a deliberate appeal to music libraries kept locally rather than streamed. The device shipped with iOS 12.3, released the same day, May 28, 2019.","Three years later, on May 10, 2022, Apple announced the iPod touch would be sold while supplies last. The accompanying press release, titled \"The music lives on,\" framed the discontinuation as a victory rather than an ending: the iPod''s role had been fully absorbed into the iPhone, Apple Watch, HomePod, and Apple Music. Stock sold out within days. The 7G was the last iPod ever made — closing a product line that had launched on October 23, 2001 with the original click-wheel model. Apple has continued shipping iOS 15 security updates: the most recent, iOS 15.8.7, arrived on March 11, 2026."],"infobox":{"label":null,"title":"iPod touch","sublabel":null,"rows":[["Model","A2178"],["EMC","3330"],["Developer","Apple Inc."],["Manufacturer","Foxconn"],["Generation","7th of 7 · final"],["Released","May 28, 2019"],["Discontinued","May 10, 2022"],["Predecessor","iPod touch (6th gen)"],["Successor","None — line ended"],["Board","N112AP · iPod9,1"],["OS at launch","iOS 12.3"],["Max OS","iOS 15.8.7"],["Processor","Apple A10 Fusion · dual-core 1.64 GHz"],["Coprocessor","Apple M10 motion"],["GPU","PowerVR GT7600 Plus (hexa-core)"],["RAM","2 GB LPDDR4"],["Storage","32 · 128 · 256 GB"],["Display","4-inch Retina · 1136×640 · 326 ppi"],["Rear camera","8 MP · LED flash · 1080p"],["Front camera","1.2 MP FaceTime HD · 720p"],["Connector","Lightning · 3.5 mm headphone jack"],["Wi-Fi","802.11a/b/g/n/ac"],["Bluetooth","4.1"],["Dimensions","123.4 × 58.6 × 6.1 mm"],["Weight","88 g (3.1 oz)"],["Colors","Space Gray · Silver · Gold · Pink · Blue · (PRODUCT)RED"],["Battery","~40 hrs audio · 8 hrs video"],["Price","$199 · $299 · $399"]],"badge":"Discontinued · May 2022"}}'::jsonb),
  ('apple', 'apple-ipod-touch-7g', 2, 'photo-rail', '{"photos":[{"src":"https://www.apple.com/newsroom/images/product/ipod/standard/new-apple-ipodtouch-06032019_big.jpg.large.jpg","alt":"iPod touch 7G family — all six colors","strong":"All six colors","source":"· Apple Newsroom · May 2019"},{"src":"https://www.apple.com/newsroom/images/product/ipod/standard/Apple-iPod-end-of-life-hero_inline.jpg.large.jpg","alt":"iPod touch 7G end of life hero shot","strong":"The music lives on","source":"· Apple Newsroom · May 2022"},{"src":"https://i.ebayimg.com/images/g/8ngAAOSwZOVoV7s2/s-l1600.jpg","alt":"iPod touch 7G boxed product","strong":"Sealed retail","source":"· eBay"},{"src":"https://i.ebayimg.com/images/g/kRIAAeSwLnposI6B/s-l1600.jpg","alt":"iPod touch 7G space gray detail","strong":"Space Gray · A2178","source":"· eBay"},{"src":"https://i.ebayimg.com/images/g/afoAAOSwyG9lXbTg/s-l1600.jpg","alt":"iPod touch 7G in hand","strong":"In hand","source":"· eBay listing"},{"src":"https://i.ebayimg.com/images/g/mfsAAOSw2OplXbUd/s-l1600.jpg","alt":"iPod touch 7G color comparison","strong":"Color lineup","source":"· eBay"}]}'::jsonb),
  ('apple', 'apple-ipod-touch-7g', 3, 'timeline', '{"heading":"One chip jump. Three years. The end of the iPod.","visual":"timeline","events":[{"month":"May","day":"28","year":"2019","tag":"Launch","title":"iPod touch 7G released.","preview":"Apple A10 Fusion. 2 GB RAM. New 256 GB top tier. Quiet press-release launch, $199 to start.","body":"<p>Apple released the 7th generation iPod touch through its online store on May 28, 2019 — the first major update in nearly four years. It carried the 64-bit Apple A10 Fusion processor (the iPhone 7''s chip, underclocked to 1.64 GHz), the M10 motion coprocessor, 2 GB of RAM, and the same 4-inch Retina display, 8 MP rear camera, 1.2 MP front camera, and aluminum body as the 6G.</p><p>It launched in space gray, silver, gold, pink, blue, and (PRODUCT)RED — the same six colors as the previous generation — in 32, 128, and 256 GB tiers at $199, $299, and $399. The 256 GB tier was new, the largest capacity any iPod had ever offered. The 16 GB and 64 GB tiers from the 6G era were retired.</p>"},{"month":"May","day":"28","year":"2019","tag":"Software","title":"Ships with iOS 12.3, adds Group FaceTime and AR.","preview":"First iPod to support Group FaceTime and ARKit. iOS 12.3 also ships the redesigned Apple Music app.","body":"<p>The 7G shipped with iOS 12.3, released the same day. That version introduced the redesigned Apple Music app with a refreshed Browse tab, and the device was Apple''s first iPod to support Group FaceTime (multi-party video calls) and ARKit (augmented reality experiences). Both capabilities had launched on iPhone in 2018 (iOS 12) but required at minimum an A9 chip — too new for the A8-based 6G.</p>"},{"month":"Sep","day":"19","year":"2019","tag":"Software","title":"iOS 13 — first iPod ever to run it.","preview":"iOS 13 dropped every A9 and earlier device. The 7G was the only iPod to make the cut.","body":"<p>iOS 13 shipped in September 2019, and the 7G was the only iPod ever to receive it. The release dropped all A8 hardware (cutting off the 6G) and required A9 or newer; the 7G''s A10 cleared the bar comfortably. iOS 13 brought Dark Mode, Sign in with Apple, and a redesigned Reminders app, and the 7G handled all of it without compromise.</p>"},{"month":"Sep","day":"19","year":"2019","tag":"Software","title":"Apple Arcade launches.","preview":"Apple''s $4.99/month gaming subscription goes live. The 7G is positioned as the cheapest device that can run it.","body":"<p>Apple Arcade — the $4.99/month gaming service Apple had previewed at the 7G''s launch in May — went live on September 19, 2019. Over 100 exclusive games, no ads, no in-app purchases, offline play. At $199, the 7G was by a wide margin the most affordable iOS device that could meaningfully run the Arcade catalog, and Apple marketed it that way. For many families, the 7G became the de facto Arcade machine: cheap enough to buy as a second device, powerful enough to actually play the games.</p>"},{"month":"Sep","year":"2020","tag":"Software","title":"iOS 14 — full support.","preview":"Home screen widgets, App Library, picture-in-picture. The 7G handled it all.","body":"<p>iOS 14 (September 2020) brought widgets to the iOS home screen for the first time, plus the App Library, picture-in-picture, and significant Messages and Maps updates. The 7G ran it without compromise — by now the only iPod still supported by current iOS.</p>"},{"month":"Sep","year":"2021","tag":"Software","title":"iOS 15 — the last major version.","preview":"Focus modes, SharePlay, Live Text. The final iOS version any iPod will ever run.","body":"<p>iOS 15 (September 2021) shipped to the 7G as the last major version it — or any iPod — would ever receive. Features included Focus modes, SharePlay over FaceTime, Live Text in the camera, and a redesigned Safari. The 7G was at this point a four-year-old device but still benchmarked respectably for its class and ran iOS 15 smoothly on its 2 GB of RAM.</p>"},{"month":"May","day":"10","year":"2022","tag":"Hardware","title":"Discontinued — end of the iPod line.","preview":"Apple announces the 7G will be sold while supplies last. The 21-year iPod product line ends.","body":"<p>On May 10, 2022, Apple published a press release titled \"The music lives on\" announcing the iPod touch would be sold only while supplies last. There was no successor. The iPod line — which had begun on October 23, 2001 with the original click-wheel model and run for 21 years through Classic, mini, nano, shuffle, and seven generations of touch — was ending. Apple framed it as a victory: the iPod''s role had been fully absorbed into iPhone, Apple Watch, HomePod, iPad, Mac, and Apple Music.</p><p>Greg Joswiak, Apple''s senior vice president of Worldwide Marketing: \"Music has always been part of our core at Apple, and bringing it to hundreds of millions of users in the way iPod did impacted more than just the music industry — it also redefined how music is discovered, listened to, and shared.\"</p>"},{"month":"May","day":"12","year":"2022","tag":"Hardware","title":"256 GB models sell out within 48 hours.","preview":"A day after the discontinuation announcement, every 256 GB color sells out on Apple''s US store.","body":"<p>Within roughly two days of the discontinuation announcement, the 256 GB iPod touch had sold out in every color on the US Apple Store. Other capacities followed within the week. Resale prices on eBay briefly spiked above the original $399 MSRP as buyers competed for the last new-in-box units. The 7G — and the iPod line — was effectively gone from Apple''s first-party inventory within days, not the weeks or months ''while supplies last'' usually implies.</p>"},{"month":"Sep","year":"2022","tag":"Software","title":"iOS 16 — excluded.","preview":"iOS 16 drops the A10 generation. iPhone 7, 7 Plus, and the 7G fall off the list together.","body":"<p>iOS 16 (September 2022) raised the minimum supported chip to A11. The iPhone 7, iPhone 7 Plus, and 7G — all A10 Fusion devices — fell off the support list in the same release. The 7G stayed on iOS 15 as its final major version, definitively ending iPod''s run on current iOS.</p>"},{"month":"Mar","day":"11","year":"2026","tag":"Software","title":"iOS 15.8.7 — latest security update.","preview":"Nearly four years after discontinuation, the 7G is still receiving security patches from Apple.","body":"<p>iOS 15.8.7, released March 11, 2026, was the most recent iOS update available to the 7G at time of writing — nearly four years after Apple discontinued the iPod line and over six years after the device launched. The release was a maintenance update rather than a feature one, but it kept iMessage, FaceTime, App Store, and device activation working. For an A10-based device with no successor and no commercial reason to maintain support, the continued security patches were a quietly generous extension of an already-long support tail.</p>"}]}'::jsonb),
  ('apple', 'apple-ipod-touch-7g', 4, 'delta', '{"heading":"What changed.<br>6th &#8594; 7th generation.","intro":"The sixth-to-seventh transition was the smallest visible change in the line''s history. Externally, the two devices were indistinguishable: same chassis, same colors, same connectors, same dimensions, same screen. Apple poured the entire upgrade into the chip and memory. The A8 became the A10 Fusion. RAM doubled. The top storage tier doubled. iOS jumped from 8.4 to 12.3 at launch. And the line gained AR support and Group FaceTime — the last new capabilities the iPod would ever receive.","footnote":"Specs: iPod touch 6th gen (A1574) · Jul 15, 2015 &nbsp;/&nbsp; iPod touch 7th gen (A2178) · May 28, 2019","prev":{"name":"iPod touch (6th gen)","year":"July 2015"},"current":{"name":"iPod touch (7th gen)","year":"May 2019"},"hardware":[{"label":"Processor","old":"A8 · dual-core 1.1 GHz · 64-bit","new":"<strong>A10 Fusion · dual-core 1.64 GHz · 64-bit</strong> — the iPhone 7 chip","chip":"better","chip_text":"A10"},{"label":"RAM","old":"1 GB LPDDR3","new":"<strong>2 GB LPDDR4</strong> — doubled, faster spec","chip":"better","chip_text":"2×"},{"label":"Motion coprocessor","old":"M8","new":"<strong>M10</strong>","chip":"better","chip_text":"M10"},{"label":"GPU","old":"PowerVR GX6450 (quad-core)","new":"<strong>PowerVR GT7600 Plus</strong> — hexa-core, ~3× graphics","chip":"better","chip_text":"3× gfx"},{"label":"Max storage","old":"128 GB","new":"<strong>256 GB</strong> — largest ever on iPod","chip":"better","chip_text":"256 GB"},{"label":"AR capability","old":"Not supported","new":"<strong>ARKit supported</strong> — first iPod","chip":"feature","chip_text":"AR"},{"label":"Group FaceTime","old":"Not supported","new":"<strong>Supported</strong> — first iPod","chip":"better","chip_text":"+ Group"},{"label":"HEIF / HEVC","old":"Not supported","new":"<strong>Supported</strong> — A10 capability","chip":"feature","chip_text":"HEIF"},{"label":"Chassis","old":"6.1 mm aluminum unibody","new":"<strong>Unchanged</strong> — same body, same six colors","chip":"same","chip_text":"Same"},{"label":"Display","old":"1136×640 · 326 ppi","new":"<strong>Unchanged</strong> — same panel since 2012","chip":"same","chip_text":"Same"},{"label":"Cameras","old":"8 MP rear · 1.2 MP front","new":"<strong>Unchanged</strong> — same modules as 6G","chip":"same","chip_text":"Same"}],"software":[{"label":"OS at launch","old":"iOS 8.4","new":"<strong>iOS 12.3</strong> — Group FaceTime, Screen Time","chip":"better","chip_text":"iOS 12.3"},{"label":"Final OS","old":"iOS 12.5.8 (2026)","new":"<strong>iOS 15.8.7 (2026)</strong> — three versions ahead","chip":"better","chip_text":"iOS 15"}]}'::jsonb),
  ('apple', 'apple-ipod-touch-7g', 5, 'config', '{"heading":"Six colors. Three tiers. The first 256 GB iPod.","visual":"config","chart_title":"Storage configurations and launch pricing","intro":["The seventh generation iPod touch launched with three capacities — 32, 128, and 256 GB — at $199, $299, and $399. The 16 GB and 64 GB tiers of the 6G era were retired, raising the floor to 32 GB and adding a new 256 GB ceiling. All three tiers shared identical hardware and were available across the full six-color palette.","The 256 GB option was a milestone: the largest capacity any iPod had ever offered, and one of the highest-storage iOS devices of its era at the $399 price point. Apple positioned it explicitly toward local music libraries — a quiet acknowledgment that the iPod touch was still, fundamentally, a music player."],"footer":"A2178: Apple A10 Fusion · M10 coprocessor · 2 GB RAM · 4&Prime; Retina 1136&times;640 · 8 MP + 1.2 MP cameras · Lightning · 6.1 mm · 802.11ac Wi-Fi · BT 4.1","items":[{"capacity":32,"unit":"GB","model":"A2178 · MVHV2LL/A","price":"$199","dates":"May 2019 &ndash; May 2022","colors":[{"name":"Space Gray","hex":"#4a4a4f"},{"name":"Silver","hex":"#d8d8dc","ring":true},{"name":"Gold","hex":"#e8d3a8"},{"name":"Pink","hex":"#f472b6"},{"name":"Blue","hex":"#60a5fa"},{"name":"(RED)","hex":"#e3001b"}]},{"capacity":128,"unit":"GB","model":"A2178 · MVJ02LL/A","price":"$299","dates":"May 2019 &ndash; May 2022","colors":[{"name":"Space Gray","hex":"#4a4a4f"},{"name":"Silver","hex":"#d8d8dc","ring":true},{"name":"Gold","hex":"#e8d3a8"},{"name":"Pink","hex":"#f472b6"},{"name":"Blue","hex":"#60a5fa"},{"name":"(RED)","hex":"#e3001b"}]},{"capacity":256,"unit":"GB","model":"A2178 · MVJD2LL/A","price":"$399","dates":"May 2019 &ndash; May 2022","colors":[{"name":"Space Gray","hex":"#4a4a4f"},{"name":"Silver","hex":"#d8d8dc","ring":true},{"name":"Gold","hex":"#e8d3a8"},{"name":"Pink","hex":"#f472b6"},{"name":"Blue","hex":"#60a5fa"},{"name":"(RED)","hex":"#e3001b"}]}]}'::jsonb),
  ('apple', 'apple-ipod-touch-7g', 6, 'prose-rail', '{"eyebrow":"Cultural impact","icon":"gamepad-2","anchor":"gaming-section","heading":"Apple Arcade''s perfect target device — and a streaming-era music player.","body":[{"text":"The 7G''s timing was almost suspicious. It launched in May 2019, four months before Apple Arcade — Apple''s $4.99/month gaming subscription — went live in September. With the A10 Fusion, the 7G could run Arcade''s titles smoothly at full fidelity. For $199 it was, by a wide margin, the cheapest device that could meaningfully participate in Apple''s new gaming push. Apple marketed it that way explicitly, leading the 2019 press release with \"the ultra-thin and lightweight design of iPod touch has always made it ideal for enjoying games.\""},{"text":"The graphics jump from the 6G was real. The PowerVR GT7600 Plus delivered roughly three times the graphics performance of the 6G''s GX6450, and the A10''s 64-bit cores kept the device compatible with new App Store releases right through iOS 15. Games like <strong>PUBG Mobile</strong>, <strong>Fortnite</strong> (briefly, before its 2020 removal), <strong>Asphalt 9: Legends</strong>, and the entire Arcade lineup ran at playable frame rates on the 4-inch screen."},{"text":"Music had also fully shifted to streaming by 2019. The 7G shipped with iOS 12.3, which was the launch version of the redesigned Apple Music app. The 256 GB top tier was a deliberate bet that some users still wanted their library on-device — for the gym, for flights, for places without coverage. Combined with the 7G''s retained 3.5 mm headphone jack (a port the iPhone had dropped three years earlier with the 7), it became the last default device for anyone who wanted plug-in wired headphones and offline music in one pocket-sized package."},{"text":"For a generation of kids in 2019, 2020, and 2021, the 7G was a first iOS device. Its $199 price, no-contract availability, and full iOS compatibility made it the natural step before parents handed over a real phone. It outlived two iPhone generations before Apple finally ended the line in 2022 — at which point a used 7G was, briefly, more expensive on eBay than it had been at retail."}],"rail":{"title":"Archive","photos":[{"src":"https://www.apple.com/newsroom/images/product/ipod/standard/ipodtouch-apple-arcade-screen-06032019_inline.jpg.large.jpg","alt":"iPod touch 7G running Apple Arcade","strong":"Apple Arcade","source":"· Apple · May 2019"},{"src":"https://www.apple.com/newsroom/images/product/ipod/standard/ipodtouch-blue-AR-screen-06032019_inline.jpg.large.jpg","alt":"iPod touch 7G with AR experience","strong":"AR on iPod","source":"· Apple · May 2019"},{"src":"https://www.apple.com/newsroom/images/product/ipod/standard/ipodtouch-black-applemusic-screen-06032019_inline.jpg.large.jpg","alt":"iPod touch 7G running Apple Music","strong":"Apple Music","source":"· Apple · May 2019"}]}}'::jsonb),
  ('apple', 'apple-ipod-touch-7g', 7, 'prose-rail', '{"eyebrow":"Industrial design","icon":"palette","anchor":"design-section","heading":"Unchanged from 2015 — and 2012 before that.","body":[{"text":"The seventh generation iPod touch''s industrial design was a complete carry-over from the 6G. 123.4 mm tall, 58.6 mm wide, 6.1 mm thin, 88 g. Anodised aluminum unibody. The same six colors — space gray, silver, gold, pink, blue, and (PRODUCT)RED — in the same finishes. Apple did not redesign a single externally visible element. By 2019, the iPod touch chassis had been on sale, essentially unchanged, since the 5G launched in September 2012. Seven years on the same body — a longer industrial-design run than any other major Apple product line of the era."},{"text":"The 4-inch Retina display at 1136×640 was likewise unchanged. By 2019 the iPhone XR shipped with a 6.1-inch display; the iPhone 11 was about to. The 7G''s screen looked tiny in 2019 photos — a deliberate concession to keeping the device pocketable and affordable, but also the most visible sign that the iPod touch had become a deliberate side path rather than a flagship."},{"text":"Two ports survived in 2019 that the iPhone had already abandoned. The 3.5 mm headphone jack remained on the bottom edge — Apple had removed it from the iPhone in 2016 with the iPhone 7. And the Lightning connector, while shared with the iPhone, sat alongside the jack rather than alone. For a music-focused device, those two ports together made the 7G the last default Apple device built around wired headphones."},{"text":"What had clearly NOT been carried into the 7G was every iPhone-defining feature introduced after the 6G''s 2015 launch: no Touch ID, no Face ID, no haptic engine, no NFC, no Apple Pay, no True Tone, no wide color gamut, no second rear camera, no portrait mode, no flash with True Tone, no force touch, no second-generation Lightning, no fast charge. The 7G was, by 2019 standards, the most feature-stripped current iOS device Apple sold."}],"rail":{"title":"Archive","photos":[{"src":"https://www.apple.com/newsroom/images/product/ipod/standard/new-apple-ipodtouch-06032019_big.jpg.large.jpg","alt":"iPod touch 7G family — all six colors front and back","strong":"All six finishes","source":"· Apple · May 2019"},{"src":"https://www.apple.com/newsroom/images/product/ipod/standard/Apple-iPod-end-of-life-hero_inline.jpg.large.jpg","alt":"iPod touch 7G end-of-life family shot","strong":"The final lineup","source":"· Apple · May 2022"},{"src":"https://i.ebayimg.com/images/g/Lg4AAeSwsJ9osI6B/s-l1600.jpg","alt":"iPod touch 7G space gray back, aluminum unibody","strong":"Aluminum back","source":"· eBay"},{"src":"https://i.ebayimg.com/images/g/Ma8AAeSwZ9losI6B/s-l1600.jpg","alt":"iPod touch 7G edge profile showing 6.1mm thickness","strong":"6.1 mm thin","source":"· eBay"}]}}'::jsonb),
  ('apple', 'apple-ipod-touch-7g', 8, 'lifecycle-lane', '{"heading":"Four major versions. Three iOS generations past discontinuation.","title":"Software lifecycle: iOS 12.3 through iOS 15.8.7","paragraphs":["The seventh generation iPod touch shipped with iOS 12.3 and received four major versions: iOS 12, 13, 14, and 15. The A10 Fusion and 2 GB of RAM gave it the headroom to clear each year''s update with room to spare — and notably, the 7G was the ONLY iPod ever to run iOS 13, iOS 14, and iOS 15 natively. Every earlier touch had been cut off before iOS 13 (which required at minimum an A9 chip).","The end of feature updates came with iOS 16 in 2022, which dropped the A10 generation entirely (iPhone 7, iPhone 7 Plus, and the 7G all fell off the support list together). By then Apple had already announced the iPod line was ending, so there was no successor to carry the touch forward. iOS 15 was, definitively, the last iOS version any iPod would ever run.","But the 7G has kept receiving security patches into 2026 — over six years after launch and nearly four years after discontinuation. iOS 15.8.7, released on March 11, 2026, was the most recent at time of writing. Each of these is a maintenance release rather than a feature update, but they keep iMessage, FaceTime, App Store, and device activation working. For an A10-based device, that''s a remarkably long support tail — and a graceful way for Apple to keep the final iPod alive in the field."],"segments":[{"ver":"12.3","date":"May 2019","type":"full","badge":"Launch","badge_type":"ship"},{"ver":"13.0","date":"Sep 2019","type":"full"},{"ver":"14.0","date":"Sep 2020","type":"full"},{"ver":"15.0","date":"Sep 2021","type":"full"},{"ver":"16.0","date":"Sep 2022","type":"dropped","badge":"Dropped","badge_type":"dropped"},{"ver":"15.8.7","date":"Mar 2026","type":"security","badge":"Security","badge_type":"security"}],"notes":[{"status":"full","label":"iOS 12–15","text":"Full support — four major versions. Only iPod ever to run iOS 13, 14, and 15 natively."},{"status":"full","label":"iOS 15","text":"Final major version any iPod will ever run. Released September 2021, before the line ended."},{"status":"dropped","label":"iOS 16","text":"Excluded — dropped the A10 generation entirely. iPhone 7 and 7 Plus fell off the same year."},{"status":"security","label":"iOS 15.8.7","text":"Post-EOL security patch — March 11, 2026. Nearly four years after Apple stopped selling, still maintained on iOS 15."}]}'::jsonb),
  ('apple', 'apple-ipod-touch-7g', 9, 'prose-rail', '{"eyebrow":"Controversies","icon":"scale","anchor":"controversies-section","heading":"Three things people questioned.","body":[{"icon":"alert-circle","subtitle":"The A10 was underclocked — again","text":"Apple pulled the same trick with the 7G that it had with the 6G. The A10 Fusion in the iPhone 7 ran at 2.34 GHz; in the 7G, it ran at 1.64 GHz — a roughly 30 percent reduction, attributed once again to the smaller battery and thermal envelope. Geekbench scores reflected the cut: the 7G benchmarked slower than the three-year-old iPhone 7 it borrowed its chip from, and slower than the A10-equipped iPad 7 of the same year. The marketing line was \"the A10 Fusion chip\" without qualification; the reality was a deliberately throttled implementation."},{"icon":"lock","subtitle":"No biometrics, no Apple Pay, in 2019","text":"By 2019 every other current iOS device had Touch ID, Face ID, or both, plus the NFC hardware needed for Apple Pay. The 7G had none of them. Unlock was a four- or six-digit passcode every time. There was no fingerprint sensor under the home button, no front-facing depth camera, no NFC chip on the back. For a $199 device aimed in part at younger users, the omissions were defensible cost decisions — but they also made the 7G the only current iOS device of 2019 that could not authenticate App Store purchases biometrically or make a contactless payment."},{"icon":"smartphone","subtitle":"A 2012 chassis sold in 2022","text":"When Apple discontinued the iPod touch in May 2022, the device on shelves was using a body design first introduced in September 2012 with the 5G. Same 4-inch screen, same dimensions, same general form factor — a chassis that had been in continuous production for nearly ten years and was still being sold new in the era of the iPhone 13 Pro Max. For some buyers it was a feature (familiarity, pocketability); for reviewers it was a sign that Apple had run the iPod line out gracefully rather than refreshed it. The 6G chassis had been a carryover; the 7G chassis was a near-decade-long victory lap."}],"rail":{"title":"Press archive","photos":[{"src":"https://www.apple.com/newsroom/images/product/ipod/standard/Apple-iPod-end-of-life-hero_inline.jpg.large.jpg","alt":"iPod touch 7G — the end-of-line family shot","strong":"End of line","source":"· Apple · May 2022"},{"src":"https://i.ebayimg.com/images/g/RQ4AAeSw-ulosI6B/s-l1600.jpg","alt":"iPod touch 7G home button and bezels","strong":"Pre-Touch ID home button","source":"· eBay"}]}}'::jsonb),
  ('apple', 'apple-ipod-touch-7g', 10, 'spec', '{"heading":"The complete sheet.","device":"iPod touch (7th generation) · A2178","cards":[{"title":"General Device Info","icon":"globe","rows":[["Model number","A2178"],["EMC","3330"],["Board","N112AP"],["Firmware ID","iPod9,1"],["Generation","7th of 7 · final"],["Manufacturer","Foxconn"],["Released","May 28, 2019"],["Discontinued","May 10, 2022 — end of iPod line"]]},{"title":"Processor & memory","icon":"cpu","rows":[["SoC","Apple A10 Fusion"],["CPU","64-bit dual-core ARMv8-A · 1.64 GHz (underclocked from iPhone 7''s 2.34 GHz)"],["Coprocessor","Apple M10 motion"],["GPU","PowerVR Series 7XT Plus GT7600 Plus (hexa-core)"],["RAM","2 GB LPDDR4"],["Graphics API","Metal 2"]]},{"title":"Display","icon":"monitor","rows":[["Type","LED-backlit IPS Retina"],["Size","4 inches diagonal"],["Resolution","1136×640 · 326 ppi"],["Aspect ratio","16:9"],["Contrast","800:1 (typical)"],["Brightness","500 cd/m² max"],["Coating","Fingerprint-resistant oleophobic"]]},{"title":"Storage","icon":"hard-drive","rows":[["Tiers","32 · 128 · 256 GB"],["Type","Flash memory"],["Top tier","256 GB — first and only iPod"],["Floor","32 GB — 16 GB tier retired"]]},{"title":"Connectivity","icon":"radio","rows":[["Wi-Fi","802.11a/b/g/n/ac"],["Bluetooth","4.1"],["Connector","Lightning"],["Headphone jack","3.5 mm — last iPod with one"],["AirPlay","Mirroring + video out to Apple TV"],["Siri","Yes"],["AR","ARKit supported (first iPod)"],["Group FaceTime","Yes (first iPod)"]]},{"title":"Camera & sensors","icon":"camera","rows":[["Rear camera","8 MP iSight · LED flash · 1080p @ 30fps · HEIF/HEVC"],["Front camera","1.2 MP FaceTime HD · 720p"],["Video out","Up to 1080p via Lightning AV adapter"],["Sensors","3-axis gyroscope · accelerometer · M10"],["Biometrics","None — no Touch ID, no Face ID"]]},{"title":"Physical","icon":"smartphone","rows":[["Height","123.4 mm (4.86 in)"],["Width","58.6 mm (2.31 in)"],["Depth","6.1 mm (0.24 in)"],["Weight","88 g (3.10 oz)"],["Rear casing","Anodised aluminum unibody"],["Colors","Space Gray · Silver · Gold · Pink · Blue · (PRODUCT)RED"]]},{"title":"Power","icon":"zap","rows":[["Battery","Built-in Li-ion"],["Audio","Up to 40 hours"],["Video","Up to 8 hours"],["Charging","Lightning"],["In box","EarPods (no remote/mic) · USB 2.0 Lightning cable"]]},{"title":"Software","icon":"layers","rows":[["Shipped with","iOS 12.3"],["Final version","iOS 15.8.7 (March 11, 2026)"],["Major versions","iOS 12 · 13 · 14 · 15 (full)"],["Excluded from","iOS 16 — A10 generation dropped"],["Unique to 7G","Only iPod ever to run iOS 13, 14, and 15 natively"]]}]}'::jsonb)
) as v(wiki_id, page_id, position, component, data)
where not exists (select 1 from public.sections s
  where s.wiki_id = 'apple' and s.page_id = 'apple-ipod-touch-7g');

-- ── one PUBLISHED revision per backfilled page (0004's pattern) ──
insert into public.revisions (wiki_id, page_id, doc, status, author_email, note)
select s.wiki_id, s.page_id,
  jsonb_build_object(
    'hero',     coalesce((select h.data from public.sections h where h.wiki_id = s.wiki_id and h.page_id = s.page_id and h.position = 0), '{}'::jsonb),
    'overview', coalesce((select o.data from public.sections o where o.wiki_id = s.wiki_id and o.page_id = s.page_id and o.position = 1), '{}'::jsonb),
    'sections', coalesce((select jsonb_agg(jsonb_build_object('type', b.component, 'data', b.data) order by b.position)
                          from public.sections b where b.wiki_id = s.wiki_id and b.page_id = s.page_id and b.position >= 2), '[]'::jsonb)
  ),
  'published', 'system', 'DBNATIVE backfill from the git-authored page'
from (select distinct wiki_id, page_id from public.sections) s
where not exists (select 1 from public.revisions r where r.wiki_id = s.wiki_id and r.page_id = s.page_id);

select set_config('vizi.publishing', '1', false);   -- the backfill may move the pointer
update public.pages p
set published_rev = (select max(r.id) from public.revisions r
                     where r.wiki_id = p.wiki_id and r.page_id = p.id and r.status = 'published')
where p.published_rev is null
  and exists (select 1 from public.sections s where s.wiki_id = p.wiki_id and s.page_id = p.id);
select set_config('vizi.publishing', '', false);
